window.CHAPTER_DATA["ch05"]={"id": "ch05", "num": 5, "part": "הקדמות וכללים - יום השבת - גדרי מלאכה - הוצאה - רשויות", "title": "רשויות", "paras": [{"s": "h2", "h": "רשויות"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"867\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">1\u003c/sup>\u003cspan class=\"ca\" data-c=\"867\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">מציאות מעשה הוצאה\u003c/span>"}, {"s": "p", "h": "והנה כאמור תנאי המציאות המגדירים את המעשה של מלאכת הוצאה תלויים בשלושה דברים בחפץ, במקום, ובהיות חפץ במקום, ורוב רובם של גדרי המלאכה מבחינת העושה והמעשה תלויים בגדרי מציאות אלו."}, {"s": "p", "h": "והנה גדרי מציאות חפץ ומקום, יהיו כמ\"ש כתבנו לעיל בגדרי מציאות של כל מעשה, הרי שהיחס בין שני דברים נוגע למשמעות חפץ במקום ומשמעות שניהם יחד ביחס לאדם."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"868\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">2\u003c/sup>\u003cspan class=\"ca\" data-c=\"868\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">וגדרי מקום חפצים האמורין במלאכת הוצאה הם גדרים הנוגעים למושג השימושי של מקום, ולא במשמעות מקום המוקדמת, אך יש בהם גדרים הנוגעים אף לזה.\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"869\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">3\u003c/sup>\u003cspan class=\"ca\" data-c=\"869\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">גדרי מקום\u003c/span>"}, {"s": "p", "h": "והנה המקום יבוא בכמה משמעויות, מציאותיות ושימושיות, ויהיו משמעויותיו המציאותיות של מושגי חפץ ומקום יסודו, והשימושיות בנויות על המשמעויות המציאותיות ועל כן נמצא גדריהם דומים."}, {"s": "h4", "h": "הגדרות מציאותיות"}, {"s": "h7", "h": "המקום והדבר"}, {"s": "p", "h": "והמשמעות הראשונה תהיה במשמעות הקיום עצמה, שאין דבר שאין לו מקום ומקומו של דבר קומו, כי קיום דבר תלוי בהיות לו מקום כהכנה למציאותו, ונבאר כי אין הכנה זו במשמעות קדימת מקום לפני היות הדבר, אלא שקיום הדבר מחוייב היות לו מקום, וזו משמעות קיומית. ואף שמשמעות זו אינה שייכת למקום חפץ, שהרי ביחס לגדר קיום הנ\"ל לא ימצא חשיבות מקום חפץ, שאין החפץ אחד בקיומו, אלא קיבוץ של דברים הקיימים לעצמם, וגדר מקום כקיום הוא ביחס אליהם, וע\"כ יהיה למשמעות זו שייכות ביחס לגדרי הוצאה במשמעות חפץ הנמצא במקום."}, {"s": "h7", "h": "החלל והחפץ"}, {"s": "p", "h": "המשמעות השניה של מקום חפץ היא חלל, החלל הוא מקום בלי היות חפץ שאינו סותר היות חפץ, ואף שיש קיום לדבר בלי החלל, אחר שיש חלל כולל הרי אין דבר שלא נמצא בחלל, ויהיה משמעות בחפץ כנמצא בחלל, והחלל שאינו מקום הוא אחיד ושווה ביחס לחפץ, ועל כן הוא כולל חפצים הנמצאים בו וזה שם מכיל, והחלל אחד לדברים רבים, וכיון אין חלק החלל המסוים שבו נמצא החפץ מקום של חפץ, אלא החפץ הוא שנמצא בתוך החלל שמכיל אותו, וזה יתווסף למשמעות הקודמת ויהיה חפץ מוכל במקום ונמצא בתוך החלל, ומשמעות כוללת זו תהיה גם ביחס למושגים השימושיים."}, {"s": "h7", "h": "הרשות והכלי"}, {"s": "p", "h": "המשמעות השלישית היא מקום חלל, והיינו, חלל שיש לו צורה, ויהיה בזה שני המשמעויות הקודמות, והיינו, שהחלל האמור לעיל הוא חלל אחיד שאין לו שייכות עם קיום הדבר, אך ביחס לדבר בעל צורה אין החלל אחד, והיינו, שהרי קיום הדבר במקום אינו נוגע לצורתו וא\"כ מה שאין שני דברים יכולים להתקיים בחלל אחד הוא ממגבלת החלל, וזה חלל שיש לו צורה, וע\"כ יהיה משמעות בחלל שמתאים לדבר, ויתווסף בדבר שנמצא בחלל שמתאים לו משמעות קיום כבעל צורה, וזה משמעות כלי, ובזה יהיה משמעות שהחלל מלא או ריק, ובמשמעות זו החפץ קיים במקום החלל ונמצא בתוך חלל המקום שהחלל הוא מקום ביחס להתאמתו, וחלל ביחס לקיומו, וזה רשות, וזה יתווסף למשמעות הקודמת שחפץ קיים במקומו ונמצא בתוך החלל ומתאים לרשותו, ואף משמעות זו קיימת בגדרי הוצאה וכנ\"ל."}, {"s": "p", "h": "מושג מקום כמקיים הוא בקיום אפשרי - הגדרת מקום ברוחב, אורך וגובה, בנפרד לכל צד "}, {"s": "p", "h": "הנה הרי רשויות דשבת ודיניהם הם דינים במקום, וכיון דאין לך קיום בלא מקום, הרי שאין במציאות חסרון במקום עצמו (שנאמר דמקום מסוים אינו מקום), וא\"כ בהכרח דכל דין הנוגע למקום לא יהיה גדר במקום כשלעצמו, אלא רק בחשיבותו אותו מקום ביחס לדבר אחר, היינו, היות המקום ראוי ומכון ועומד לדבר אחר."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"103\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">4\u003c/sup>\u003cspan class=\"ca\" data-c=\"103\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ויש להבחין כי עצם המושג מקום הרי הוא בכל קיום האפשרי, היינו, ברוחב ואורך וגובה כל אחד לבדו, וזה מוכרח מהיות דברים שאינם מרובעים ומעוקבים, דדבר דאורכו יתר על רוחבו הרי דמקומו יותר באורך מברוחב, כי אין מקום מגדרי חלל (דגדרו הוא במעוקב). וכיון שכן הרי דיש לנו לדון בגדרו של מקום בגדר נפרד לכל צדדיו, ואם נמצא שיעור הנוגע רק לאורכו הרי שגדר מקום שלו הוא רק באורך, וכן ברוחב וכו'.\u003c/span>"}, {"s": "p", "h": "שם מקום בשני מובנים נפרדים - מקום המאפשר קיום דברים ביחס לחפץ וביחס לשאר מקומות "}, {"s": "p", "h": "ויש להבחין כי שם מקום במשמעות שהוא דבר המאפשר קיום דברים יבוא בשני מובנים. האחד, ביחס לדברים הצריכים מקום, ויתכן שביחס לדבר אחד נחשב מקום, וביחס לשני לא, וזה גדר נפרד מעצם משמעות מקום, וכגון מה דקימ\"ל דאין מקום חשוב פחות מד\"ט על ד\"ט האמור ביחס לשטח, דביחס לגדר מקום עצמו באופן כללי כמאפשר קיום דברים, הרי שאין מקום שאינו ד\"ט על ד\"ט דהרי כל העולם הוא מקום, אלא מקום חשוב האמור הוא חשיבות ביחס להיותו מאפשר קיום דברים מסוימים או סוג מסוים של קיום, ובמקום ד\"ט שכמש\"כ במק\"א שגדר חשיבותו הוא ביחס לקיום דבר ארעי, וביחס לקיום דבר לאורך זמן, וע\"כ בעינן מקום שיש לו קרקע המאפשר קיום לאורך זמן, וזה גדר מקום הינוח, שאף שודאי שגם אוויר חשוב מקום, אנן בעינן מקום קיום לאורך זמן. וביחס לדבר ארעי, שיהיה המקום מאפשר קיום לדבר שהיותו במקום אינו חלק מקיום המקום כדבר המאפשר קיום לאורך זמן, אלא גדר היותו במקום שהוא נח, וזה ימעט דברים שהם בגדר קיום המקום לאורך זמן. וזה איכא למילף מהגדרת המעשה האסור שהוא לא להוציא דבר ממקום למקום, שיש למצוא בזה הכרח שיש מקומות חלוקים ואין כל המקום אחד, והכרח שאין היות הדבר המוצא בגדרי המקום. שחלוקת מקום ממקום וגדר מקום עצמו נעשה ע\"י דבר שאינו בגדרי הדבר המוצא, וזה גדר קרקע דמקום, שבזה יהיה המקום חשוב קבוע ביחס לחפץ, שהוא עשוי לנוע ולנוח והיא עשויה לאורך זמן, ובלא כן הרי בהינוח החפץ ישתנה המקום, ואין זה הוצאה אלא יצירת מקום חדש."}, {"s": "p", "h": "נפרדות גדרי מקום מגדר רשות - גדרי היות דברים במקומות אינם מענייני רשויות שבת "}, {"s": "p", "h": "והבן כי גדרים אלו אינם מענייני רשויות כלל, אלא להיות דברים במקומות באופן כללי, והיינו, שאין צורך לדבר ע\"מ שיחשב מונח יותר מכדי הנחתו, היינו, מקום בגודל הראוי לקיימו שם. וכיון שאין מנוחה אלא על דבר, הרי שאין גדר הינוח נוגע אלא למשטח, ועל כן יהיו גדרי הינוח ביחס לפני שטחו ללא שיעור, היינו, שאחר שאנו צריכים לגדר העברת דבר ממקום למקום הכרחנו גדר מקום בנפרד, וגדר הוצאה בנפרד, היינו, יוצא ממקום. ושיעור ד\"ט אינו חלק מהגדרה זו. וע\"כ בהכרח דשיעור ד\"ט אינו במקום, דאין מקום אלא לדבר, ולכן אין למצוא חסרון במקום עצמו אלא אי היותו."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"104\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">5\u003c/sup>\u003cspan class=\"ca\" data-c=\"104\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וזה גדר כל שיעור שהוא אורך על רוחב שמקורו באורך או ברוחב לבד, וכנ\"ל. וכמו שמצאנו דינים הנוגעים לשטח בלי גדר עובי, היינו, רק ביחס לאורכו ורוחבו, וזה פשר שיעור ד\"ט על ד\"ט שהוא שיעור בשטח מאוזן ואנכי באותו משמעות, שהרי שיעורו הוא אפילו ביחס לאורך לבד, ואף אחר ששיערנו בו שטח, נשאר גדרו כשיעור נפרד לאורך ורוחב. וכן לגבי מקום בעל עובי. ודו\"ק.\u003c/span>"}, {"s": "h4", "h": "הגדרות שימושיות"}, {"s": "p", "h": "ואחר הגדרות אלו יבואו המשמעויות השימושיות של מקום, והיינו, שכיון שאדם נמצא במקום ומשתמש בו ומשתמש בחפצים ומניח חפצים בין שימוש לשימוש ע\"כ יהיה משמעות לחפצים ביחס למקום וההיפך וכל האמור למעלה שייך גם באדם בגדרי מציאות."}, {"s": "h7", "h": "קירבה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"105\" style=\"--a:#dc2626;--abg:rgba(220,38,38,0.1)\">6\u003c/sup>\u003cspan class=\"ca\" data-c=\"105\" style=\"--a:#dc2626;--abg:rgba(220,38,38,0.1)\">המשמעות הראשונה הוא משמעות של קירבה שאדם משתמש בדברים כקירוב, והדוגמא הפשוטה היא אכילה, היינו, שימלא האוכל את תוכו במקום גרונו או מעיו, ובמשמעות זו האדם עצמו הוא מקום, וביחס לשימוש אדם משמעות זו היא משמעות קירוב ביחס לריחוק, וחיבור ביחס לניתוק במובן חיציו, והיא תחילת משמעות שימוש במקום אצל אדם. \u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"872\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">9\u003c/sup>\u003csup class=\"cb\" data-c=\"871\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">8\u003c/sup>\u003csup class=\"cb\" data-c=\"870\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">7\u003c/sup>\u003cspan class=\"ca\" data-c=\"870 871 872\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">מנוחה\u003c/span>"}, {"s": "p", "h": "המשמעות השניה היא שימוש אדם במקום כמקום שלו, והיינו, מה שיצטרך האדם מקום להנחת עצמו, ובמשמעות זו המקום מקיים את האדם בבין תנועה לתנועה ע\"י שמאפשר הנחה, וזה גדר מקום במשמעות המציאותית הראשונה וביחס לשימוש, ומבחינה שימושית יהיה זה שיעור מקום שימוש."}, {"s": "h7", "h": "ישיבה"}, {"s": "p", "h": "המשמעות הנ\"ל תבוא גם ביחס לשימוש קבוע יותר, כמו מי שחונה במקום, ויהיה בזה תוספת משמעות במה שהמקום משמש אותו לשאר צרכים הנצרכים לשהות ארוכה, וזה קרוי בכל מקום ישיבה, וגם זה גדר מקום במשמעות המציאותית הראשונה וביחס לשימוש קבוע יותר, ומבחינה שימושית יהיה זה שיעור מקום ישיבה."}, {"s": "h7", "h": "חלל שימוש"}, {"s": "p", "h": "המשמעות השלישית היא משמעות שימוש אדם בחפץ במקום, והיינו, שאדם המשתמש בכלי צריך שהכלי יהיה אתו באותו המקום, וצריך שיהיה מקום לכלי, וזו משמעות של מקום של חפץ ביחס לשימושו, שיהיו יחד בתוך אותו המקום הכולל מקום אדם ומקום שימוש בחפץ שהוא מקום האדם כמשתמש, ומקום זה כיון שהוא מתייחס לשימוש אדם ושימוש חפץ משמעותו מקום שכולל שתי מקומות וזה גדר חלל כמו במשמעות המציאותית הראשונה. "}, {"s": "h7", "h": "מקום הינוח"}, {"s": "p", "h": "המשמעות הרביעית הוא שימוש אדם במקום ע\"י הנחת חפץ, היינו, שיש לאדם מעלה שימושית בזה שיהיה לחפץ מקום, גם בלי השייכות לשימוש בפועל, אלא שיהיה מוכן לשימושו שיוכל לקחתו לכשיצטרך (וזה כמו משמעות בעלות), ובזה יהיה משמעות למקום שיהיה ראוי להעמיד חפץ ואין משמעות זו ביחס לחפץ אלא באדם ביחס למקום שרוצה את החפץ לשימוש ואת המקום לשימוש זה וזה משמעות מקום כרשות ביחס לחפץ, ויהיה לזה שיעור נפרד משיעור מקום שימוש אדם לעצמו שמבחינה שימושית יהיה זה שיעור מקום שימוש אדם לצורך הנחת חפץ במקום, וכן יהיה משמעות שימוש אדם במקום לצורך הכנת חפץ שהמקום יניח את החפץ, שצריך שיהיה צורת המקום ראויה להנחת חפץ, והיינו, שאין משמעות ההנחה בחפץ עצמו שאין לחפץ משמעות שימושית עצמית בהיותו במקום זה שזה כבר משמעות שימושו ולא מקומו, אלא המשמעות היא ביחס לאדם שהחפץ מוכן לו והיא משמעות שימוש במקום."}, {"s": "p", "h": "עד כאן אלו משמעויות בשימוש במקום בפועל והם כמו מושג המקום במשמעות המציאותית שמקיים את הדבר, ובמשמעות השימושית הוא מקיים את השימוש, ומעתה יבואו המשמעויות של יעוד שימוש במקום, והם כמו מושג החלל במשמעות המציאותית שמכיל את הדבר, ובמשמעות השימושית שהוא מכיל את השימוש."}, {"s": "h7", "h": "מקום המוכן לשימוש "}, {"s": "p", "h": "המשמעות החמישית הוא משמעות מקום כמוכן לשימוש, והיינו, שיש לאדם צורך שיהיו לו מקומות המיוחדים לשימוש ושלא ישמשו לדברים אחרים הנוגדים את השימוש המסוים שרוצה בו, ומשמעות זו היא כפולה שביחס לשאר מקומות שאינם מיוחדים יחוד זה הוא כמו מקום המקיים שאמרנו שהרי הוא מקיים את מוכנות השימוש אך ביחס לשימוש במקום עצמו אין זה מקום השימוש, אלא מוכנות לשימוש, ובמובן הזה יש לו משמעות חלל שהיא מאפשרת שימוש, וזה המושג רשות שימוש שהיא מקום מבחינת היותה מוכנה לשימוש והיא חלל ביחס לשימוש עצמו, וכיון שכך אין לזה שייכות למשמעות השניה והשלישית ששימוש אדם במקום יהיה ביחס לאדם, ושימוש אדם של חפץ במקום יהיה רשות החפץ והחפץ שיהיה מוכן."}, {"s": "h7", "h": "רשות"}, {"s": "p", "h": "המשמעות השישית היא יעוד שימוש במקום כמוכן לשימוש מרובה מקומות, והיינו, שיש לאדם צורך שיהיה לו מקום הכולל מקומות רבים המאוחדים לשימוש מסוג מסוים, ומשמעות זו היא כמו הקודמת לה אך כיון שהיא מתייחסת למקומות רבים כחלקים של מקום כולל יהיה בה משמעות שונה לכלל והפרט שהמקום הכולל לא יהיה לו משמעות מקום אלא משמעות חלל אך למקומותיו כנפרדים יהיה משמעות מקום שימוש והיא הרשות השלימה, ועל כן לא יהיה גדר המקום הכולל בגדרי מקום שימוש אדם או מקום שימוש חפץ אלא בגדרי השימוש המסוים שלו נדרשת הכללת המקומות."}, {"s": "h7", "h": "רשות מקום"}, {"s": "p", "h": "המשמעות השביעית הוא יעוד השימוש במקומות הרשות הנפרדים ביחס לשימוש שאליו הרשות מוכנה, ומשמעות זו היא המשמעות החמישית והשישית יחד, והיינו, שהמשמעות החמישית התייחסה למקום מסוים כמוכן לשימוש, והמשמעות השישית כמאחדת מקומות רבים ומיועדת לשימוש מסוים, והמשמעות השביעית היא המשמעות החמישית ביחס לשישית."}, {"s": "p", "h": "גדרים חלוקים במקום, חלל ורשות ובחפץ - חלל כשלעצמו, מקום כמאפשר קיום, ורשות לדבר מסוים "}, {"s": "p", "h": "וביתר ביאור כי מצאנו בדינים אלו שלושה גדרים במקום, חלל, מקום, ורשות. שם חלל הוא משמעות מקום כדבר שלעצמו (לעומת חומר), וכיון שגדר זה הוא ביחס למה שאינו חלל, הרי שאין חשיבותו נובעת מדברים הנמצאים בו או שיתכנו להימצאות בו, וע\"כ אין הוא חלוק או מוגדר לפי יכולתו להכיל איזה דבר ויהיה כולו אחיד, וגדריו ביחס לשאר חללים בגבול גודל וצורה. שם מקום הוא משמעות החלל כמאפשר קיום דברים, ויהיו הדברים קודמים לו וחשיבותו נובעת מהם, ויהיה חלוק ביחס לרוב אפשרויות שיש בו להכיל סתם דבר, שכיון שדברים נפרדים מטבעם, גם החלל שחשיבותו היא ביחס לדברים יחשב מחולק. שם רשות הוא ביחס לדבר המסוים שנמצא בו. שדברים נפרדים נחשבים גם לשונים אחד מהשני מעצם הפרדתם, וע\"כ גם גדר מקום שביחס אליהם יחשב נפרד משאר מקומות, וזה רשות. וע\"כ ביחס לחפץ האמור יהיה שלוש הגדרות במקום, חלל, במשמעותו חסר היחס לדברים. מקום הוא המשמעות ביחס לדברים. ורשות היא המשמעות ביחס לדבר מסוים."}, {"s": "p", "h": "וכן יש למצוא שלושה גדרים אלו בחפץ, דבר, חפץ וכלי. שם דבר הוא במשמעותו בלי יחס למקום. שם חפץ, משמעותו ביחס למקום, וגדר זה יפריד דבר ממשנהו, שהוא במקום אחר ממשנהו. וכלי שמשמעותו ביחס למקום מסוים, ובזה יוגדר הכלי ככלי של המקום. ובניין המושגים הכולל חפץ ומקום הוא כך, חלל, דבר, מקום, חפץ, רשות, כלי."}, {"s": "p", "h": "בניין מושגי חפץ מקום ורשות - השתלשלות מושגים מחלל ודבר ועד רשות וכלי בית "}, {"s": "p", "h": "ואמנם חלל ודבר האמורים אינם שייכים לגדרי הוצאה שהם בחפץ ומקום, אך יהיה גדרם מושאל ביחס לחללי מקום, וכהגדרה של מקום נטול דברים, וכן גדר חפץ ומקום יהיה מושאל למקום שיש לו אפשרות מעשית להנחת דבר עליו, וכן המושג יהיה גדר כלי ורשות מושאל למקומות שמוגדרים לשימוש מסוים בחפץ. וכן בעניין הדברים שנגדיר דבר שלא נח כלא נמצא ברשות, והוא מקביל לחלל, וגדר דבר שנמצא ברשות לא מוגדרת כנמצא באוויר, הוא מקביל למקום, ודבר שנמצא ברשות מוגדרת יחשב שהוא כלי ששייך למקום, והוא מקביל לרשות. ובנין הדינים כך חלל מקום, לא נח, מקום ד', דבר באוויר, רשות מוגדרת, כלי בית ויש להמשיך בזה שאחר היחס של כלי למקום מסוים נגדיר רשות כמיועד לחפצים מסוימים, ויבדלו החפצים לשונותם השימושית. וכיון שהגדרנו כזה מקום נוכל לומר שרק כלי שנמצא במקום שראוי לשימושו נחשב כנמצא ברשות. וכיון שהגדרנו כך אפשר להגדיר רשות כמקום שתופס כלים הנמצאים בו. וכיון שכך נוכל להגדיר כלים ככלים שאף שעברו רשות עדיין נחשבים ברשות שתפסה אותם. וכיון ששיש כלים חוץ לרשות שנחשבים כברשות כך נוכל להגדיר שרשויות יוכלו לתפוס רשויות אחרות להיות נספח אליהם. וכיון שהרשויות התפוסות נחשבות כנפסח נוכל לומר שכלים הנמצאים בהם אף נספחים לרשויות אלו. וכיון שכך נוכל לומר שיש רשויות שאף שיש בהם כלים לא יוכלו הכלים להגדיר הרשות, וכיון שכך נוכל לומר שיש כלים שנחשבים שאינם ברשות גם כשהם שם, וכו'."}, {"s": "p", "h": "ועכ\"פ יהיה גדר במקום ביחס לקיום חפצים בו, וע\"כ דברים הקיימים במקום יוגדרו כמי שיש להם מקום, וכיון שבתוך אותו המקום ישנם דברים המוגדרים כדבר שיש לו מקום והרי הם נפרדים, הרי שהמקום יחשב כמקום הדבר, ויחולק למקומות נפרדים. וכיון שהמקום מחולק הרי שדברים הנמצאים יחשבו כיש להם מקום נפרד. וכיון שיש דברים שיש להם מקום נפרד, הרי ביחס לדברים אלה יוגדר המקום שנמצאים בו הדברים כמקום של דבר. וכיון שהדברים נמצאים במקום שיש בו גדר עצמי כמקום של דבר, הרי שיוגדר מקום שנמצאים בו כמקומם. וכיון שבמקום ימצאו דברים ששייך שיהיה מקום שהוא מקומם, אז יהיה שייך במקום עצמו גדר שהוא מקום שמיוחד לדבר, וכיון שדברים נמצאים במקום ששייך שיהיה מיוחד לדבר, הרי שיוגדר שיהיה מקום שמיוחד להם גם בלי שיהיו בו. וכיון שיש לדברים מקום מיוחד בלא שנמצאים בו, הרי שיחשבו כנמצאים במקום אחד. וכיון שבמקום ישנם דברים שנחשבים כנמצאים במקום אחד, אז יהיה גדר במקום עצמו שהוא מקום אחד, וכיון שיהיה המקום מוגדר כמקום אחד, הרי שגם דברים שנמצאים בכל מקומותיו יחשבו כנמצאים במקום אחד."}, {"s": "h4", "h": "הגדרות רשות"}, {"s": "p", "h": "ועתה נפרט את המשמעות החמישית לסוגיה, שיש במשמעות זו שני סוגים עיקריים של שימושי אדם במקום, כמקום הכנה, וכמקום מעבר. "}, {"s": "h7", "h": "רשות המוכנה לתשמיש"}, {"s": "p", "h": "המשמעות הראשונה היא המשמעות הרביעית במשמעות החמישית, והיינו, שיש לאדם שימוש במקום כרשות חפץ, ועל כן יהיה שייך יעוד שימוש במקום כהכנה לשימוש כזה, ובמשמעות השביעית יהיה זה משמעות החלל הכולל שיהיה מוכן לשימוש הכנת חפצים, ועל כן יהיו כל מקומותיו הנפרדים מקומות המוכנים להכנת חפץ, וביחס לחלל יהיה זה משמעות אחידה שהוא מיועד לשימוש אדם, וכיון שהוא אחד והמקומות שסביבו נפרדים הרי שזה יגדיר אותו בנפרד משאר המקומות אך ביחס לכלל מקומותיו אף שהם משמשים לשימוש אחד אין הם אחד שהם משמשים שימוש זה בנפרד ולהפריד צריך שתהיה הפרדה ממקומות שסביבותיו וכיון שנפרדו הרי שיש להם משמעות אחידה ביחס לחוץ."}, {"s": "h7", "h": "רשות המוכנה לשימוש"}, {"s": "p", "h": "והמשמעות השניה היא שימוש במקום כמעבר, והיינו, שכיון שחפצים משמשים את האדם בכמה מקומות יהיה צריך למעבר בין מקומות אלו, ומשמעות זו היא מקום במובן הפשוט ביותר של קיום החפץ, ועל כן לא יהיו המקומות צריכים להתאחד אפילו כמקום החפץ בעל הצורה, והחלל המיועד לשימוש יכלול מקומות אלו כמוכנים לשימוש המעבר, שהמעבר ברוב מקומות אלו יוגדר כמעבר אחד שהרי לא יהיה למקומות תפיסה בחפץ שאינם מקומות שימוש מקומי רק כקיום."}, {"s": "p", "h": "שלושה מושגים שימושיים אלו שייכים רק במקומות המיועדים משכבר לשימוש אך מקומות שאינם מיועדים לשימוש לא יהיה להם אחידות שימוש ומקומותיהם יוגדרו רק לפי השימוש בפועל."}, {"s": "p", "h": "א\"כ מצאנו שלושה מושגים מציאותיים, מקום כמקיים והוא מקום הדבר עצמו, מקום כחלל והדבר נמצא בתוכו, חלל המתאים למקום, ושלושה מושגים שימושיים, מקום כמשמעות קרבה, מקום שימוש אדם, מקום שימוש אדם בחפץ, מקום המיועד לשימוש, רשות מקומות רבים המיועדים כולם יחד לשימוש מסוים, רשות הינוח, ורשות מעבר."}, {"s": "p", "h": "והנה אמנם השתמשנו בלשון מעורבת במושגי קיום, שהרי המקום אינו שייך לקימת הדבר אלא לקומתו, שהיא תוכנה חיובית בו, ולא מקיומו העצמי, ובמצב היותו, וכמו שכתוב הקים את המשכן, שלפני כן לא היה המשכן, והוא פעולה בעצם היותו, ועל זה שייך לשון קיום. אבל גדר חפץ במקום והעברתו שייך לקומתו, ובזה יהיה שייך פעולה בחפץ קיים, ובעל קומה שיהיה המקום מאפשר קומתו."}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"873\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">10\u003c/sup>\u003cspan class=\"ca\" data-c=\"873\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">דיני מקום\u003c/span>"}, {"s": "p", "h": "הנה כמו\"ש כתבנו לעיל במשמעותו השימושית של מקום תנאי מקום ביחס להוצאה יהיו חלק ממשמעותו השימושית של המקום, ויש בזה שני גדרים גודל מרחב שימוש והאחידות השימושית בכלל המרחב."}, {"s": "h4", "h": "גודל מקום"}, {"s": "p", "h": "הנה מצאנו ביחס להוצאה כמה שיעורי מקום, ויש לנו להגדירם כראוי מאיזה משמעות מקום מקורם."}, {"s": "h7", "h": "עשרה טפחים"}, {"s": "p", "h": "גדר מה שגובה עשרה טפחים הוא מקום תפיסת רשות, וכן גובה מחיצות וגובה להחשיב מקום להיות נפרד מרשות שסביבו, ועוד כאלה, הוא מלימוד שלא ירדה שכינה לארץ ומצאנו שדיבר עימו מעל הכפורת שהיא גובה עשרה טפחים. והנה זה הגדר אינו מגדרי מקום אלא מגדרי תפיסת הקרקע את אווירה שתחשב חלק מהקרקע, וממנו נלמד ששימוש של אדם בקרקע הוא עד גובה י', והיינו, שעד י' טפחים נחשיב את שימוש האדם כחלק משימושו בקרקע, ואפילו שיתכן שימוש גם מעל י' טפחים לא יחשב זה כשימוש בקרקע, אלא כשימוש באוויר. וכיון שאין הגדרת רשות אלא במקום, ואין מקום בלא קרקע, לא תחשב הרשות אלא עד עשרה טפחים. וממילא אם נרצה להפריד רשויות אין לנו אלא להפריד את הקרקע שלהם, ובזה יספיק מחיצה י' טפחים. ועל כן מקום עשרה טפחים יחשב כמקום נפרד ממקרקע שסביבותיו. וכיון שהוא גדר בקרקע לא תועיל מחיצה י' טפחים לחצוץ רשות אם לא תתחיל מהקרקע."}, {"s": "h7", "h": "ארבע אמות"}, {"s": "p", "h": "גדר מה שמקום שביתת אדם הוא ד' אמות, וכן העברה היא ד' אמות, וכן שיעור תל המתלקט עשרה הוא בארבע אמות, הוא משום ששיעור מקומו של אדם הוא ארבע אמות, ומה שהוא שיעור מקומו של אדם מצאנו מחלוקת אם הוא משום שעצם מקום אדם המונח הוא בד' אמות, או ששיעור שימוש אדם בחפץ הוא במקום ד' אמות. ואיך שלא יהיה הוא גדר בשימוש אדם. וממילא יהיה שיעור מקום שימוש אחד של אדם ד' אמות, וכיון שעד עשרה טפחים נחשב השימוש כחלק מהקרקע, אם התל יתלקט עשרה בתוך ארבע לא יהיה חלק התל שמעל עשרה חלק משימוש אחד של החלק של הקרקע שלידו, ויחשב חלק זה של התל כנפרד מהקרקע. אך אם יתלקט עשרה ביותר מארבע הרי שהוא מקום שימוש עם הקרקע, וכן לכל אורך התל אפילו יגיע לעשרה יהיה המשך שימוש אחד עם הקרקע, כיון שהגודל הגדול ביותר של מקום שימוש אחד הוא ארבע אמות, וכן לא תחשב העברה ברה\"ר בפחות מד' כיון שעד ד' אפשר שיש עליה שם שימוש אחד במקום."}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"874\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">11\u003c/sup>\u003cspan class=\"ca\" data-c=\"874\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ארבעה טפחים\u003c/span>"}, {"s": "p", "h": "גדר מה שצריך שיהיו הרשויות בעלות גודל מקום של ד' על ד', וכן שלא יחשב עקירה והנחה אלא במקום ד', וכן שלא תחשב מחיצה אלא אם היא למקום ד', וכן לא יהיה פתח נחשב אלא אם הוא רחב ד', וחלון רחב וגבוה ד', כי אין לך מקום חשוב פחות מד' (והנה אף שלא מצאנו שכתבו זה לכאורה רוחב ארבעה הוא גם גדר באדם שהוא רוחב ארבעה כמו שמצינו במסכתין לעניין פתח הוצאת המת), והיינו, שביחס לחפצים המונחים לא יחשבו כמונחים באופן שיחשב שזה מקומם, אלא אם יהיו מונחים במקום שראויים להישאר עליו מבחינת מה שישמרו עליו ולא יפלו ממנו, וזה גדר מקום ד', וזה באופן כללי כיון שיש חפצים דקים שיונחו גם במקום קטן יותר, וכן יש כאלה שלא יונחו אלא במקום גדול מזה, אבל ביחס לרוב חפצים לא יהיו מונחים באופן המועיל אלא אם הם מונחים במקום ד'. ומשמעות מילת חשוב הוא שראוי לקיום חוזר, אם לשימוש, ואם לשאר דברים. וכיון שכן לא יחשב מקום אם אלא אם הוא מקום הראוי להניח עליו חפצים, וכיון שאין מניחים חפצים אלא במקום ד' לא יחשב מקום חפצים אלא אם הוא בגודל ד' על ד', וכיון שכך בבואנו להגדיר מקום כרשות שמהותה היא מקום המיועד לשימוש מסוים, הרי שלא תחשב אלא אם יהיה בה גדרי מקום, וזה אינו אלא בד' על ד'. וכן לעניין עקירת והנחת חפץ, אף שיחשב שהחפץ נמצא ברשות, לא יחשב כמונח ברשות, אלא אם הוא מונח במקום, וזה אינו אלא בד' על ד'. וכן לעניין מחיצה, שלא תחשב מחיצה אלא אם היא מחיצה למקום, שאין מחיצה אלא למקומות, וכיון שמקום פחות מד' על ד' לא חשוב מקום, לא תחשב מחיצה כזו מחיצה."}, {"s": "p", "h": "גדר שטח ד' על ד' טפחים - חילוק בין מקום הינוח בקרקע לשיעור שימוש בשטח "}, {"s": "p", "h": "והנה כאמור שאמנם שיעור ד\"ט הוא ביחס לשימוש אדם, אבל דין שטח של ד\"ט על ד\"ט הרי זה כבר דין בשטח הקרקע. ואמנם ביחס למקום הינוח אחד שייך לומר שהרי הוא מתחבר לשאר הקרקע משום שראוי לשימוש, אך אם השטח עצמו מחולק כבר לא יועיל זה, וע\"ז אמרו דכיון שאין שיעור שטח דד\"ט שיעור בעצם חשיבות הקרקע לשימוש אלא בהגדרת מקום שיש בו רוחב הראוי לשימוש, כיון ששטח זה ראוי להניח עליו דבר ויהיה ראוי לשימוש, אף ביחס לרוחב הנ\"ל יש לו להיות נחשב אחד. ומבואר דעצם גדר קרקע דרשות (היינו לעומת אוויר) הוא ביחס להנחת חפץ ואין בו שיעור כמו שאין שיעור בחפץ. וגדר שיעור רוחב ד\"ט הוא ביחס לשימוש אדם, וגדר שטח ד\"ט הוא בהגדרת הקרקע כמקום. וע\"כ אין זה ראוי דראוי שביחס לרוחב ד\"ט הוא דראוי משום דתלי ביה מידי, וביחס לשטח קרקע הוא ראוי ע\"י שיניח שם איזה דבר וישתמש."}, {"s": "p", "h": "חילוק רוחב ד' משטח ד' טפחים - רוחב שיעור תפיסה ושטח שיעור מקום לחפץ "}, {"s": "p", "h": "וביתר ביאור כי אין גדר ד\"ט ברוחב שווה לגדר ד\"ט דשטח, והיינו, דאף שמה שצריך שיעור ד\"ט ברוחב הוא משום רוחב קרקע הראוי לשימוש אדם, אין זה משמעות שטח עצמו שהוא בגדר קרקע הראוי לרשות שהיא פני השטח. ששיעור רוחב הוא שיעור תפיסה, ופירושו שכאילו אנו רואים שמקום זה מלא, וע\"כ אם יהיה יתד שאינו באותו גדר שימוש הרי שהוא ממעט ברוחב שעכשיו אין ראוי שיהיה במקום זה דבר בעל רוחב זה. אך שיעור השטח הוא שיעור מקום והוא ביחס לחפץ, ואין בו חסרון שהוא מחולק. וביחס לשטח הרי החסרון במקרה הנ\"ל הוא רק במה שאין בשטח זה רוחב כזה, וע\"כ די שיניח דבר. והיינו, שאף שהנחת דבר יש בה משמעות שטח אחר ולא זה, אין בזה חסרון, כי אין החסרון בשטח, ואין התיקון בשטח, דאף לולי האי מידי נחשב האי שטח כשטח אחד, אלא שיש בו דין שיהיה ראוי לשימוש, ובזה מועיל מה שראוי להניח וכו'."}, {"s": "h7", "h": "בית סאתיים"}, {"s": "p", "h": "דין בית סאתיים הוא דין הנוהג ביחס להגדרת מקום המשמש לשימוש הינוח אחד, וזה נקרא שימוש דירה, והיינו, שכמו שכתבנו, ששימוש המיועד לדירה מגדיר את כל המקומות המשמשים לשימוש זה כמשמשים לאדם, וכיון ששימוש זה נוגע לשימוש בקרקע הרי שהרשות תלויה בנפרדות השימוש בקרקע, וכיון שכך צריך שהקרקע עצמה תוגדר ממקומות שסביבותיה. והנה בכדי להגדיר את המקומות כנפרדים מספיק מה שיעשו מחיצה למקום, ומקומות שנפרדים משאר מקומות יוכלו לשמש לשימוש של הינוח, וההרשות הכוללת כל המקומות תחשב לרשות אחת אחידה, אך אין זה ענין לאחידות המקומות, שהן לא נתאחדו ביעוד השימוש שהרי משמשים לשימושים נפרדים ולחפצים נפרדים. וא\"כ יש לנו רשות אחת המיועדת לשימוש של הינוח ומקומות רבים המיועדים להנחת דברים רבים, אלא שכיון שהרשות נפרדת מסביבותיה יש לנו להגדיר את מקומותיה כדבר אחד, שהרי כולן כאחת נמצאות בתוך מחיצות הרשות, והיות למחיצות תוך יגדירם כדבר אחד. ומעיקר הדין אין צריך שיהיו המקומות עצמם מיועדים לשימוש דירה, אלא כיון שיש מחיצות הרי שכל המקום נתאחד לרשות אחת, וכל מקומותיו מוגדרים חלק מהרשות. אלא שמתקנת חכמים להבדיל בין שימושי הינוח שונים. וגדר אחד מתקנה זו היא להבדיל בין שימוש דירה לשאינו, ולהגדיר רשות ע\"פ הבדלה זו, והם אמרו שלא תחשב רשות אחת, היינו, מקום המיועד לשימוש כרשות, היינו, שהיא מאחדת מקומותיה לשימוש זה, אם יהיה זה שלא לשם דירה, אך כיון שכאמור המחיצות בהיותם מכילים את כלל המקומות מאחדים את המקום, יהיה תלוי בכח הכלת מחיצות, ומקום שאין המחיצות מוגדרות כמכילות, יעוד שימוש כזה לא יתאחד לרשות אחת, ולמדנו שגודל זה הוא כגודל חצר המשכן שהיה מאה בחמישים שהוא גודל בית סאתיים, והיינו, שכיון שלמדנו שהשרה ה' שכינתו בתוך המשכן, וכדכתיב ושכנתי בתוכם הרי לנו שמחיצות יכילו גודל כזה, היינו, להגדיר מה שנמצא בחללם כנמצא בתוכם. וא\"כ מצאנו מהו גודל מקום שמחיצות יגדירוהו כאחת מכח היות מכילים אותו. וע\"כ שימוש שלא יחשב כשימוש הראוי לאחד את חללו לשימוש אחד אם יהיה בתוך בית סאתיים יחשב לאחד, מכח מחיצותיו, ויותר מזה לא. אך אם יהיה מיועד לשימוש דירה, יחשב לאחד מיעוד שימושו, כיון ששימוש זה הוא שימוש אחיד בכל הרשות, והיינו, שיש לחלק בין שני סוגי יעוד שימוש, שיש שימוש שהוא אמנם מחולק ביחס למקומות שמשתמשים בו בחפצים שונים, אך אף השימוש הנפרד הוא חלק משימוש שאינו מחולק, והיינו, שמי שישתמש במקום שלא לשימושי דירה הרי שכל מקום הוא מקום נפרד ביחס לשימוש. אך מי שישתמש שימושי דירה לא יהיה בשימוש הנפרד משמעות נפרדת, כי הכל תחת שם דירה יחשב ועל כן יחשב חלל הרשות אחד. "}, {"s": "h7", "h": "ט\"ז אמה"}, {"s": "p", "h": "שיעור ט\"ז אמה הנוגע לרוחב רה\"ר, (ולאורכו בפלטיא) הוא דין הנלמד משיעור רוחב הדרך ששימשה את עגלות קרשי המשכן, והשימוש בהם. וסיבת השיעור בזה שהוא שיעור שימוש שאינו שימוש במקום מסוים אלא שימוש מעבר, שהיו העגלות עוברות ממקום למקום, שמקום הקרשים היה על העגלות, והם עברו בדרך. ואף שמצאנו שיעורים גדולים יותר ביחס לשימוש מעבר, זה שיעור הקטן ביותר. ומזה שאנו משערים בן לוי שהיה עמהם נלמד שאף הוא שיעור בשימוש האדם במקום כמעבר. ולהבדיל בין שימוש זה לשימוש של ארבע אמות נאמר, ששיעור ארבע אמות הוא שיעור אורך, כי הוא נוגע לשימוש אחד. אך שיעור רה\"ר הוא שיעור של ריבוי, וע\"כ נמדד בשיעור רוחב. והיינו, כי שיעור אורך הוא שיעור שימוש של התחלה וסוף, והוא שיעור גדול. אך רה\"ר אין לה משמעות של התחלה וסוף, כי היא משמעות מעבר. ולכן יהיה שיעורה ברוחב, שהוא שיעור שאינו שיעור של התחלה וסוף, אלא שיעור של התפשטות, ועל כן הוא שיעור קטן (וכן מצאנו שיעור ט\"ז אמה ביחס להתפשטות קידוש ירק בכרם). (ובמק\"א כת' דאולי יש בזה גדר של ארבע פעמים ארבע אמות)."}, {"s": "p", "h": "גדר אורך ורוחב במקום ובשיעורים - אורך גדר התמשכות ורוחב גדר תפיסת הדבר במקום "}, {"s": "p", "h": "וביתר ביאור ואגב גם זה נבאר דגדר אורך בכל מקום הוא גדר התמשכות דבר, וגדר רוחב הוא גדר תפיסת דבר, ובכל שיעור יש לברר אם גדר משך או גדר תפיסה, דבזה ישתנו, דאם השיעור הוא גדר תפיסה, הרי שמשמעותו הוא הדבר עצמו, והוא שיעור המועט. אך אם הוא בגדר התמשכות, משמעותו הוא התפשטות, והוא שיעור המרובה, וביותר לא יתווסף. וכן ביחס למקום המשוער ע\"י שיעור אחד לאורך ורוחב, יש לברר אם הוא בגדר אורך או רוחב. שאם הוא שיעורו מרובע הרי בהכרח שהוא גדר ברוחב, אך אם הוא שיעור רק לאורך או רוחב, הרי שבהכרח או שהוא שיעור מרחק, והוא שיעור המרובה. או שהוא שיעור תפיסה, והוא שיעור המועט. וכמו ארבעה טפחים שהם שיעור המועט, וארבע אמות שהם שיעור המרובה. כי שיעור ארבעה טפחים הוא שיעור ברוחב, וכמו דמצאנו בחלון דעירוב וטומאה, וע\"כ הוא שיעור המועט, והוא שיעור מרובע. אך שיעור ארבע הוא לכאורה שיעור באורך. וע\"כ יבוא בכל מקום כשיעור המרובה ובהתפשטות."}, {"s": "p", "h": "סדר חשיבות שטח מקום מרובע - אורך חשוב ברוחב חשוב להיות שטח ומקום נפרד "}, {"s": "p", "h": "וסדר הדברים הוא שנמצא חשיבות באורך דבר, וכן נמצא ברוחבו, ואורך חשוב ברוחב חשוב יחשב שטח, ושטח בעל משמעות אחידה כלשהי יחשב מקום לעניין ההוא. ובסדר זה הרי גודל אינו גדר במקום אלא בשטח, והוא, משום גודלו חשוב להיקרות שטח, והמעביר חפץ מרחק יותר משטח זה הרי הוא כמעביר משטח לשטח. וכל מקום שמצינו שיעור שטח שהוא באורך ורוחב שווים ולא יחשב גודל השטח באם לא יהיו מרובעים, בהכרח שמקור שיעור זה הוא באורך לבד, ומשמעות חשיבותו כשטח הוא מה שהשטח הוא אורך חשוב משום כמות רוחב שלו, והרוחב הוא רק חשיבות דאורך. וע\"כ מצאנו בשיעורים כאלו שהם שיעור גם לאורך לבד, וכמו במקום ד\"ט שישנו ברוחב מחיצה בלי אורך, ולבוד ד\"ט לרשב\"ג, וכן ברוחב פתח, וכן לגבי ד' אמות דדופן עקומה."}, {"s": "h4", "h": "אחידות המקום"}, {"s": "p", "h": "ואחר שנתבאר כי דין מקום הוא גדר הנובע משימוש האדם במקום, א\"כ לא יחשב מקום כמקום אלא עם השימוש בו יהיה אחיד, וכיון שראינו שמקום חשוב אינו אלא בד' טפחים, א\"כ צריך שכל הד' טפחים יהיו משמשים שימוש אחד. אך אם לא יהיה המקום ראוי לשימוש בכולו כאחד לא יחשב המקום אחד, ולא יהיה בו שיעור מקום. אך זה הגדר נוגע רק למה שישתמשו בו בפועל, והיינו, שאם הניח אדם חפץ במקום ד' שאינו אחיד לא יחשב שהניח בו. אבל מקום הנוגע לגדרי רשות שלא תחשב רשות לולא שיהיה בה מקום חשוב, כיון שאין הם נוגעים לשימוש בפועל, אלא ליעוד לשימוש, אם יהיה אפשר להשתמש במקום באופן אחיד ע\"י שיניח עליו דבר או בדרך אחרת יחשב המקום כרשות, אפילו לא הניח עליו דבר. כיון שאין הרשות דין בקרקע אלא בשימוש בו. "}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"875\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">12\u003c/sup>\u003cspan class=\"ca\" data-c=\"875\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">גדרי מציאות חפץ במקום\u003c/span>"}, {"s": "p", "h": "אחד שביארנו את משמעות המקום, יש לנו לבאר גדרי מה שנקרא חפץ במקום וכמו שכתבנו לעיל ישנם שלושה גדרים עיקריים בהיות חפץ במקום והוא המשמעות המציאותית הפשוטה מה שכל חלקיו נמצאים במקום ושהמקום מקיימם המשמעות השניה היא היות חפץ כדבר אחד במקום והמשמעות השלישית הוא היות חפץ במקום שהוא חלק ממקום גדול ויהיה משמעות שהוא בתוך חלל המקום הגדול."}, {"s": "h4", "h": "מקום"}, {"s": "p", "h": "והנה שם מקום נמצאהו במשמעויות חלוקות, וחלוקתם העיקרית בשלוש, ונפרטם מהמשמעות היסודית ומעלה."}, {"s": "h7", "h": "דבר שיש בו דבר"}, {"s": "p", "h": "דבר שיש בו דבר או ששייך שיהיה בו דבר, והיינו, לא במשמעות שהמקום מקיים את הדבר כי אין קיום לדבר בלא מקום, אלא כגדר אפשרי, היינו, שיש לדבר להתקיים בו (כי אין דבר הנמצא במקום זה שונה מנמצא במקום אחר לגבי קיומו, ואין להחשיב זאת כקיום הדבר). והוא עיקר תכונת מקום בשונה מחפצים ובגדר חלל."}, {"s": "h7", "h": "דבר המקיים דבר"}, {"s": "p", "h": "דבר המקיים דבר. וזה שייך במקום שיש בו תוספת משמעות מלבד עצם התקיימות דבר בו כמקום הינוח, שאין מנוחת דבר מחוייבת מעצם קיומו. וזהו גדר במקום עצמו, אך ביחס לדבר שיש בו או ששייך שיהיה בו."}, {"s": "h7", "h": "דבר המוכן לקיום דברים"}, {"s": "p", "h": "דבר המוכן לקיום דברים. וזה שייך במקום שיש בו יכולת כללית לקיים בו דברים, וזה גדר במקום עצמו, ולא מחמת איזה דבר שיהיה בו. ואף כשיהיה בו דבר, אין גדרו כמקום מחמת היותו קיום הדבר המסויים הנמצא בו עתה שהרי ראוי לדברים הרבה."}, {"s": "h4", "h": "חפץ ומקומו"}, {"s": "p", "h": "וכן הוא בשם חפץ ומקומו, שנמצאם במשמעויות חלוקות, וחלוקתם העיקרית בשלוש, ונפרטם מהמשמעות היסודית ומעלה."}, {"s": "h7", "h": "חפץ הנמצא במקום"}, {"s": "p", "h": "חפץ הנמצא במקום. ולא במשמעות שהוא במקום סתם (דזה ממשמעויות מקום), אלא במה שהוא במקום זה ולא אחר. ומשמעות זו היא ביחס לדבר אחר, וכמו ביחס לקירבת החפץ לדבר אחר. ובזה לא יהיה משמעות במקום אלא במה שהדבר האחר נמצא במקום הסמוך לו. וכן ביחס לשימוש בחפץ בתשמיש שאינו מעצם קיומו."}, {"s": "h7", "h": "חפץ הנמצא במקום מסוים"}, {"s": "p", "h": "חפץ הנמצא במקום מסוים, והיינו, במה שיש במקום תוספת משמעות מלבד מה שהוא מקום החפץ כזהות, וכמו מקום מנוחת חפץ, וכדלעיל במובן השני של מקום. ויש בזה גדר מוכנות לקירבה הנ\"ל, שבלא סיום המקום אין הקירבה שייכת אלא בזמנה. אבל בחפץ הנמצא במקום מסויים, הרי ששייך בו קירבה במי שיתקרב אליו, שהוא קבוע וזה מתקרב."}, {"s": "h7", "h": "חפץ הנמצא במקום חשוב"}, {"s": "p", "h": "חפץ הנמצא במקום חשוב, והיינו, במקום שהוא מוכן לקיום דברים. וזה גדר שהחפץ קבוע במקום, וכמו בשעת קירבה ממש, שהרי המקום חשוב לעצמו (וכמו ההבדל בין מי שמניח דבר מחוסר יכולת להחזיקו לזמן קצר, לבין מי שמניחו מחמת שאין צריך לו עתה, שהראשון יניחו במקום כל דהוא ובלבד שינוח, אבל השני יניחו במקום שהמכינו לכשיצטרך לו)."}, {"s": "h4", "h": "צורך אדם במקום"}, {"s": "p", "h": "והנה כאמור לעיל עיקר חשיבות מקום וחפץ הן ביחס לאדם, ויש לנו לפרט משמעות אלו במובן זה, ונחל במקום, ונמצאהו במשמעויות חלוקות, וחלוקתם העיקרית בשלוש, ונפרטם מהמשמעות היסודית ומעלה."}, {"s": "h7", "h": "חלל"}, {"s": "p", "h": "מקום כחלל, וכגדר הראשון במקום וביחס לאדם עצמו, היינו, מה שיש בו אפשרות התקיימות, ובזה לא יהיה גדר במקום אלא במה שאינו מלא, שהמקום המלא ימחצהו ולא יאפשר קיומו. וזה שייך בצורך כמו הילוך (וביחס לאוויר המאפשר מעבר ולא ביחס לקרקע שמהלך עליה)."}, {"s": "h7", "h": "מקום"}, {"s": "p", "h": "מקום סתם, וכגדר השני במקום וביחס לאדם עצמו, היינו, מה שיש בו תוספת על עצם התקיימותו בה, וזה שייך בצורך כמו ארץ לרוץ (וביחס למה שהיא מאפשרת התקדמות, היינו, פסיעה), וקרקע לעמוד (היינו מה שהוא מתייצב עליה)."}, {"s": "h7", "h": "רשות"}, {"s": "p", "h": "רשות, וכגדר השלישי במקום וביחס לאדם עצמו, היינו, מה שמקום זה מוכן למילוי צורך שיש לאדם, וזה שייך בשני המובנים הקודמים, או שיש בו קביעות דריקנות ויהיה מוכן להילוך, או שיש בו תכונת שמאפשר תשמיש מקומי."}, {"s": "p", "h": "גדר מקום בקרקע בשלושה פנים - שטח, אורך, ורוחב, ומשמעות השטח ככולל ולעצמו "}, {"s": "p", "h": "וכמשנ\"ת גדר מקום ביחס לקרקע, היינו, שטחה, מוגדר בשלושה מובנים, אורכו, רוחבו, ושטחו. ואף שמושג שטח נפרד ממושגי אורך ורוחב, ויש בו מה שאין בהם, שאין גדרי אורך אלא באורך וכו', אבל השטח הוא בכח אחד גם באורך וגם ברוחב, וע\"כ יהיה שייך להגדירו באחת, שכל אורכו ורוחבו הוא משמעות אחת של שטח. אך ראה נא, כי גדרו הנ\"ל אינו מבטל את מושגי אורך ורוחב, ואף השטח יש לו אורך ורוחב. ועל כן יבוא בשלושה גדרים, שטחו, אורכו, ורוחבו. ואכן מצאנו שיהיה השטח מוגדר בשני גדרים. האחד, במשמעותו ככולל האורך והרוחב, כמו דין ד\"ט על ד\"ט, שפירושו שיש בשטח זה שיעור רוחב ד\"ט, ואף שד\"ט הוא שיעור ברוחב לבד, כשנרצה להגדיר שטח שיש לו כזה שיעור הרי שנצטרך שיהיה בו זה השיעור בכל השטח. והשני, הוא בגדרי שטח עצמו ובהיות לו כמות שטח, ואף שלצרכי מדידה נשתמש במושגי אורך, לא יהיה זה גדר השטח עצמו, וכמו בשיעור בית סאתים שאינו שיעור באורך או רוחב השטח אלא בשטח עצמו, היינו, גודלו."}, {"s": "p", "h": "משמעות קרקע כפני שטח המקום - קרקע פני השטח בלבד ונפרדותה תיבחן ע\"י גדרי שטח "}, {"s": "p", "h": "וקרקע זו משמעותה היא בשטח המקום, יען כי אין משמעות בקרקע כמציבת השימוש מלבד בפני שטחה. וע\"כ יהיה שטח מקום גדר ראשון בו, וביתר ביאור שאף אמנם וכמש\"כ שיעורי השטח אינם מוכרחים להיות בגדרי שטח עצמו, והם זה כגדרים כמותיים ביחס למשמעות דקרקע עצמה, אך עצם משמעות קרקע מוגדרת ע\"י שטח, היינו, שדין קרקע הוא בכל נקודה ונקודה בשטח, וככשנגדיר גודל שטח הרי מוכח שיהיה לכל נקודה ונקודה גדר קרקע בפני עצמו, וכמש\"כ הרי משמעות זו של קרקע היא בפני שטחה. ואף שיהיה השטח חלק מגוף עבה אין זה שייך לגדר קרקע כי קרקע היא פני השטח לבד, ומשום כך גם היותה נפרדת ומאוחדת תיבחן ע\"י גדרי שטח, וזה אף שאין לשטח זה לבדו עמידה במציאות."}, {"s": "h4", "h": "צורך האדם בחפץ"}, {"s": "p", "h": "וכן בצורך האדם בחפץ שנמצאהו במשמעויות חלוקות, וחלוקתם העיקרית בשלוש, ונפרטם (אף שיש מהם לא נמצאהו גדר בהוצאה) מהמשמעות היסודית ומעלה."}, {"s": "h7", "h": "שימוש כילוי"}, {"s": "p", "h": "שימוש כילוי, וזה שייך בצורך עכשווי, ובחפץ מתכלה, וכמו הרעב לאוכל."}, {"s": "h7", "h": "כלי תשמיש"}, {"s": "p", "h": "כלי תשמיש, וזה שייך בצורך עתידי מסויים, ובחפץ הראוי לזה, וכמו כלי אכילה."}, {"s": "h7", "h": "אסיפת ממון"}, {"s": "p", "h": "אסיפת ממון, וזה שייך בצורך עתידי שאינו מסויים, ובחפץ הראוי להרבה דברים, וכמו כסף לקניית אכילה (או שווה כסף)."}, {"s": "h4", "h": "צורך האדם בחפץ ממוקם"}, {"s": "p", "h": "והנה על אף האמור במשמעותם הנפרדת של חפץ ומקום כצורך האדם, ומה שיש בזה להגדירם כל חד לעצמו, תהיה משמעותם כאחד בגדר נוסף על האמור, ונמצאם במשמעויות חלוקות, וחלוקתם העיקרית בשלוש, ונפרטם מהמשמעות היסודית ומעלה."}, {"s": "h7", "h": "שימוש בו"}, {"s": "p", "h": "שימוש בו, וזה כמו בגדר הראשון דמקום חפץ, ובגדר הראשון בצורך האדם בחפץ, והיינו, מה שיש לו צורך עכשווי, ולא יושג אלא במקום זה כאכילה וקירבה וכו'."}, {"s": "h7", "h": "מוכנותו לו"}, {"s": "p", "h": "מוכנותו לו, וזה כמו בגדר השני וכו', והיינו, מה שיש לו צורך עתידי, וצריך שיהיה ממוקם באיזה מקום שיוכל לקחתו לכשיצטרך לו."}, {"s": "h7", "h": "שמירתו"}, {"s": "p", "h": "שמירתו וזה כמו וכו', והיינו, מה שיש לו צורך עתידי שאינו מסויים, וצריך שיהיה ממוקם בקביעות לכשיתעורר איזה צורך שחפץ זה ראוי להשלימו."}, {"s": "p", "h": "והנה אף שנמצא סדרם של דברים זה לעומת זה, ומהנצרך לחשוב. אך אין חשיבות זה תלוי בחשיבות בזה, וכדוגמא שודאי מקום הראוי לדברים הרבה הוא מקום חשוב יותר לעצמו ממקום שאינו, אבל ביחס לצורך שיש לאדם בחפץ ממוקם יהיה זה תלוי בצורך, שמי שצריך לשימוש כילוי דחפץ אין מקום המוכן חשוב לו יותר משאינו, כי אין בצורך שלו משמעות הכנה (וע' מש\"כ אקרא דציפור מצאה בית ודרור קן לה, שהצורך הגדול יצריך הכנה גדולה)."}, {"s": "h4", "h": "סיכום"}, {"s": "p", "h": "ונסכם את כל האמור, ונקדים בשייכותם למלאכת הוצאה, דהנה מלאכת הוצאה מרשות לרשות לא נאמרה בכל דבר שיש להגדירו כיציאה, אלא במקרים מסוימים, ולא נאסרה הוצאה מרשות לרשות בכל הרשויות, ומושג הוצאה מרשות לרשות אינו נובע מעצם איסור המלאכה, אלא מציאות הוצאה מרשות לרשות נובעת מצורת שימושי האדם."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"876\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">13\u003c/sup>\u003cspan class=\"ca\" data-c=\"876\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ומאחר שמלאכת הוצאה בשבת נוגעת במעשה אדם בחפץ ובמקום. יהיו גדרי המלאכה ושיעוריה קבועים לפי שלושה חלקים אלו, דהיינו מעשה האדם, החפץ, והמקום. ומקום וחפץ יוגדרו ע\"פ מה שעושה בהם האדם, והגדרת חפץ ומקום יגדירו את מעשה האדם, וחוזר שיכול מעשה האדם להגדיר החפץ והמקום.\u003c/span>"}, {"s": "h7", "h": "מקום וחפץ"}, {"s": "p", "h": "הנה המושג מקום נובע מהיחס להיות חפצים הנמצאים במקום, והיינו, שהמושג מקום בלי יחס החפצים נקראהו חלל, והוא המושג המופשט למקום לולי מושג החפצים."}, {"s": "p", "h": "ואחר שנשיג החפצים, וכיון שחפצים נמצאים במקום הוא החלל המוקדם, הרי שנמצא משמעות למושג חלל כמקום לחפץ, וזה יקרא מקום."}, {"s": "p", "h": "כמו\"כ המושג חפץ במובנו המופשט אין לו צורך במקום, שמשמעותו הקיומית אינה תלויה בהיות לו מקום, ואף אחר היות לו מקום לא יהיה מקומו חלק ממהותו."}, {"s": "p", "h": "אך אחר שישנו מושג המקום וכיון שמקום מכיל חפצים הרי שיש משמעות לחפץ גם במובן שהוא במקום."}, {"s": "p", "h": "והיינו שאחר שישנם המושגים היחסיים של חפץ ומקום, יוגדרו יחסים אלו כמושגם של חפץ ומקום בנפרד ביחס למשמעות זו, ויהיה זה היחס הבסיסי של מושגי חפץ ומקום, שיש שחפץ יש לו מקום, ויש שחפץ שאין לו מקום. וכן במקום, שיש שמקום מלא, ויש שמקום ריק."}, {"s": "p", "h": "ואחר שישנה יחסיות המושגים אפשר להגדיר את מציאותם של דברים, והיינו, שחפץ הנמצא במקום יחשב שיש לו מקום וכן מקום שיש בו חפץ יחשב שהוא מלא, וההיפך. ממילא יוגדר מצבם היחסי בנפרד דהיינו שמקום שיש בו חפץ ביחס לחפץ החפץ יוגדר שהוא נמצא במקום וביחס למקום שבמקום יש חפץ."}, {"s": "h7", "h": "מקום וחפץ והאדם"}, {"s": "p", "h": "וכל זה הוא ביחס למושגי מקום וחפץ שיוגדרו ביחס זה לזה, ולא יהיה משמעות למקומות נפרדים וחפצים נפרדים. אך ביחס לאדם יגדרו מושגים בנפרד, והיינו, שכיון שהאדם מתייחס לחפצים נפרדים באופן נפרד, וכן למקומות נפרדים באופן נפרד, הרי שמושגי מקום וחפץ יוגדרו באופן נפרד, והיינו, שאף שודאי שגם מצד המציאות דברים הם נפרדים, אך כיון שלא יהיה בהם שוני לולי יחס האדם, נפרדותם לא תגדיר את יחסיהם, אך אחר שיש להם משמעות לאדם הרי שיוגדרו הן מחמת נפרדותם והן מחמת כמותם, והיינו, שכיון שחפץ זה מוגדר בנפרד משאר חפצים מחמת משמעותו של האדם, הרי שהמקום שבו הוא נמצא יוגדר כמקום שיש בו חפץ זה, וממילא יוגדר מקום כדבר מחולק. וכן לעניין החפץ שכיון שמקום מוגדר בנפרד משאר מקומות מחמת משמעותו של האדם, הרי שחפץ שנמצא בו יוגדר כחפץ הנמצא במקום זה, וממילא יפרדו החפצים גם ביחס מקומם."}, {"s": "p", "h": "וכיון שמושג חפץ מסוים הנמצא במקום מסוים הוא מושג היחסי לאדם יוגדרו הם ע\"פ האדם, והיינו, שלא יחשב דבר הנמצא במקום כנמצא במקום אלא באם יחשיב האדם את החפץ כראוי למקום, וכן לא יחשב מקום להיות מקום חפץ, אלא אם יחשיב האדם את המקום כראוי לחפץ, ומזה יוגדרו גדרי שיעור החפץ וכן שיעור המקום."}, {"s": "p", "h": "וכיון שמושגי חפץ ומקום הוגדרו כבעלי משמעות נפרדת, יופרדו גם את מושגם העצמי ויוגדר כך, שנוכל להגדיר מקום שהיה בו חפץ ועכשיו אינו כמקום שהוא ריק מחפץ זה, וכן לגבי חפץ שחפץ זה יצא ממקום זה, וכיון שכך נוכל לומר שחפץ אחר הנמצא במקום זה כחפץ שנמצא במקומו הקודם של חפץ אחר, וכן חפץ הנמצא במקום זה כחפץ שאינו נמצא במקומו הקודם, והיינו, שיהיה למקום שם מקום בנפרד מהיות בו חפץ, וכן לחפץ יהיה שם מקום בנפרד מהיותו במקום."}, {"s": "h7", "h": "מקום חפץ ושימוש האדם"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"877\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">14\u003c/sup>\u003cspan class=\"ca\" data-c=\"877\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">והנה כל זה הוא רק ביחס האדם למשמעות מקום חפצים, אך ביחס לשימוש האדם בחפצים ובמקומות יוגדרו מקומות שימוש וחפצי שימוש ויחסיהם באופן אחר, והיינו, ביחס למקום שמקום המשמש לשימוש מסוים יחשב למקום וחפץ הנמצא בו יחשב כנמצא במקום, ומקום שאינו משמש לשימוש מסוים לא יחשב כמקום, וחפץ הנמצא בו יחשב כאין לו מקום. וכן צורת השימוש תגדיר את המקום, שמקום המשמש לשימוש אחד יחשב למקום אחד, וחפץ הנע במקום זה יחשב שלא יצא ממקומו, ומקום שאינו משומש לשימוש אחד לא יחשב מקום אחד וחפץ הנע במקום זה יחשב שיצא ממקומו, וכן ביחס בין מקומות אלו שמקומות בעלי שימושים נפרדים יחשבו למקומות נפרדים.\u003c/span>"}, {"s": "p", "h": "וכן ביחס לשימוש האדם ששימוש במקום הנחשב שימוש אחיד יגדיר את המקום הנ\"ל כמקום אחד, וחפץ הנע במקום זה לא יחשב כיצא ממקום."}, {"s": "p", "h": "והנה אין כוונתנו שהיחס השימושי יבטל את המשמעות המוקדמת שיש לחפץ ומקום ביחס ביניהם, וביחס לאדם, וכן שמשמעות זו לא תבטל את המשמעות המוקדמת שיש למקום וחפץ, והיחס ביניהם בלבד, אלא הם רובדים נפרדים שמשמעותם הנוספת נוגעת רק לרובד הגבוה מהם."}, {"s": "p", "h": "והנה שלושה בחינות מציאות אלו מגדירות משמעויות שונות במקום וחפץ. א. מציאות חפץ ומקום והיחס ביניהם מגדיר את המשמעות של חפץ הנמצא במקום ושל מקום המכיל חפץ. ב. מציאות חפץ מקום והאדם והיחס ביניהם מגדיר את המשמעות של חפצים נפרדים הנמצאים במקומות נפרדים. ג. מציאות חפץ מקום ושימוש והיחס ביניהם מגדיר את המשמעות של חפצים מסוימים במקומות מאוחדים."}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"880\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">17\u003c/sup>\u003csup class=\"cb\" data-c=\"879\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">16\u003c/sup>\u003csup class=\"cb\" data-c=\"878\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">15\u003c/sup>\u003cspan class=\"ca\" data-c=\"878 879 880\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">חילוקי רשויות\u003c/span>"}, {"s": "p", "h": "גדר הכולל ריבוי רשויות נפרדות - חילוק גדרם כמקום וכרשות ובכל אחד בקיומו ובנפרדותו "}, {"s": "p", "h": "הנה במה שאמרה תורה שלא להוציא מרשות לרשות יש לשמוע גדר הכולל כל הרשויות הנפרדות לעצמם (היינו, שגדרם כרשויות אינו כחלק ממשמעות שיש בכל הרשויות יחד) לגבי מעשה הוצאה, וגדר כולל שיש למצוא בהם הוא במה שהם מקום המשמש ליעוד, וחילוק רשויות בגדר זה הוא בשני גדרים, האחד, בגדרם כמקום. והשני, בגדרם כרשות. ובגדרם כמקום יש למצוא שני פנים, בקיומו ובנפרדותו, בקיומו, היינו, בהבדלת מקום ממה שאינו. ובנפרדותו, בהבדלת מקום ממשנהו. וכן בגדרם כרשות, בקיומה, בהבדלת מקום המיועד לאיזה דבר ממה שאינו, ובנפרדותה, בהבדלת יעודם שזה לשימוש זה ומשנהו לאחר."}, {"s": "p", "h": "ונמצאם כולם בארבע רשויות של שבת, שרה\"י היא מקום ומיועדת לשימוש (תשמיש היחיד), ורה\"ר היא מקום ומיועדת לשימוש (הילוך הרבים), וכרמלית היא מקום ואינה מיועדת לשימוש. ומקום פטור אינו מקום וממילא אין שייך בו יעוד (ואף שיהיה מיועד אין זה מקום המיועד). וממילא יש להבין חילוק דיניהם, שדין טלטול ארבע אמות הוא עניין הנוגע למקום חפץ, שמקום שימוש חפץ הוא בכל ד' אמות שסביבו, ובאחידות המקום, היינו, שכשהמקום אחיד, לא יהיו שני מקומות לחפץ ברשות זו, וכל המקום יהיה מקומו. ולכן יאסר לטלטל ברה\"ר ובכרמלית שאינם מקום אחיד, ולא יאסר ברה\"י. ומקום פטור שאינו מקום כלל גם יהיה מותר, כי לא יצא ממקום ולא נכנס אל מקום."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"106\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">18\u003c/sup>\u003cspan class=\"ca\" data-c=\"106\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ודין להוציא מרשות לרשות נוגע למקום החפץ כדלעיל, ולשינוי הרשויות במובן השימוש שבהם, ולכן יהיה אסור להוציא מרה\"ר לרה\"י וההפך, כי הם רשויות שונות מבחינת שימושיהם, וע\"כ גם יקראו מקומות שונים ביחס לחפץ. וכן מרה\"י ורה\"ר לכרמלית שהיא אינה בעלת שימוש, ולכן יקראו מקומות שונים ביחס לגדר הרשות כמקום שימוש, אך למקום פטור שהוא אינו מקום כלל, יחשב כאילו הניחו בלא מקום.\u003c/span>"}, {"s": "h5", "h": "נושאי דיני הוצאה ברשויות"}, {"s": "h7", "h": "חילוקי רשויות, מחיצה ופרצה, תקנות עירובין, ומעשה ההוצאה האסורה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"881\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">19\u003c/sup>\u003cspan class=\"ca\" data-c=\"881\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">דיני הוצאה ורשויות מן התורה ותקנות חז\"ל מתחלקים לכמה נושאים הנצרכים ביאור וגדר. א. מהות הרשויות עצמם לאופיים השימושי והמבנה הממשי. ב. ההפרדה וההגדרה (מהם מחיצה ופרצה) הנובעים מהמבנה הממשי של הרשות. ג. תקנות חז\"ל הנוגעות לשינוי המבנה השימושי (עירוב וכדומה). ד. ההוצאה האסורה (הנחה ועקירה, ד' אמות, וכן דין כלי בית ועוד).\u003c/span>"}, {"s": "p", "h": "והנה מהיות כי רשויות של תורה וגם חילוקי רשויות מדרבנן בעלי הגדרות עצמיות, ותנאים כנצרך להם, ועוד יש בהם תנאים ודינים הנובעים מעירובי הרשויות הללו (שגם הם יוצאים מכח הגדרתם העצמית או מתקנות החכמים ז\"ל להצריכם הגדרות נוספות שאינם עיקר הגדרתם מן התורה), כי בשינוי קל תובחן ותושפע גדר הרשות, ויועיל בזה החילוק יותר על ההשוואה."}, {"s": "p", "h": "חילוק גדרי רשות דאורייתא מדרבנן - רשות דאורייתא נוגעת רק למקומו של חפץ "}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"882\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">20\u003c/sup>\u003cspan class=\"ca\" data-c=\"882\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">וגדר ההבדל בין רשות דאורייתא (היינו, הדינים שנאמרו בתורה שביחס להם יש להיות דין רשות), ובין רשות דרבנן. כי מן התורה אין משמעות לרשות מלבד לדין הוצאת חפץ, וכל גדרי רשויות דאורייתא נוגעות רק למשמעותם כמקומו של חפץ, ואף אי נימא דאל יצא איש ממקומו, היינו, אל יוציא, האי מקומו הוא מקומו של איש, וזה לכאורה גדר במקום אדם ולא במקום חפץ. אין זה אלא משום דגם גדר חפץ הוא מושג בשימושו של אדם, וע\"כ יהיה גדר מקומו ביחס למושגי מקום של אדם. אבל אין זה משום דדין הוצאה במקום אדם, והיינו, שנאמר דגדר הוצאה הוא הרחקת החפץ מאדם, והרחקה מאדם ביחס לחפץ היא במקום, וע\"כ יהיה הגדר מקומו של אדם, וכמו שהיה אפשר לומר בדין איגודו בידו, ובזה נשתנה גדר העברה ביד מזריקה. דזה אינו, דבזה הרי אין משמעות לשינויי רשויות דרה\"ר והיחיד, וגדר העברה ברה\"ר בגדר אחד, דנימא דגדר אחד לשניהם ביחס להוצאה. ובהכרח דגדר מקום והוצאה הוא גדר במקום חפץ, ואין גדר מקום אדם בגדר מקום חפץ אלא משום דאין חפץ אלא ביחס לאדם, וע\"כ יהיה מקום חפץ ביחס לאדם ומקומו. וזה מוכח גם מעצם שינוי שיעור ד\"א דהעברה משיעור ד\"ט דרה\"י ומקום חפץ, ובהכרח דאיכא לדין מקום חפץ (וכן משמע ממה דאמרינן ידו של אדם חשובה וכו' וגדר אחשביה ביחס למקום ד\"ט, דאם היה הגדר ביחס לאדם, הרי היה לומר בהיפך דכל דין ד\"ט למקום חפץ הוא ביחס לאדם, ויש בזה ראיות רבות. ואכמ\"ל), והיינו, גדר הכנסה והוצאה והעברה, וזה גם משמעות שם הבאה דלשון תורה, דאין משמעות הבאה ביחס לעצם התרומה, ושם הבאה, היינו, שאף דאין חסרון בעצם התרומה, הרי שביחס להבאת התרומה הרי די למלאכה. וזה הרי בהכרח גדר בחפץ.\u003c/span>"}, {"s": "h7", "h": "הגדרת מושג רשות כמקום המיועד לשימוש - התאמת המקום לסוג התשמיש והמשתמש והצורך בהפרדת מקומות"}, {"s": "p", "h": "והנה המושג הראשי שממנו יוצאים עיקרי הדינים הוא רשות שמשמעותו מקום שהוא מיועד לשירות שימוש מסוים, ושימוש זה כולל בתוכו חלוקה על פי סוג התשמיש, וסוג המשתמש. ובכדי להגדיר מקום שהוא מיועד לשימוש מסוים (רשות), נצטרך להתאים את המקום המיועד לשימוש הנ\"ל תוך שימוש בתנאים המגדירים הנמצאים במושגי שימושי המקום הכלליים (טרם הגדרת השימוש המיועד), ע\"פ התנאים שמחייב השימוש המסוים שהמקום יועד לו, ודבר זה נכון גם לכשנרצה להגדיר מחדש מקום שימוש מיועד ליעוד שונה ממנו כבתקנות החכמים ז\"ל. ומעתה נאמר שאף הצורך בהפרדת מקומות לצורך המושג רשות, סיבתו, מהיות מקומות מיועדים לעניינים שונים, השוני (המצוי והמְצוּוֶה) מחייב הבדלה בין אחד למשנהו על מנת לשמר כל מקום כמקום השימוש המסוים, ושיהיו מוגדרים לעצמם כמיועדים לשימוש מסוים זה ולא זה, ופשוט. ועפ\"ז נצטרך לדון בע\"ה בכל עניין בגדרי השימוש שלו, ועי\"ז, על מהות המקום הנצרך לשימוש זה ועל גדרי המקום (טרם הגדרת היעוד)."}, {"s": "h7", "h": "שני מרכיבים המשפיעים על הרשות - מבנה ממשי בששת צדדיה מול אופי השימוש בה"}, {"s": "p", "h": "והנה מצאנו בדיני רשות שני מרכיבים אשר משפיעים על אופי הרשות. חלקם ישפיעו על עיקר דין התורה דרשות היחיד, הרבים ומקום פטור, וחלקם ישפיעו רק על דינים דרבנן כמו כרמלית, ודינים הנובעים מתקנת עירובי חצרות. האחד, הוא מבנה הרשות הממשי, היינו, הגודל (גובה, מרחב), גידור ששת צדדיה (ארבעה צדדים, תקרה, וקרקע). והשני, הוא אופי השימוש שברשות, היינו, סוג השימוש (נוח, מיוחד, תדיר, צנוע, לאוויר שחוצה לו, לאוצר, חוסר שימוש, ועוד), סוג המשתמשים (יחיד, רבים, שותפים, אורחים, גזלנים, ועוד)."}, {"s": "p", "h": "(ואע\"פ שכאמור ביסוד כל הדינים והגדרים המשתנים מונח אופי השימוש, והגדרים נקבעו על פיו, בין ע\"י שיעורים מהלכה למשה מסיני, ובין ע\"י קביעת חכמינו ברוחב ועומק דעתם וברוח הקודש, עדיין יש לנו לחלק בין אלה שמושפעים מאופי השימוש באופן ישיר לבין אלה שכבר הועמדו לשיעורים קבועים.)"}, {"s": "p", "h": "גדרי רשויות קודמים לצורת מקומן - רה\"י ורה\"ר עומדות לעצמן ודיני צורתן התאמה להן "}, {"s": "p", "h": "והנה שיהיו חילוקי רשויות בצורתם ובשימושם, גדרי רה\"ר ורה\"י החלוקים אינם נובעים מצורת מקומם, שאף רשות בעלת מחיצות יש למצוא שתחשב רה\"ר, ואף רה\"י בעל גודל טז' אמה תחשב רה\"י, כי דינים הנוגעים לצורת הרשויות אינה גדר הרשות עצמה ואין גדרה נובע מצורתה, אלא בהיפך שגדר הרשות עומד לעצמו, ודיני צורת הרשות הם התאמה לגדר זה. שרה\"י עצמה יש לה משמעות אף בלא תנאיה, אלא שלהגדיר מקום כרה\"י אנו נדרשים שיהיו לו מחיצות וכו', וכן רה\"ר להגדיר מקום בשמה נדרש טז' אמה וכו'. והנ\"ל לכאורה תלוי בגדר הרשות עצמה."}, {"s": "h5", "h": "חילוקי השימושים הכלליים ברשויות התורה ומדרבנן"}, {"s": "h7", "h": "ארבע רשויות בחילוקי השימושים הכלליים - שימוש היחיד, שימוש הרבים, מקום פטור, וכרמלית"}, {"s": "p", "h": "והנה חילוקי השימושים הכלליים הנזכרים הם: א. שימוש היחיד שמקומו נקרא בכל מקום רשות היחיד. ב. שימוש הרבים שמקומו נקרא בכל מקום רשות הרבים. ג. ושימוש שאינו אחד מאלו אינו נחשב שימוש להגדיר מקומו על פיו, וכן מקום שאינו ראוי לשימוש (שאין יתכן להגדיר אותו כאחד מן משני הרשויות השימושיות שכוחם מאופי שימושם), ומקומו נקרא מקום פטור. ד. עוד רשות אחת מדברי חז\"ל היא כרמלית, שהחשיבוה בתנאיה המסוימים כרשות נפרדת. (ולא מצאנו לו הגדרה שימושית אחידה, ואפשר שנתנו לו חכמים הגדרה רק ע\"פ תנאי מקום הממשי. וכן שם כרמלית ניתן כהגדרה איסורית (לעניין הוצאה וטילטול בתוכו) למקומות שאינם מתוקנים כתקנת חז\"ל, ובלי שייכות לגדרים המבניים של כרמלית)."}, {"s": "h5", "h": "רשות כמקום שימוש"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"883\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">21\u003c/sup>\u003cspan class=\"ca\" data-c=\"883\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">וביאור חלוקה זו, כי משמעות רשות כמקום שימוש, היינו, שגדרי מקום הרגילים יגדירו מקום של דבר רק אם נמצא בו, ורק ביחס לחפץ מסוים. אבל רשות משמעה מקום שהוא מיועד לשימוש. ויש בזה שני שינוים מגדר מקום, גם שאינו מיועד לחפץ מסוים אלא לשימוש. וגם שהוא אינו מוגדר ע\"י שימוש בפועל אלא ע\"י יעודו לשימוש.\u003c/span>"}, {"s": "p", "h": "והנה מאחר דגדר רשות נובע ממשמעות מציאות מקום ביחס לשימושי האדם, וכמ\"ש לעיל שמקום המיועד לשימוש מסוים יחשב כרשות נפרדת ומקום אחד. וביחס לזה נמצא שלושה מיני רשויות."}, {"s": "p", "h": "(ואין מקום פטור מהן, אחר שאינו מוגדר ביחס ליעוד שימושו (או לחוסר יעוד ככרמלית), אלא בהיעדר חשיבות להיות בעל יעוד כל שהו.)"}, {"s": "p", "h": "גדר מקום רשות ותנאיו - מקום המכיל ומקום דבר, קרקע ורוחב "}, {"s": "p", "h": "והנה כמש\"כ בגדר מקום המוזכר בדינים אלו, דיש למצוא בו שני גדרים. האחד, מקום שלעצמו, היינו, מה שיכול להכיל דברים. והשני, מקום של דבר, היינו, שדבר זה נמצא במקום הנ\"ל, ובגדר זה אין למקום משמעות עצמית."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"107\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">22\u003c/sup>\u003cspan class=\"ca\" data-c=\"107\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">והנה אף שלגבי מקום סתם כל שיהיה בו גדרים הנ\"ל, יש להחשיבו כמקום. לגבי שם רשות, היינו, שיהיה המקום חשוב מקום רשות, ושיהיה דבר הנמצא חשוב ברשות, מצאנו שני דינים. האחד, שיהיה לו קרקע ולא אוויר. והשני, שיהיה רחב ד' על ד' טפחים.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"884\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">23\u003c/sup>\u003cspan class=\"ca\" data-c=\"884\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ותנאי הראשון שיהיה קרקע ולא אוויר, הוא שיהיה לו בסיס להנחת דברים. והיינו, שאף שאוויר שווה לקרקע לענין מה שיכול להכיל דברים, לגבי היות המקום חשוב כרשות צריך שיהיה בו גם יכולת הינוחם, וביאור הדבר הוא כי אין גדר מקום כרשות רק ביכולתו להיות בו דבר, אלא צריך גם שיהיה מוכן לכך, וכיון שדברים ללא תנועה אינם יכולים להתקיים שם לזמן, אין זה נחשב שמוכן לכך. וביאורו כי משמעות מקום לדבר הנמצא בו כמקומו הוא בשני גדרים. האחד, בעצם הקיום, שאין קיום לדבר ללא מקום. והשני, שהוא מקומו ביחס לשאר מקומות. ויהיה גדרים אלו משמעות במקום שלעצמו, האחד, כחלל שיש יכולת להכיל דבר. והשני, כמקום שיש בו יכולת למקם דבר.\u003c/span>"}, {"s": "p", "h": "קרקע ואוויר כשתי משמעויות במקום – קדימתם לגדר חלל ומשמעות קביעות ברשות "}, {"s": "p", "h": "וביאור הדברים בהקדם גדר חלל דרשות, והיינו, דכמו שאמרנו יש לקרקע משמעות מקום נוספת ביחס לסתם מקום, במה שהיא מקום קבוע ויציב, וע\"כ יש לה משמעות כיסוד ביחס להיות מקום רשות שימוש, וביחס למה שיש ברשות משמעות שימוש חשובה (עוד יותר ביחס לסתם שימוש קבוע), והנה שם מקום שאין לו משמעות זו קרוי בכל מקום אוויר, וכמו שאמרנו אף אוויר זה נחשב מקום שימוש, שניתן להשתמש בו, וא\"כ יהיה לנו שני גדרים הנוגעים למשמעות מקום דשימוש, וכיון שאין שימוש בעצם פני השטח כי רק יסוד לקיום השימוש, הרי שהמושג קרקע הוא גם בגדר מקום הפחות הנ\"ל, היינו, אוויר, אלא שבהיות לו קרקע יש לו משמעות נוספת שהוא יציב וקבוע, וא\"כ ביחס למושגי מקום דרשות יהיה משמעות לקרקע במה שהיא יוצרת קביעות שימוש לאוויר שעימה, וע\"כ כשנרצה להגדיר רשות אף שאין צורך לשימוש כל דהוא דווקא בקרקע, הגדרת מקום עצמו כרשות שימוש הרי היא ביחס לקרקע, שמושג רשות הוא גדר במקום כמוקם שימוש קבוע."}, {"s": "p", "h": "גדר רשות בשימוש הקבוע במקום – שלא יחשב שימוש ארעי להגדרת הרשות "}, {"s": "p", "h": "ובזה יבואר שאף אמנם שימוש כל דהוא הרי אפשרי בכל מקום פנוי, ובכלל שהוא אינו צריך להכנה (במובן כן ולא במובן הקדמה), אך גדר רשות שימוש אינו ביחס לשימוש כזה אלא ביחס לשימוש הקבוע, והוא בהכרח גדר נפרד ממושגי שימוש סתם, וכמו בקנין דחפץ שנאמר שחפץ שייך לאדם מסוים, שאף אין שייכות בין חפץ עצמו (בקיומו ובסגולותיו השימושיים) למושגי קנין אדם בו, אלא הוא מתקיים אחר שיהיה שייכות בין אדם לחפץ, והוא גדר מגביל ביחס לעצם מושג חפץ הכולל, וכן הוא ביחס לשימוש ורשות שמושג השימוש עצמו אין לו הגבלה לרשות, אלא שביחס לשימוש בצורה מסויימת, תהיה רשות הגדרה בשימוש (ואכן גם גדרים האמורים אינם דווקא במקום כרשות לענין שבת, ויש למצואם גם ביחס לשאר מקומות שמשמעותם מקומות שימוש), וכן בגדרי מקום הרי שמשמעות מקום ביחס לרשות שימוש, מוגדרת בגדרי מקום עצמו (וראה כי זה משמעות שם רשות בכל מקום, היינו, השייכות בין דבר שבעצמו אינו מוגבל ביחס לדבר אחר שמגבילו ומגדירו), והיינו, אוויר. וביחס לקרקע כמכון דרשות נדבר ממושגי אוויר של קרקע, וכמו שכתבנו שאף שעצם גדר אוויר קרקע אינו נוגע לעצם המושג שימוש בקרקע, שזה שייך אפילו יותר מאוויר קרקע, כיון שרשות נוגעת לשימוש בקרקע, יש לנו לבאר עד היכן נחשב אוויר שאינו קרקע, כחלק מקרקע."}, {"s": "h7", "h": "רשות היחיד"}, {"s": "p", "h": "רה\"י. היא מקום המיועד לשימוש של היחיד."}, {"s": "p", "h": "טבעו של שימוש היחיד שהוא שימוש של מנוחה, דהיינו שמניחים בו חפצים לשומרם ולהשתמש בהם במקומם, ובזה הוא שימוש תכליתי. וכיון שכך כשנתאים מקום להיות רה\"י נצטרך שיהיה גדור לעצמו, ומקום כזה ממהותו הוא מיועד לשימוש אחיד, כיון ששמירה היא הגדרה חיובית אחידה לכלל המקום, ונחשב כל המקום כמקום אחד."}, {"s": "h7", "h": "רשות הרבים"}, {"s": "p", "h": "רה\"ר. היא מקום המיועד לשימוש הרבים."}, {"s": "p", "h": "טבעו של שימוש הרבים הוא שימוש של מעבר, דהיינו שאין חפץ שמקום הנחתו מיועד להיות ברה\"ר, אלא חפצים מקומם ברה\"י, ורה\"ר משמשת כמקום מעבר מרה\"י לרה\"י. וכיון שכך כשנתאים מקום להיות רה\"ר נצטרך שיהיה רחב, ונוח להילוך, ושיהיה בעל מעבר נוח, ומקום זה ממהותו אינו מיועד לשימוש מנוחה, ואפילו כשיונח חפץ לא יהיה לו מקומו אשר תחתיו אחד."}, {"s": "h7", "h": "רשות כרמלית"}, {"s": "p", "h": "כרמלית. היא מקום ללא יעוד שימושי."}, {"s": "p", "h": "משמעות המושג כרמלית שהיא לא רה\"י ולא רה\"ר, והיינו, שאין בה את הגורם המאחד של רה\"י שהיא משמשת לשימוש אחיד, ואין בה את הגורם המבדר של רה\"י שהיא משמשת לשימוש מעבר. ועל לא תחשב כרה\"ר ולא כרה\"י."}, {"s": "p", "h": "איסור הוצאה ברשויות דאורייתא - שינוי מקום כנוס ברה\"י למקום מוצא ברה\"ר "}, {"s": "p", "h": "והנה מן התורה לא נאסרה הוצאה אלא ברה\"ר ורה\"י, ויובחן שאין זה מעצם שם הוצאה (היינו, שיהיה שם הוצאה מרשות לרשות כולל גם הוצאה מרה\"י לרה\"י החלוקה ממנה), הוא כי גדר מעשה ההוצאה מרשות לרשות הוא עשייה שחפץ הנמצא ברשות אחת יהיה ברשות שניה, והיותה רשות שניה מוגדרת כך במופרדות השטח, וזה שייך אף בשני רשויות היחיד ובשאר רשויות. אך איסור התורה נאמר רק על הכנסה או הוצאה (במובנה היחסי להכנסה). והיינו, שבפשטות היה לומר שגדר המלאכה האסורה היא כל שינוי מקומו של חפץ, ומה שאין כלל בזה הוצאה מרה\"י זה לרה\"י זה, הוא משום שאין חשוב מקום זה שונה ממקום זה אלא רק בשינוי רשויות הנ\"ל. אבל מלשונו לא משמע כן, אלא כל רשויות הנפרדות חשובות כמקומות שונים לגבי שם הוצאה, וגדר מה שאסרה תורה דווקא ברשויות הנ\"ל הוא משום שרק בזה יהיה שם מלאכה. ולכאורה זהו גדר במשמעות מקום חפץ, היינו, שהיות חפץ ברה\"ר מלבד מה שהוא במקום  מסוים (עצם הגדרת מקום הוא מסוים), יש לו משמעות שהוא מוצא, ולהיפך שהיות חפץ ברה\"י יש לו משמעות שהוא כנוס."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"108\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">24\u003c/sup>\u003cspan class=\"ca\" data-c=\"108\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ובזה יש לנו להגדיר רשות כרמלית שהיא לא כרה\"י ולא כרה\"ר, והיינו, שאין בה איכות רה\"י להחשיב את כלל מקומותיה כמקום אחד, ואין בה איכות רה\"ר להחשיב מקום המשמש חפץ אחד למקומות נפרדים. וע\"כ המוציא מרה\"י לכרמלית פטור ולא חשוב כמוציא, כי אף שביציאתו אליה בטל ממנו שם כנוס כיון שבהיותו בה אינו חשוב מוצא אין זה מלאכה שנאסרה, וכן לאידך.\u003c/span>"}, {"s": "h5", "h": "רשות ביחס לחפץ המונח בה"}, {"s": "p", "h": "הנה מה שכתבנו במה שרה\"י היא אחידה ורה\"ר אינה, הוא רק ביחס לחפץ המונח בה. שוודאי שאף רה\"ר היא רשות אחידה לעצמה שהרי יש שיעור ותנאים הנוגעים לכלל הרשות, אלא שרה\"י ביחס לחפץ הנמצא בה דרוש שיהיה השימוש בה אחיד, כמו שישתמש האדם במקום אחד, ובמובן שהוא ביחס מקום וחפץ לאדם, ולא לשימוש. וזה אינו ברה\"ר שאין משמעות אחידה לשימוש בה."}, {"s": "p", "h": "ועכ\"פ מקביעת שלש רשויות של תורה אלו נלמד, שאע\"פ שישנם שימושים רבים ושונים, החילוקים הנוגעים לדיני רשויות הם רק חילוקי שימושים אלו, ואמנם ניתן ליחס לשימושים אלו כמה מרכיבים, כמו כמות המשתמשים, וסוגי השימושים, אבל יסודם הוא, בהגדרת שימושים אלו כשימושי יחיד ושימושי רבים על כל פנים."}, {"s": "h7", "h": "הבחנה ממונית בין רה\"י לרה\"ר - שימוש היחיד בזכותו מול שימוש הרבים בהפקעת מניעה"}, {"s": "p", "h": "עוד יש לבאר, שההבחנה העיקרית בין רשות היחיד לבין רשות הרבים (חילוקי הרשויות מן התורה) היא כעין המשמעות הממונית שלהם, וכמו חילוק שיש בדינים הממוניים בין אדם שמשתמש בחפץ שלו, שגדר השימוש הוא כפועל יוצא מזכותו והשלמת היעוד הממוני שלו, לבין אדם שמשתמש ברשות הפתוחה לכל, וגדר שימושו אינו מחמת שיש לו זכות במקום, אלא רק שאותו מקום מופקע מזכות אחר למנוע, והרי שאין בשימושו קיום של זכות כלשהי, וכן בענייננו, רשות היחיד מיועדת לשימוש של אדם פלוני באופן חיובי, שהיא שלו ולא של אחרים, ושימושו בה נובע מזכותו, ויש בשימוש זה מימוש היעוד של זכותו ברשות זו. ולעומת זאת רשות הרבים אמנם גם היא מיועדת לשימוש של אותו אדם, אבל לא באופן חיובי, ולא בגדרו המסויים משאר אנשים, אלא רק מחמת שהיא מקום שמיועד לכל אדם, ולכן גם שימוש של שותפות, יחשב לשימוש היחיד, אפילו אם הוא מרובה שותפים, שכל אחד משתמש כאן בזכות ותראה כי בזה רשות הרבים היא היעדר הגדרה במשמעות הגדר הפרטי (אמנם אין רשות הרבים אי הגדרה של רשות בעצם, שאף לה ישנם תנאים חיוביים להיות ראויה לשימוש הרבים, רק שביחס לפרטיות השימוש, חוסר תנאי זה ברשות הרבים הוא אי הגדרה)."}, {"s": "p", "h": "ואם כי דיני רשויות אלו וחילוקי השימושים העקרוניים ניתנו רק כהגדרות למקום הממשי שלהם, כמו גודל וכו', אבל מכמה מקומות נראה כי יש השפעה אף לשימוש בפועל כהגדרתו לכל שימוש (רבים, יחיד). ועיין להלן."}, {"s": "p", "h": "חילוקי גדרים ברשות במקומה – משמעותם הנפרדת והמאוחדת "}, {"s": "p", "h": "והנה יש נמצא כמה גדרים בהגדרת רשות, וחלוק לשלושה א. קרקע ב. מקום ג. רשות. ואין רשות אלא בקרקע, ואין מקום אלא בקרקע."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"109\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">25\u003c/sup>\u003cspan class=\"ca\" data-c=\"109\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וחילוק גדר מקומם כך. הגדרת קרקע היא ע\"י מחיצות, וזה בשני גדרים. א. קרקע נפרדת ע\"י מחיצות. ב. קרקע אחידה ע\"י ד' מחיצות. והגדרת מקום היא ע\"י היקף, וזה בשני גדרים. א. מקום נפרד ע\"י היקף. ב. מקום אחיד ע\"י שימוש אחיד. והגדרת רשות היא בשימושיות, וזה בשני גדרים, א. רשות נפרדת ע\"י סוג השימוש. ב. רשות אחידה ע\"י יחודה.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"885\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">26\u003c/sup>\u003cspan class=\"ca\" data-c=\"885\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">וגדרם המאוחד דרשות המקום בקרקע, שתהיה ראויה קרקע המקום לאחד את כל שימושיה, שיחשבו שימוש באותו המקום, וזה מוקדם לשימוש, והיא הגדרה ביחס לכל חלק וחלק בנפרד. אך אף אחר שיהיה זה הגדר יש לנו להחשיב את כלל השימוש במקום לאחד, וזה ההיקף. ואחר כל זה יש לנו להגדיר את הרשות ע\"פ מה שהמקום משמש. ואמנם אין היקף דשתי וערב ראוי להחשיב את כלל המקום לאחד ביותר מבית סאתים. אך כיון שהמקום הוקף לדירה, ומשמש כדירה, הרי שהשימוש מחשיב את המקום כאחד, וממילא את כלל המחיצות כאחד. ונמצאו ארבעה שלבים. מחיצות לקרקע שיחשב מקום. והיקף למקום שיחשב משמש. ושימוש במקום שיחשב רשות. ורשות לטלטול שלא יחשב העברה. ודיורין לרשות שיחשב הוצאה.\u003c/span>"}, {"s": "h4", "h": "רשות היחיד"}, {"s": "h7", "h": "גדר רשות היחיד כמותאמת לשימוש היחיד - דין ההבדלה וההפרדה במבנה הממשי כתנאי לייחוד הרשות"}, {"s": "p", "h": "כמו שכתבנו לעיל גדרו העיקרי של רשות היחיד הוא, שיהיה ראוי לשימוש היחיד כדרך המשמעות הממונית של חפץ היחיד, והיינו, שהוא מותאם באופן פרטני לשימוש של איש (או אנשים מסוימים), ולכן דין ההבדלה וההפרדה של רשות היחיד הוא כל כך מהותי בדינו, שהרי כל מהותו שהוא מיוחד, וההבדלה היא החלק החיצוני של הייחוד."}, {"s": "p", "h": "והנה לרשות היחיד ניתנו כמה תנאים במבנה הרשות הממשי, ועל פיהם תיקרא רשות היחיד מן התורה בכל מקום."}, {"s": "p", "h": "וברשות היחיד המוגדרת כך ע\"י המבנה הבסיסי שלה (ושאין בה סיבות פנימיות שיגדירוה כרשות הרבים, כפלטיא וכו'), ישנם כמה סוגים הנזכרים אצלנו."}, {"s": "p", "h": "חלקם מושפעים מאופי השימוש שבאותו מקום ומהם בית, חצר, מבוי (שיש להכלילו מסוגי החצר), גג, קרפף, דירה העשויה לצורך שחוצה לה. וחלקם המושפעים ע\"י המבנה עצמו כמו מקום שגודלו יותר מבית סאתיים, שמחיצתם אינה שתי וערב, ומחיצה העומדת מאליה."}, {"s": "p", "h": "איכות רשות היחיד ושם הכנסה – בהכלתה יהיה חפץ כנוס וכלל מקומותיה מקום אחד "}, {"s": "p", "h": "והנה משם הכנסה הנאמר במעביר לרה\"י ושם הוצאה הנאמר במעביר לרה\"ר יש ללמוד על גדרי הרשויות עצמם. והיינו, שיש ברה\"י איכות שחפץ הנמצא בה חשוב ככנוס, ובזה גדר החפץ שנמצא ברה\"י אינו ביחס למקום שהוא נמצא בו ממש, ושהוא נמצא במקום שיש עליו שם רה\"י. אלא הרי הוא נחשב כנוס בכלל הרשות, והוא איכות נוספת בחפץ חוץ מהמושג מקומו של חפץ. ומזה נלמד על גדרי רה\"י שכלל מקומותיה חשובים כמקום אחד. ויתבאר בע\"ה כי גדר רשויות אלו נובע משני סוגי תשמישין שיש לאדם, וצורך שיש לו בהיות לו מקום מוכן לתשמישין אלו. האחד, תשמיש. והשני, מעבר (הילוך). ורה\"י היא מקום המוכן לתשמיש, ורה\"ר היא מקום המוכן למעבר."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"110\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">27\u003c/sup>\u003cspan class=\"ca\" data-c=\"110\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ותראה כי שני סוגי תשמישין אלו יגדירו את מקום הרשות באופן שונה, כי מקום שימוש הוא קבוע, ומשמעותו שווה בכל המקום, ומקום מעבר הוא ארעי, ואין משמעותו אלא במקום שעובר בו, וע\"כ יהיה נובע מזה גדר חפצים המונחים ברשויות אלו, שדבר הנמצא ברה\"י עומד לשימוש במקומו, ודבר הנמצא ברה\"ר עומד להעברתו. ששימוש ברה\"ר הוא שימוש אמצעי, ושימוש ברה\"י הוא שימוש תכליתי.\u003c/span>"}, {"s": "p", "h": "והיינו, שכיון שרה\"ר היא המשמשת כמעבר לרשויות אחרות אין בה מקום להינוח דברים, אלא למהלכים של דברים, ואם יונח בה דבר לא יוגדר זה כמקומו של דבר. אך רה\"י שהיא לשימוש דבר המונח בה יחשב הדבר כנמצא בכל המקום, וכן לא יהיה בה מקום למעבר, ואם יעבור בה דבר לא יחשב כדבר שהתקדם."}, {"s": "h5", "h": "המבנה הממשי של רשות היחיד."}, {"s": "p", "h": "מצאנו כמה דינים הנוגעים למבנה הממשי של רשות היחיד והאפשרויות ליצור אותו עיקר הדינים מחולקים לשתי תנאים: א. הדין העיקרי של רשות היחיד היא שתהיה גדורה לעצמה. ב. דין נוסף הוא שתהיה בגודל הראוי לשימוש, ודין זה הוא דין כללי הנוגע לכל מקום שנרצה שיהיה ראוי לשימוש. וכן מצאנו דין שרשות היחיד עולה עד הרקיע."}, {"s": "h6", "h": "דין שתהיה גדורה לעצמה."}, {"s": "p", "h": "דין רשות היחיד שתהיה גדורה לעצמה איתא בכמה מקומות, ומקרה הפשוט הוא שגדורה במחיצות, ואמנם בברייתא דד' רשויות הובאו שני מקרי רשות היחיד אחרים, וסה\"כ שלושה והם: א. חריץ שהוא עמוק עשרה (גידור) ורחב ארבעה על ארבעה (שם מקום). ב. וכן תל שהוא גבוה עשרה (גידור) ורחב ארבעה על ארבעה. ג. עוד דין בו רשות נקראת גדורה הוא כשיש לה מחיצות (גדר דקה הסובבת את המקום הנרצה), והנה למרות שלהגדיר מקום צריך שיהיה גדור לחלוטין, מצאנו שלא צריך שיהיו מחיצות ממש שסוגרות את כל המקום."}, {"s": "p", "h": "כהקדמה לסוגי ההגדרה של רשות היחיד, יש לחלק בין גידור לצורך הרחקת מפריע מסוים, שגידור זה הוא אינו חלק מעיקרי דין הרשות, לבין גידור הנובע מעצם הגדרת הרשות, שגם אם יסודו בהרחקה מן החוץ, ברי שאינו מתייחס למפריע מסוים, ולכן גידור זה הוא חלק מעצם ההגדרה של הרשות. "}, {"s": "h6", "h": "תל"}, {"s": "p", "h": "והנה בשתי הדוגמאות הראשונות שאמרנו, היינו חריץ, וגדר (וכאמור שהן בלבד הובאו כדוגמה לרשות היחיד בכל מקום. ע' בריתא הנ\"ל (שבת ו.)) נראה שאין אנו צריכים לדיני מחיצות, שכן הרשות מוגדרת לעצמה, ואינה מופרעת ע\"י רשויות אחרות. ועדיין יש לחלק בין המקרה הראשון, בו ישנם גבולות ברורים מכל צידי הרשות הראויה לשימוש (מלבד תקרה), לעומת המקרה השני, בו לכאורה יש אמנם גבולות כלפי חוץ, אבל לא גבולות כלפי פנים, שכן אין לתל גבולות במקום השימוש, שהוא על גבי התל."}, {"s": "p", "h": "ואמנם יש למצוא גדר זה בתל, אם נבאר גדר גבול שאמרנו באופ\"א, והיינו, שנאמר שהמושג גבולות אינו אטימות מוחלטת, (וכמו בחריץ בה צידי החריץ נתקלים בגבולות של קרקע) אלא גבולות שימוש, ומקום שהוא גבוה עשרה טפחים סביבותיו (בגובה) גבולים ע\"י חוסר היכולת להשתמש בסביבותיו ללא קרקע קרובה, אך לזה נצטרך להוסיף ששימוש מעל עשרה טפחים אינו נקרא שימוש (או לפחות אינו נקרא שימוש במקום בעל קרקע)."}, {"s": "h6", "h": "חריץ"}, {"s": "p", "h": "והנה חריץ, על אף שנראה שהיה אפשר להכליל את גבולותיו בדיני מחיצות (דקות), עדיין יש לחלק שכן מחיצות חוצצות את כל מקום השימוש בגובה עשרה טפחים, משא\"כ בחריץ בו הטפח הראשון חצוץ רק בטפח אחד של קרקע וכן הלאה, וזה צ\"ב, שלא יושווה דין מחיצות לזה, ויש לומר ששימוש בטפח הראשון אינו שימוש דרך קרקע, והיכולת לחבר בין שימוש הקרקע של החריץ לבין שימוש הקרקע של רשות הרבים עוברת דרך כל אותם עשרה טפחים, ואם אמנם שימוש בתוך עשרה טפחים נחשב כשימוש בקרקע בכל מקום, כאן שהעירוב הוא בין קרקע לקרקע אולי צריך עירוב שווה גובה."}, {"s": "h6", "h": "מחיצה"}, {"s": "p", "h": "והנה במקרה שהרשות גדורה ע\"י מחיצות (דקות) ובגדר מחיצה עצמה יש לנו לדון, במקרה הפשוט של רשות היחיד מצד אחד ורשות הרבים מצד שני ומחיצת עשרה טפחים ביניהם, מה הוא גדרה של המחיצה, שיש לומר מצד אחד, שהרי רשות הרבים תופס עד עשרה טפחים, וכך יש לתחום את העירוב רשויות שלה עם רשות היחיד שלצידה, וההמחיצה הרי מחלקת ביניהם. אבל מצד אחר, כיון שמחיצה תפקידה למנוע רגל רבים, הרי שהמחיצה צריכה להיות על פי גדרי הימנעות הרבים מלעבור, ונצטרך לומר שמחיצה עשרה טפחים היא שיעור גובה מספיק של יכולת עצירה של הרבים מלעבור."}, {"s": "h7", "h": "שני צדדים בהגדרת שטח המחיצה - חלוקת אוויר הרשויות לעומת מניעת רגל רבים"}, {"s": "p", "h": "ותראה כי שני צדדים אלו יגדירו את שטח המחיצה ופעולתו באופן שונה, שלצד הראשון שהמחיצה מתייחסת לשני הצדדים ומחלקת ביניהם, הרי שכל חלק בגובה המחיצה פועל חלוקה על חלק אחר באוויר הרשויות שכנגדו (ובכל אופן יש כאן הבדלה כוללת הבנויה מחלקים), ולביאור השני שהמחיצה מתייחסת למניעת רגל רבים, המשמעות של חלקי המחיצה אחידה למניעת רגל רבים ואין ערך לחלקיה, וגובה המחיצה משמש כמשך אחיד, (ולאח\"ז זכיתי שתאמר בדין סלע שיש באורכו עשרה טפחים וברחבו ארבעה ואין בגבהו עשרה לעניין כלאים (ירושלמי כלאים פ\"ב ה\"ו)). "}, {"s": "p", "h": "ולפי שני צדדים אלו יש לחלק את שייכות המושג מחיצה בחריץ ותל, שלצד הראשון גם אם נאמר שהגובה השונה של חריץ ותל מרשות הרבים מספיק בכדי להגדיר גבולות לחריץ ותל וכדלעיל, אך אין לנו לומר שיש כאן מחיצה במובנה הפשוט החוצץ בין רשות הרבים לרשות היחיד (אלא אם נאמר גוד וכו'). ולצד השני יש לבאר שאף בחריץ ותל שייך המושג מחיצה, באופן זה שהם יוצרים משך מסוים שמונע רגל רבים, ובזאת יופרדו דיניהם מטרסקל על גבי קנה וגזוזרטרא, ויתבאר באופן דומה דין תל המתלקט."}, {"s": "h7", "h": "הגדרה עצמית לדין מחיצה - צירוף שני הדינים בהפרדת רשויות ובמניעת רגל רבים"}, {"s": "p", "h": "ומיניה נפקא הגדרה עצמית לדין מחיצה וגובהה, שלצד הראשון, שהמחיצה מחלקת ואינה אלא הפרדת הרשויות והגדרתם, ממילא אין משמעות למחיצה עצמה, אך למחיצה המונעת רגל רבים הרי משמעות וחשיבות עצמית לה ככח מונע, והתוצאות היוצאות מזה הן תוצאות למשמעות עצמית, והבן. (והנה, יש מי שרצה לתת למחיצה הגדרה עצמית שלא בדרך זו, והדברים אינם מובנים, שלא מצאנו שום משמעות לגופה של המחיצה מלבד שהיא חוצצת, שהרי אין לה הגדרות בעובייה או בחומרה, ועשרה טפחים נלמד כגדר ברשות הנחצצת ולא במחיצה, ובוודאי לא ניתן למצוא משמעות בעצם קיומה במקום, והדברים תמוהים.) ובאמת נראה לומר שתרתי אית בה במחיצה, דין מחיצה המחלקת וגם מניעת רגל רבים, ועל כן יש להבחין בחסרונות הקיימות רק באחת מהגדרות אלו, והתיקון בזה יבוא רק על הגדרה זאת."}, {"s": "h7", "h": "גובה עשרה טפחים"}, {"s": "p", "h": "והנה בכל הנ\"ל יש למצוא שצריך גידור של עשרה טפחים. ובכמה מקומות מוגדר עשרה טפחים גם הוא כמקום הראוי לשימוש."}, {"s": "h6", "h": "מספר המחיצות"}, {"s": "h7", "h": "מחלוקת שלוש או ארבע מחיצות - מהות הגידור בשלושה או ארבעה צדדים מול פירצה"}, {"s": "p", "h": "והנה מצאנו שנחלקו בדין מחיצות רה\"י אי שלש מחיצות דאורייתא או ארבע (ואע\"פ שהדברים נאמרו לגבי מחיצות, ה\"ה לגבי חריץ וכו' ונתפוס מקרה מחיצות לקלות העניין), ובספק זה היה להניח שני נידונים נפרדים, הראשון הוא בעיקר המושג גידור אם יש לו שלושה צדדים או ארבעה צדדים (וביתר ביאור נאמר שלמשל שנרצה לגדור בין כרם לזרע הקרוב לו שפניהם נפגשים מצד אחד, אז נאמר שהגידור הנצרך הוא רק מצד אחד, וכך יתכן שגידור של מקום רשות היחיד הוא רק משלושה צדדים, והצד הנותר אינו צד לענין זה), ועוד יש להניח בספק זה שאף אם נאמר שלגידור רשות היחיד ישנם ארבעה צדדים, עדיין יש לדון ולומר שיש בכל הצדדים יחד גדר אחד של גידור, וע\"כ יספיק לנו לגדור חלקם שע\"י זה יוגדרו כל הצדדים מאיזה סיבה."}, {"s": "p", "h": "ותראה שעכ\"פ שני נידונים אלה הם אחד משני פנים, וששניהם מכוונים על מהות הגידור, ואמנם היה נראה שיש לומר באו\"א שהמח' מתייחסת רק לנושא הפרצה והעירוב הבלתי נרצה, ולכ\"ע הגידור נצרך או אינו נצרך מכל הצדדים, רק שחלקו כמה צדדים תעשה פרצה, ויהיה קלקול בגידור האמור (ואמנם שיש לפקפק בחלוקה האמורה בין גידור ופרצה, שפשטות הדברים שהן דבר אחד, היינו, שפרצה המקלקלת היא היא חסרון גידור, וגדרו אחד. אבל אחר העיון יש למצוא מקום שנחלק הגידור והפרצה להיות שני נושאים נפרדים, ויהיה הגידור מתייחס ליצירת דבר שאינו, ופרצה לחסרון בדבר קיים, ועוד יבואר בע\"ה)."}, {"s": "p", "h": "ועכ\"פ נאמר שישנם שלושה הבחנות בזה, האחד, מספר הצדדים. השני, מספר בעיות העירוב. והשלישי, מספר המחיצות הממשיות וצורתם הנצרכות לגדור את הצדדים הנצרכים."}, {"s": "h7", "h": "הגדרת ארבעה צדדי המקום - ארבעה צדדי השפעת עירוב המקלקלים את הגדרת המקום"}, {"s": "p", "h": "והנה עיקר עניין ארבעה צדדים נגדיר ע\"פ האמור, שהגישה אל מקום (הכולל את כל צדדיו ומהותו) מן החוץ הוא מחולק לארבעה צדדים, והיינו, שישנם ארבעה צדדים מהם ניתן להשפיע עירוב על מקום, והמקום מושפע ע\"י ארבעת צדדיו, וכל צד משפיע באופן כולל על כל הצדדים, ועל כל המקום בהגדרתו, והיינו, על אף שבעיית העירוב אחת היא, והיא חוסר הגדרת המקום לעצמו, אבל חיבור אותו מקום ושאפשר שיתערב, מחולק לארבעה חלקים שיוגדרו כל אחד לעצמו לדיניו הנוגעים לצד אחד (ותליא בזה גדר דין עומד מרובה בצד אחד, ודין פרוץ במילואו, ועוד) וישפיעו באופן כולל על כל הצדדים המשפיעים על מהותו של המקום הכולל והאחד. והיינו שאין חלקי העירוב המערבים את המקום הנרצה להגדרה מערבים אותו משום היותם מערבים בכח ומקלקלים בחיוב, אלא מהיות השטח בלתי מתגדר בהיות החלקים המערבים קיימים."}, {"s": "p", "h": "ומזה יש לשמוע שארבעה צדדים האמורים אינם גדר אלא במקום עצמו שמכיל ארבעה צדדי עירוב (וכמו שהקדמנו עירוב הוא דין המתייחס אל שני צדדי העירוב מבחינתו של צד אחד), ולא כמו שיש שרצו לדון, אם דין ארבעה צדדי עירוב נאמר במקום, שלכל מקום יש ארבעה צדדים, או שהמקום הוא אחד וארבעה צדדים מתייחסים לכוחות המערבים, וזה אינו ע\"פ האמור, שאין כאן שני דינים, דין המקום להיות מוגדר לעצמו, ודין המקום שלא יהיה מעורב ע\"י זולתו, אלא הכל דין אחד שיהיה המקום מוגדר לעצמו ולתשמישו וכל הנ\"ל משפיעים רק על חלק זה, והוא היות המקום נשאר מוגדר לעצמו, וא\"כ בהכרח שאינם משפיעים על החלק שהוא הדין עצמו (ועיין הערה לעיל)."}, {"s": "h7", "h": "חישוב צדדי רשות היחיד - הגדרת צדדי הרשות לפי גדרה הפנימי"}, {"s": "p", "h": "והנה בעניין צדדי המקום, יש לנו לדון איך נחשב את הצדדים האמיתיים של הרשות האמורה להתגדר בהם, שהרי כשיש ארבע מחיצות שלמות, אין לנו צורך להגדיר את מיקום הצדדים כלפי הצדדים האמיתים, שמכל מקום הרי הרשות גדורה לעצמה, אבל הרי כמו שכתבנו ישנם דינים המתייחסים לכל צד בנפרד, ובאם לא נגדיר את צדדי העירוב לפני שנתייחס לצורת המחיצות במקרה מסוים, לא נוכל לדעת האם מדובר בצד אחד, שהעומד מרובה בו ושאר המחיצות ישרות, או בשלושה צדדים, שאחד מהם פרוץ במילואו ושאר המחיצה הנותרת מתעקמת, ופתחא בקרן זווית לא אמרינן, וכן במקרה שלא כל צדדיה של הרשות שווים בגודלם, וכמו ברשות מלבנית ששני צדדיה קצרים מן השניים האחרים, וברשות משולשת וכו'. ובדיני ריבוע העיר לגבי תחומין, מצאנו שמחשבים לפי רוחות העולם, ולא מצאנו זאת לגבי מחיצות רשות היחיד, ואף בזאת נראה לומר כדלעיל שדין ארבעה צדדים נאמר רק ביחס לרשות עצמה, ולהגדרתה העצמית, וכיוון שכן הרי שיהיו גדרים המעמידים את הצדדים שאינם מתייחסים לצדדים אמיתיים וקבועים, אלא רק ליכולת להכליל את הרשות לעצמה ולהגדירה, וממין כללים אלו הם הסימטריה הפנימית של הרשות והיכולת להגדיר אותה כגדורה, ודוק."}, {"s": "h7", "h": "מחלוקת כמה צדדים נצרכים להיחצץ - הגדרת קצוות המחיצות בשתיים ובשלוש לסגירת חלקי העירוב הנצרכים"}, {"s": "p", "h": "והנה היות בעיית העירוב קיימת מכל צדדיו שהם ארבעה, וכמו שהקדמנו שישנה מחלוקת כמה צדדים מהווים בעיה וחסרון בהגדרת המקום לעצמו, א\"כ יש לנו לסגור את כל צדדיו הגורמים את היותו מוגדר. והנה ישנה מחלוקת נוספת כמה צדדים נצרכים להיות נחצצים ע\"מ להגדיר את המקום, והנה מחיצה אחת וודאי לא תגדור את המקום כיון שאין לה אפילו יכולת להגדיר ריבוע מקום או כל מקום סגור, שאף אם נאמר שיש לה יכולת להגדיר עוד שני צדדים ע\"י קצותיה אין זה הגדרה שאין להם סוף לצדדים אלו כיון שאין מגדירה את הצד הרביעי. והנה ארבעה מחיצות וודאי יגדירו את צדדי המקום כמוגדר, כיון שחוצצים את כל חלקי העירוב, ויש להסתפק בשנים ושלוש מחיצות, והיינו, ששני מחיצות יכולים להגדיר את המקום שבתוכם על ידי הם עצמם מצידם, ועל ידי קצותיהם שיגדירו את שני הצדדים הנותרים של המקום, (רק שיש לנו להבין שאף על פי שאנו אומרים שקצותיהם מגדירים את שאר הצדדים הם אינם חוצצים אותו), והנה באם ישנם שלש מחיצות יש שלשה צדדים ודאי מוגדרים ואף הצד הרביעי מוגדר מכח שני המחיצות הגודרות אותו בשני קצותיהם (וכדלעיל). "}, {"s": "h7", "h": "בירור גדר פילוש במחיצות הרשות - פריצה רצופה מעבר לעבר המבטלת יכולת שימוש המחיצות הקיימות"}, {"s": "p", "h": "והנה מלבד מה שכל אחד מחלקי העירוב, היינו, הצדדים מהווים בעיה בהיותם פורצים את השטח הנרצה ישנו מושג שנקרא פילוש, והיינו, שבאם שני צדדים פורצים לשטח הנרצה מכיוונים המתחברים בפריצתם (המוגדר ע\"י דרכי השימוש, הילוך וכו') מוגדר השטח כמפולש על ידם והנה יש לדון האם הוא משום היות כל צד פורץ עד הצד שממולו (ויש להגדירו יותר מאשר פירצה המהווה ריעותא בהגדרה אלא היא מבטלת את עצם היכולת של מקום זה להשתמש גם בשאר המחיצות הקיימות) או משום שיש שני צדדים פתוחים והרי השטח פרוץ משני כיוונים אזי לא יקרא מוגדר מצדדיו דיו."}, {"s": "h6", "h": "דין שתהיה ראויה לשימוש"}, {"s": "p", "h": "דין ארבעה על ארבעה הוא דין בכל מקום שיקרא רשות ע\"י שיהיה ראוי לשימוש. וכן הא דבעינן אויר עשרה טפחים גובה."}, {"s": "h6", "h": "דין שעולה עד הרקיע"}, {"s": "p", "h": "בנוגע לכל שלש הרשויות שהם מן התורה מצאנו שנפרדו דיניהם לגבי עד כמה גובה מקרקע המקום, יחשב האוויר כשייך לרשות הקיימת על הקרקע, וברשות היחיד נאמר שהאוויר עד הרקיע נחשב חלק מהרשות הקיימת על הקרקע."}, {"s": "h7", "h": "רשות היחיד עולה עד לרקיע - כח עשרה טפחים תחתונים להחיל דיני הרשות בגובהה"}, {"s": "p", "h": "ויש להבין שהרי גם ברשות היחיד ישנם דינים מסוימים המתייחסים רק לעשרה טפחים התחתונים שלו, כמו שצריך שיהא גדור רק בעשרה הטפחים התחתונים שלו, ואף לגבי אי אמרינן עומד מרובה בערב, העומד והפרוץ ממוקמים רק בעשרה הטפחים התחתונים, וכמו שביארנו לעיל אין לומר שזה חלק מהצורך לגדור את הרשות הנפרצת אליו שהיא עד עשרה טפחים, ועוד, שלגבי חלוקה בין שני רשויות היחיד, לא מצאנו שיצטרכו יותר מעשרה טפחים בגלל ששניהם עולים עד הרקיע, ובהכרח שאין זה דין שרשות היחיד היא אחידה לכל גובהה, אלא רק שהרשות העיקרית הנמצאת תוך עשרה טפחים בכוחה להחיל את דיניה לכל גובהה."}, {"s": "h7", "h": "גג בבית מקורה ברשות היחיד - חילוק תשמיש הגג מהבית ואיסור כיתוף כומתא וסודרא"}, {"s": "p", "h": "ומעתה יש לנו לדון בבית מקורה, שהיה לומר שהתשמיש הנמצא על גבי הבית (גג) אינו חלק מהרשות שתחתיו, ולא יחול עליו דין רשות היחיד עולה עד הרקיע (אלא אם כן יש בו דין גוד אסיק מחיצתא שאז המחיצות גודרות אותו בנפרד ובלי שייכות לבית שתחתיו), ואף שיש מי שסובר שאף בכהאי גוונא אמרינן רשות היחיד עולה עד הרקיע, הרי אף הוא מודה שאם נפרץ במילואו לכרמלית נאסר, ומאי שנא מכל חריץ שעולה עד הרקיע אף על פי שהוא פרוץ למעלה באווירו לרשות הרבים, ואע\"פ שהיה לתרץ שכאן האוויר אינו מיועד לשימוש אחיד עם שימושי הקרקע של רשות הרבים, שהיא קרקע והוא אוויר, וקרקעו גדור עשרה טפחים, היא הנותנת, שלא יהיה דין עולה עד הרקיע, אם תשמישו התחלק מסיבתו שהיא הקרקע, ע\"י קרקע אחרת, ועיין לה, שבכרמלית אנו אומרים שאף שאוויר כרמלית הוא עד עשרה טפחים, הרי אם נחלק האוויר ע\"י קרקע חדשה, תהיה הקרקע גובה חדש לחישוב דין כרמלית עד עשרה טפחים, שלא לומר שכך הוא בכל רשות הרבים שיש לה למעלה טז' אמה ושאר דיניה."}, {"s": "p", "h": "והנה, מצאנו עוד בדין גג שמשתמשי רשות הרבים המשתמשים בו בכומתא וסודרא, אוסרים אותו לבעליו, אע\"פ שרשות הרבים עד עשרה טפחים, וגג זה גבוה עשרה (ע\"ש), ורשות היחיד עולה עד הרקיע, ואיסור זה נפתר ע\"י העמדת סולם בין הבית (או החצר) לבין הגג, ולא נתברר גדר תיקונו לגבי השתמשות הרבים האוסרת בכומתא וסודרא."}, {"s": "h5", "h": "ההגדרה השימושית של רשות היחיד."}, {"s": "p", "h": "רשות היחיד מוגדרת כמיועדת לשימושים פרטיים ולמשתמשים פרטיים, ומצאנו שישנם כמה וכמה סוגים של שימושים שנחשבים שימושי רשות היחיד, והם מחולקים ע\"פ מקומות שהיו ידועים ולהם אופי שימושי מסוים, נאמר שלא מצאנו שחילוקים אלו ישפיעו על דין תורה להחשיבם כרשות היחיד."}, {"s": "h7", "h": "הגדרות שימושיות ברשות היחיד - אופי בית, חצר, מבוי, גג, קרפף, מוקצה, ודירה"}, {"s": "p", "h": "ואלו הם והגדרותיהם לשימושם:"}, {"s": "h7", "h": "בית"}, {"s": "p", "h": "בית. מקום מיוחד ליחידים המיועד לשימוש צנוע, דינים מיוחדים ניתנו לכלים ששבתו בתוכו, ואווירו נחשב כמלא."}, {"s": "h7", "h": "חצר"}, {"s": "p", "h": "חצר. מקום שאינו מיוחד רק לאדם אחד אלא לכמה אנשים בשותפות, (אפילו חצר ששייכת בפועל לאדם אחד עדיין אינה מוגדרת כבית המיועד ליחידים מעצם סוג השימוש בה אשר הוא הוא המאפשר שיתוף רבים בסוג רשות זו) ואינו מיועד לשימושים צנועים כבבית, וכשרבים שותפים בו צרכים לערב ביניהם."}, {"s": "h7", "h": "מבוי"}, {"s": "p", "h": "מבוי. גם הוא אינו מיוחד כחצר ומיועד עוד פחות ממנו לשימושים צנועים, ולכן מאפשר שימוש של אנשים רבים יותר יחד, דין במבוי שניתן לגדור מחיצתו ע\"י לחי או קורה מה שלא הותר בחצר (הנצרכת לפס ארבעה). וצריכים להשתתף כל בני המבוי להתירו."}, {"s": "h7", "h": "גג"}, {"s": "p", "h": "גג. מקום מיוחד ליחיד ואין שימושו תדיר כבחצר ואינו מיועד לשימושים צנועים, דינו כחצר לגדור מחיצתו ע\"י פס ארבעה."}, {"s": "h7", "h": "קרפף"}, {"s": "p", "h": "קרפף. אין שימושו תדיר ואינו מיועד לדירה כבית וחצר, כי אם לאוצר וזריעה וכדומה, אם היה גדול מבית סאתיים עשאוהו חכמים ז\"ל כדין כרמלית, שאסור לטלטל בו."}, {"s": "h7", "h": "מוקצה"}, {"s": "p", "h": "מוקצה. רחבה שאחרי הבתים שאין שימושה תדיר כבחצר אלא לאוצר וכדומה ודינה כקרפף, ואם היתה גדולה מבית סאתיים עשאוה ככרמלית שאסור לטלטל בה. "}, {"s": "h7", "h": "דירה שתשמישה לאוויר"}, {"s": "p", "h": "דירה שתשמישה לאוויר. אם היתה גדולה מבית סאתיים עשאוה חכמים ז\"ל ככרמלית ואסור לטלטל בה."}, {"s": "h4", "h": "ההפרדה וההגדרה (מחיצה ופרצה) הנובעים מהמבנה הממשי של הרשות."}, {"s": "p", "h": "ע\"מ להבין את פעולת המחיצות כיוצרות את ההגדרה העצמית של הרשות, נצרכים אנו להבין את החלקים הקשורים בפעולת המחיצה. "}, {"s": "h6", "h": "גדרי מחיצה"}, {"s": "p", "h": "בכל מקום בו פועלת מחיצה קיימים שלושה מרכיבים:"}, {"s": "p", "h": "א. מחיצה, היינו, המבנה הממשי בהגדרתו כדבר בעל יכולת לחצוץ."}, {"s": "p", "h": "ב. הדבר שהמחיצה חוצצת בפניו."}, {"s": "p", "h": "ג. הדבר שהמחיצה אמורה לחצוץ עליו."}, {"s": "p", "h": "סדר השתלשלות משמעות מקום – מקום, קרקע, שטח, אוויר ומחיצת מקום "}, {"s": "p", "h": "ובהקדם לזה, סדר משמעות דמקום (ויתבאר בע\"ה). א. מקום סתם בגדרו הכולל אוויר וקרקע באחת. ב. קרקע בגדר שם מקום קבוע, ובזה יהיו שיעורי אורך ורוחב הנפרדים. ג. שטח בגדר קרקע האמור וביחס לחשיבות הינוח, ויש בזה משמעות דאורך ורוחב כגדר עצמי ולא כשיעור, ושיעורי שטח כמו בית סאתיים. ד. אוויר המשוייך לקרקע ובגדר הקרקע, ובזה יהיה דין גובה עשרה. ולסיים הקרקע כשלעצמה לא בעינן מחיצות, ויהיה די בסיום כל דהו או בהבדל שע\"י סיבות שאינן גידור כמו ברה\"ר או בדרכים אחרות הנוגעים לשטח. ועל השטח הנ\"ל יהיו גדרי מקום חשוב דד\"ט על ד\"ט, והוא גדר ברוחב המושת על השטח, שכשנרצה שיהיה שטח (שהוא בגדר נפרד מאורך ורוחב) בעל רוחב כזה, נצטרך שיהיה כך בכל כיון. גדר מחיצה אין הוא גדר בשטח לבד, אלא הוא סיום שטח הקרקע לגובהה, וכדאמרן אין זה דין חלל דאית ביה שלושה עוביים וששה צדדים ושיעורו שווה בשלושת אורכיו לגבי גדר רוחב המושת על חלל, ואאם היתה מחיצת עשרה ביחס חלל הרי שהיה שיעורה בעשרה מעוקב. וגדר גבוה אוויר דקרקע גדר של קרקע וביחס להשפעתה על אוויר שלידה, ועכ\"פ ביחס לאוויר שמעליה."}, {"s": "h7", "h": "שלושת חלקי המחיצה בעירוב - השפעה הדדית בדרבנן מול השפעה חד-צדדית בדאורייתא"}, {"s": "p", "h": "והנה שלושה חלקים אלו קיימים בנפרד כלפי כל פעולה הנובעת מעירוב, והם שני חלקים בסה\"כ לשני צידי העירוב, ושני חלקים לכל צד בעירוב, שתים שהן ארבע, והיינו, ההשפעה על הצד שני בעירוב וההשפעה ממנה. ואע\"פ שברשויות דאורייתא הנראה הוא שיש השפעה חד צדדית של רשות הרבים על רשות היחיד, ואין כל השפעה של היחיד על הרבים, ברשויות דרבנן קיימת אפשרות זו (אפשרות זו קיימת מחמת שונות הגדרים בין הדין דאורייתא המתייחס לרבים במובן של ריבוי כמותי שתוספת של יחיד אינה סתירה לריבוי, אך מאידך ההתייחסות ליחיד היא של מיעוט שהרבים הם סתירה לו. משא\"כ ברשויות דרבנן שבהם השוני בין הרשויות השונות הוא שינויים איכותיים ולא כמותיים, שאז נמצא שעירוב יחיד (או שאר הגדרות) איכותי לעצמו יסתור הגדרה של יחיד אחר), והיינו, בשתי חצרות שלכל חצר יש את שני האפשרויות להשפיע על החצר השניה ולהיות מושפעת ממנה. "}, {"s": "p", "h": "ואע\"פ שהמושג מחיצה הוא דבר אחד, ובעצם הגדרת מבנה כלשהו כמחיצה הרי הוגדרו גם בעיית העירוב טרום המחיצה, ופתירתה ע\"י המחיצה כדבר מפריד, יש לחשב את חלקי פעולת המחיצה טרם איחודו על מנת לברר את קיומם של חלקים אלו במקרים שונים."}, {"s": "p", "h": "והן אמת שאע\"פ שהיה נראה שבהתקיים תנאי מחיצה כאילו פרחו היכולת להשפיע ולהתערב, ישנה גם פעולה חיובית למחיצה זאת ביחס למהות המשפיעה, והיא הקיום האחיד למהות בתוך המחיצות אשר שייך בעיקר בהגדרת רשות היחיד, וכמדומה שגם ברשות הרבים להגדרתה שייך דבר זה."}, {"s": "h7", "h": "הגדרת המקום הנחצץ לפי צרכיו - מחיצה המפרידה צד אחד בלבד עקב מהותו"}, {"s": "p", "h": "והנה למרות שכל הנחצצים משני צידי המחיצה שווים כלפיו בהפרדתם, רק מקומות כאלה שיש להם צורך בחציצה (או צורך לאי חציצה) מוגדרים ע\"י המחיצה כנחצצים, ואלה אשר אין פעולת העירוב משפיעה עליהם ועל הגדרתם העצמית גם המחיצה לא תתייחס אליהם רק כחוצצת מפניהם, וכדלעיל."}, {"s": "p", "h": "ועל כן תיתכן מחיצה המפרידה רק צד אחד מצידיה עקב מהותו של צד זה, ועקב צורת קיום המחיצה כלפיו (והם, היינו, הך). וצד השני יוגדר עדיין כמעורב."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"886\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">28\u003c/sup>\u003cspan class=\"ca\" data-c=\"886\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ולאחד כל הגדרות אלה נאמר כי המושג עירוב למרות שהוא נגרם ע\"י שני חלקים שנתערבו הרי כל חלק מוגדר (ובמילה מוגדר הכוונה ע\"ש העבר או העתיד שיקום עם קום המחיצה. ויש מקומות בהם יש אפיון אחר במקום, המגדירו בנפרד מהמעורב לו גם ללא מחיצה, אך לא יקרא מופרד לעניין רשות אלא במחיצה.) מעורב לעצמו ובעיית העירוב היא בעייתו עצמו, ועל כן גם המחיצה לא תועיל אלא אם כן תקום ע\"פ צרכיו.\u003c/span>"}, {"s": "h7", "h": "הגדרת המחיצה הממשית והמקום הנחצץ - דיני עומד מרובה ופתח כדינים במקום הנחצץ ולא במחיצה"}, {"s": "p", "h": "ונרחיב בבביאור כי התנאים באחד משלושת מושגים אלו הם תנאים בעצם על כל כולם, והתנאי האמיתי שהוא יכולת ההגדרה עצמית לנצרך לו."}, {"s": "p", "h": "בהגדרה של מחיצה (במובנה הממשי) לא תהיה הגדרה בפני מה היא חוצצת ועל מה, כיון שאין היא הגדרה עצמית אלא היחס כלפי כל צד והגדרתו העצמית ובצרכיו הוא נותן את ההגדרה הנרצית בפני מי היא חוצצת ועל מי, ועל כן כל הדינים שמובילים למיעוט באטימות המחיצה (עומד מרובה, ופתח וכדומה) הינם דינים במקום הנחצץ (ובהגדרתו העצמית) ולא במחיצה שעליה לא יחולו דינים ונאמר בה שהיא קיימת בשלימות או שאינה כלל (ע\"ע לעיל שמצאנו שתהיה במחיצה משמעות של הרחקה ואינו עניין לכאן בו אנו דנים על מחיצה במשמעותה העצמית)."}, {"s": "p", "h": "הדבר הנצרך מחיצה הוא מהיות שבאי החציצה נוצרת בו עירוב בלתי רצוי לו. ועירוב זה יהיה ע\"י פרצה למקום שונה מהמקום הצריך חציצה שעי\"ז תוסר הגדרתו."}, {"s": "h7", "h": "תנאי המחיצה בהתאם למציאות הרשות - חציצה מושלמת מול רשות מערבת שאינה צריכה הגדרה עצמית"}, {"s": "p", "h": "ויהיו תנאי המחיצה הן בהתאם לעירוב הקיים וההפרדה הרצויה, ובאיחוד ההגדרות נאמר שהיא בהתאם למציאות הרשות וקיומה (ואכן בכמה מקומות נראה שדין התורה ותקנת החכמים היא דווקא בהגדרת מציאות הרשות והיא הבסיס לשאר הדינים)."}, {"s": "p", "h": "העירוב כאמור מתייחס לשני הצדדים המעורבים וביחס לכל צד בנפרד שיחשב כמעורב עם הצד השני, אם כי לא ישפיע על שניהם באופן שווה או בכלל, וכשמחיצה עושה הפרדה היא מגדירה שני דברים כמוגדרים, אך כאמור הפרדה אינה מתייחסת לשני הצדדים המופרדים באופן שווה בעקבות הצרכים השונים של כל צד בהפרדה. הגדרת מקום מתייחסת רק לצד אחד כמופרד."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"111\" style=\"--a:#dc2626;--abg:rgba(220,38,38,0.1)\">29\u003c/sup>\u003cspan class=\"ca\" data-c=\"111\" style=\"--a:#dc2626;--abg:rgba(220,38,38,0.1)\">ישנם סוגים שונים של עירוב המשפיעים על המקום הנצרך להגדרה וכל מקום שנצרך להגדרה היא שהוא ניתן לעירוב, שכמו שכתבנו העירוב וההפרדה הינם שני אפשרויות קוטביות במקום.\u003c/span>"}, {"s": "p", "h": "והנה המחיצה אמורה לחצוץ באופן מושלם את כל הדבר הנרצה לחציצה ששם חציצה אחד הוא. וההגדרה של הרשות המוגדרת והרשות המערבת (כשמתייחסים לצד אחד, המוגדר) היא הגדרה שונה ביסודה, בהיות הרשות המערבת בלתי נצרכת להגדרה כל שהיא על מנת ליצור עירוב, אלא כוחה הוא בזה שאינה מוגדרת ודבר לא נתבאר דיו."}, {"s": "h7", "h": "שלושת תנאי הגידור במקום מסויים - מהות שימוש היחיד, החלק הנצרך להגדרה, והגורם המערב שמסביבו"}, {"s": "p", "h": "והנה כאמור ע\"מ לגדור מקום מסוים נצרכים אנו להגדיר את מהות המקום, ואת החלק בו הנצרך להגדרה, ומסיבת איזה גורם מערב הוא נצרך להתגדר."}, {"s": "p", "h": "והיינו מהות המושג שימוש היחיד והיחס הנ\"ל למקום שאנו באים להגדירו כך, ואת החלק במקום זה הנצרך להגדרה, והגורם המערב והוא היות השטחים שמסביב לשטח הנ\"ל אינם רשות היחיד (והיינו, כיון שבמקום אותו אנו רוצים להגדיר ישנם חלקים רבים במרחב המקום, אין דעתנו לגדור כל חלק במקום בנפרד אלא לשים גדר שתגדיר את כל המקום באחת, שאין בעיית עירוב המקום נמצאת רק בפניו החשופים למקום המערב, אלא בעיית העירוב קיימת בכל מרחבו של המקום, ויש לנו לדון האם המחיצה (או כל גבול) הגדירה את כל המקום הקיים ברשות או רק את צדדיו שהם הבעיה ובהיות צדדי המקום בלתי מערבים את הבעיה הרי ממילא הופך הוא שאר המקום לבלתי מעורב). "}, {"s": "h7", "h": "מהות הכח הסותר לרשות היחיד - תנאי מקום גדור ליחיד מול מקום פרוץ למעבר הרבים"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"887\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">30\u003c/sup>\u003cspan class=\"ca\" data-c=\"887\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ונצרכים אנו להגדיר את המשמעות של מקום שאין הוא רשות היחיד בגלל מחיצותיו, ולהבין את הכח שעומד ממול ההגדרה של רשות להיות רשות היחיד. והנה ברור שהמושג רשות היחיד הוא מושג בעל הגדרה עצמית ללא שייכות למה שהיה ההגדרה של השטח המדובר לפני עשייתו לרשות היחיד. ומן התורה ישנם שלושה רשויות והם רשות הרבים, רשות היחיד ומקום פטור. ורשות היחיד יש לו תנאים שמשמעותם העיקרית היא, היות המקום גדור לעצמו ומיוחד לשימוש לנמצאים בתוכו. ורשות הרבים תנאיה בעלי משמעות עיקרית של מקום פרוץ המיועד לשימוש מעבר הרבים. ורשות מקום פטור עיקר הגדרתו הוא מקום שאין לו הגדרה מן ההגדרות האמורות לעיל, שאין הוא בעל תנאים להיות בו שימוש הרבים או היחיד.\u003c/span>"}, {"s": "p", "h": "והנה ישנם הגדרות שהם הגדרות בצורת השטח מבחינה גשמית, והגדרות שהם נובעות מהשימוש הנוכחי בשטח. ונראה שהכח שגורם לשטח להיות לא רשות היחיד הם תנאים שגורמים שהשטח לא יהיה ראוי להיות שימוש ליחיד. ומעתה נאמר שההגדרה של המחיצות של רשות היחיד הם גורמי היותו מקום מוגדר ליחיד."}, {"s": "p", "h": "שני דינים במחיצת רשות - מחיצה להגדרת קרקע להנחה ובכל המחיצות יחד להגדרת שימוש "}, {"s": "p", "h": "ולפמשנ\"ת לעיל יובחן שני דינים נפרדים במחיצת מקום, דין במחיצה כהגדרת קרקע להנחת חפץ (ובזה יש דין מניעת רגל רבים וכו'), וסוג המחיצה וכו', ומלבד זה יש דין במחיצות יחד, כהגדרת מקום שימוש אדם (ובזה יש דין שיהיו מחיצות ניכרות). וכמו שיתבאר בעז\"ה אין זה דין במחיצות עצמם, אלא במה שהם גבולות המקום. וזה יובדל מאוד ביחס לתל, והיינו, שודאי מחיצות דתל כהגדרת קרקע הם בצידי התל וכל התל עצמו, ובזה אין חסרון שלא נראה. אך גדר מחיצות המקום, היינו, גבולותיו, אין זה גוף התל אלא עצם הבדל הגובה, והיינו, שביחס לקרקע במובנה כמקום הנחת חפץ, דין גובה עשרה דמחיצות הוא לא דין בגובה אלא בתפיסת קרקע את אווירה, ובזה אין משמעות אם זה למעלה או למטה ממנה, וגדר מחיצות הוא גדר חיובי, היינו, שנצטרך להגדיר קרקע ע\"י שנגדיר את אווירה, ובזה גדר המחיצה מניעת רגל רבים. אך ביחס להגדרת הקרקע כמקום שימוש אחד, אין המחיצות רק גבולות, ואין למחיצה עצמה משמעות, ובתל יהיה זה הפרש הגובה, (ובזה יהיה שייך גדר דינא דהר\"ן (גבי שיעור גודל מקום דיהני ליה מחיצות) במחיצות ניכרות, היינו, שצריך שיראה את הפרש הגובה)."}, {"s": "p", "h": "ובזה יהיה ההבדל בין מחיצת רה\"י ומחיצת רה\"ר שמחיצת רה\"ר אין לה משמעות רק בהיותה גבול. ובזה יהיה גם ההבדל בין שבת וסוכה לגבי מחיצות ניכרות שיש בדין מחיצת סוכה מה שאין בשבת, דודאי ביחס למחיצה כהגדרת קרקע עצמה שתהיה נפרדת, ובלי שם מקום, שוו דיניהם. אלא שביחס למחיצה כהגדרת מקום הרי יש למקום שלה דיני תקרה, וא\"כ יהיה דין שתהיה גם גבול ביחס לתקרה, וע\"כ צריך שתהיה ניכרת ביחס לסכך, וזה משמעות גוד אסיק. וזה יש לומר גם בגבולות רשות שבת ביחס לתל. וזה הבדל הנמצא בין גדר פירצה לגדר בקיעת גדיים, דפירצה היא דין במחיצה כהגדרה למקום וכגבולותיו, וע\"כ שייך שיהיה בזה דין רוב שזה ביחס למקום שהוא אחד, אך בקיעת גדיים הוא דין במחיצה כהגדרה לקרקע ע\"י אווירה, שזה דין חיובי במחיצה ועל זה לא יועיל רוב. "}, {"s": "p", "h": "ובזה יבואר גדר היקף לדירה, והיינו, שמדין התורה אין גוף המחיצה למקום, אלא כיון שגזרו חכ' שיהיה מחיצה למקום, היינו, שאף שיהיה מקום מוגדר בגבולותיו, והיינו, שאין בדין מחיצות רק להגדיר קרקע ע\"י אווירה, ואין משמעות במחיצות עצמם לגבי המקום מלבד היותם גבולותיו, כיון שתקנו דינים במקום עצמו, היינו, ביחס לשימוש, והיינו, שיהיה משמעות שימוש גם בהגדרת רה\"י, וזה גזרת מבוי ששימושו נראה כרה\"ר, וזה משמעות יותר מבית סאתים, שאין המחיצות מגדירות את המקום שאין בהם תוך. וזה משמעות כרמלית שלא תובדל מרה\"ר אלא בשימוש."}, {"s": "p", "h": "צורת הרשות קודמת לקיום הרשות - המחיצות יחד מגדירות צורת המקום קודם קיום הרשות "}, {"s": "p", "h": "והנה כאמור דין שיהיה המקום נפרד הוא דין תמידי, ויש לדון בזה מסוגיא דאתי רבים, והיינו, שעכ\"פ באותו הזמן דלא אתי עכ\"פ יחשב המקום כנפרד, ויש להכריח מזה שהוא דין במחיצות, אלא שיש לבאר למה לא יחשבו המחיצות עכ\"פ בזמן דלא אתי, וכן יש לבאר דאם זה דין במחיצות למה יהיה זה תלוי בשם ד' מחיצות, או בגדר שתי מחיצות מעלייתא, הרי משמעות המחיצות יחד הוא משמעות ברשות, ולא במחיצות כמונעות רגל רבים. ונראה מכאן לכאורה דמלבד מה דאית ביה במחיצות המשמעות הפשוטה דמניעת רגל רבים, יש בהם משמעות במחיצות כולן יחד ובלי שייכות לרשות."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"888\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">32\u003c/sup>\u003csup class=\"cb\" data-c=\"112\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">31\u003c/sup>\u003cspan class=\"ca\" data-c=\"112 888\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ואחר העיון הוא מוכרח דהא צורת הרשות, ודאי קודמת לרשות, דאף אם ג' מחיצות דאוריתא, מי יגביל הרשות ברוח רביעית שלא נאמר דהיא ממשיכה עוד וליכא למחיצות, וביותר לר\"י דב' מחיצות דאורייתא. אלא בהכרח דיש גדר במחיצות יחד במשמעות צורת המקום, וגדר זה קודם לקיום הרשות, וגדר זה גם אינו שייך למשמעות הרשות, דהוא באותו משמעות ביחס לצורת רה\"ר (לגבי גבול טז' אמה ומפולש משער לשער ועוד), וביחס לצורת רה\"י האמורה.\u003c/span>"}, {"s": "p", "h": "גדר גובה עשרה טפחים – תפיסת גובה של פני השטח ולא גדר בחלל "}, {"s": "p", "h": "וכן משמע מהא דגדר עשרה טפחים הוא גדר התפשטות פני השטח לגובה האוויר, וכמו מה דרה\"י עולה עד לרקיע, ורה\"ר תופסת עד עשרה, והיינו, דמשמע דמקום עצמו הינו השטח, והגובה הוא ביחס לפני השטח, וגדר אורך ורוחב שטח, הרי אינם במושגי שטח, שהרי אין בכוח אורך רק לאורך, ואיך נאמר בו גדר ביחס לגובה. אלא שמקום היינו, השטח, כיון שיש לו פנים, היינו, פני שטחו, הרי שיש לו שייכות לאוויר שפניו פונים אליו, וזה לא נובע ממושגי אורך ורוחב דשטח, אלא ממציאות המתחדשת בשטח יותר מאורך ורוחב, וזה ביחס לכלל השטח. והיינו, כמו שיעור ד\"ט דמקום דאף שהוא ביסודו ממושגי רוחב ד', אחר שיש לנו שטח חשוב ביחס למושג רוחב זה, הרי שהשטח עצמו הוא כבר בגדרי שטח, ולא מחולק לאורכו ורוחבו. וע\"כ יהיה בו גדר פני שטח, שמופנה לאוויר שמולו."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"113\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">33\u003c/sup>\u003cspan class=\"ca\" data-c=\"113\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וביתר ביאור משמעות מש\"כ דגובה עשרה אינו דין בחלל המקום, אלא בגובה מקום, כי אם אכן היה גדרו חלל, היה שיעורו מרובע ומעוקב ובעל ו' צדדים, משא\"כ אם הוא דין במרחק או תפיסת גובה של שטח. וא\"כ הרי שגם שיעור המועט או המרובה דגובה מקום אינו ביחס לחלל, ואם נמצא גדר חלל לגביו, ביאורו שע\"י הגדרת גובה ביחס למקום ממילא יש לנו אפשרות להגדיר חלל, ואין גדר החלל גדר במקום בעצמו אלא מסדר שני.\u003c/span>"}, {"s": "p", "h": "חילוק גדר מחיצות דאורייתא ודרבנן – מחיצות דאורייתא להגדרת קרקע לעומת ודרבנן להיקף חלל "}, {"s": "p", "h": "והנה מזה תמצא הכרח דאין דין מחיצות הנוגע להגדרת קרקע רשות גדר בעצם הגדרת הרשות, שאם כן לא היה מועיל בו הלכות דלבוד ורוב וכו', אלא רק במה שהוא מגדיר את קרקע המקום, היינו, דכיון שמשמעות רשות היא החלל, הרי שאם נרצה להגדיר מקום ביחס לרשות נצטרך להגדיר את אוויר הקרקע, שנגדיר את הקרקע לעניין רשות. וא\"כ אין גדר המחיצות ביחס למקום כהגדרת המחיצות עצמם, כי המחיצות מגדירות את האוויר עצמו, ואין בזה צורך ביחס לקרקע, כי עצם שייכות האוויר ביחס לו כבר מוגדרת שהיא תופסת את אווירה לבד ולא אוויר דקרקע אחרת, וכן אין לקרקע אחרת להיות תופסת את אווירה, אלא גדר מחיצות הוא בהיפך שאחר שיש לו להגדיר את האוויר, הרי שיש לו גם להגדיר אותה עצמה, במה שהיא ואווירה שווים, היינו, גדר מקום לגבי רשות (מקום המוכן לשימוש)."}, {"s": "p", "h": "ולפי זה נראה דאף גדר מקום בעל ד' צדדים הוא בצורתו, היינו, ריבוע, וזה הוא מאחר שהוא סיום והגבלה, דכיון דאין הגבלה אלא ביושר, היינו, ביחס לכח התפשטות אחד, ויושר מקום הוא באורכו ורוחבו, וגדר מקום היותר מועט הוא באורך אחד, ורוחב אחד, הרי שסיום מקום הפחות בצדדיו הוא בריבוע. ואף שיתכן לחלקו ביותר מזה אין זה משום גדרו, והיינו, שכיון שמקום מסוים ביחס לשאר מקומות משמעותו בשטחו, שהרי אין שייכות בין מקום אחד לשני אלא בזה. דביחס לגובה אין זה משמעות מקום דווקא. א\"כ זה גדר המושג מקום שבין שאר מקומות, ולגבי גדר זה הרי דאין אלא שני גדרים שהם אורך ורוחב חיוביים, ואף דביחס למקומות שבחוץ מצאנו דבאים מד' צדדים, צ\"ל דאין זה מגדר מקום הבסיסי, היינו, שטחו, אלא זה במובן גובהו שיש לו משמעות פירצה וחיבור מצד לצד."}, {"s": "h6", "h": "דיני מחיצה"}, {"s": "h7", "h": "אין מחיצה אלא לד' טפחים"}, {"s": "p", "h": "אין חשיבות למחיצה למקום להיקרא מחיצה, אלא א\"כ היא עשויה למקום שיש בו ד' טפחים. דין זה מתייחס למקרים בו תהיה למחיצה השפעה נוספת מלבד המקום המסוים הנ\"ל."}, {"s": "h7", "h": "לבוד"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"889\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">34\u003c/sup>\u003cspan class=\"ca\" data-c=\"889\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">לבוד – הל\"מ. והוא דין על רווח הגדול שלא יחשב כרווח. ויש בו שני בחינות, האחד, במקום בו יש צורך של חיבור בין שני דברים, ובהיות ריחוקם תוך שיעור לבוד יחשב כישנו חיבור הנצרך. ב, במקום בו נדרש קיום כלשהו יעשה הלבוד את המקום החסר כאילו לא קיים. \u003c/span>"}, {"s": "p", "h": "ומאחר שדין לבוד מתייחס למקום (רווח, שטח) כבלתי ראוי להתייחסות נפרדת מסביבותיו, הרי שלא יתקיים רק בדברים שהם עצמם בחינה של דבר אחר, דוגמת מחיצות שהם בחינה (של גידור) למקום אותם הם חוצצות (היינו, שאין המחיצות רק צורך להגדרת המקום הנידון כגדור או לא), שבאופן זה דין לבוד יאחד את הרווח שבין המחיצות עם המחיצות עצמם לצורך הגדרת המקום אותם הם חוצצת כחצוץ. "}, {"s": "p", "h": "וביאור הדבר שאין אומרים לבוד אלא בדבר שהוא התייחסות לאחר, כי אין לנו להתייחס לחלקים נפרדים כמחוברים אלא אם כן ישנה סיבת איחוד קודמת לאיחודם, וכמו במקרה לעיל שישנו מקום אחיד ומחיצות נפרדות, ולשם אחידות המקום לעניין גידורו אנו מתייחסים גם למחיצות ולרווח שסביבותיו כאחד. וכך הוא גם בדיני קורה "}, {"s": "p", "h": "ובזה יש להבחין בין שני עניינים, גדר המקום והרווח עצמם, וגדר שני החלקים שביניהם יש את הרווח, ובוודאי שיקל עלינו לומר רק ששני החלקים בשני הצדדים נחשבים כהמשך אחד, מאשר לומר שעל מקום הרווח חל דין שני החלקים. "}, {"s": "p", "h": "ויש לחקור במקום בו דרוש קירבה בין שני חלקים שונים כמו מבוי וקורה, איזה שם יינתן לרווח. ויש לחלק בזה בין אופן שהרווח הוא רק במרחק, ואין היותו חסרון ביחס למקום בו הוא פועל, וכמו במקרה בו הקורה גבוהה פחות מג' מהמבוי, שבזה לא ישתנה הדין באם נגדיר שהקורה קרבה אל המבוי או המבוי קרב אל הקורה, לבאם הרווח נתון על מקום בה נצרכת פעולתם כבמקרה שהקורה קצרה ואינה מגיעה לכותל המבוי מלבד הבעיה שיש שהיא רחוקה מן המבוי גם חסרה פעולתה על המקום שתחת הרווח שאף אם נאמר שהמקום אינו נחשב למקום עקב קטנותו אבל גם לא יחול עליו דין הקורה."}, {"s": "p", "h": "הצורך בדין לבוד נובע מהצורך להגדיר שיעור גודל ריחוק שלא יחשב כריחוק שהרי אין כל דבר דבוק לחבירו לחלוטין שלא יהיה בו שום רווח לכן יש צורך להגדיר ממתי נעשה הרווח בעיה לחיבור ולבעיות רווח באופן כללי וכדלעיל."}, {"s": "h7", "h": "גוד אסיק"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"114\" style=\"--a:#dc2626;--abg:rgba(220,38,38,0.1)\">35\u003c/sup>\u003cspan class=\"ca\" data-c=\"114\" style=\"--a:#dc2626;--abg:rgba(220,38,38,0.1)\">גוד אסיק – הל\"מ והוא דין המתייחס להמשכת מחיצה כלפי מעלה, ומשמעות המילים גוד אסיק הוא, שאני מושך ומעלה את המחיצה לכיוון למעלה. ובו נאמרו שני דינים שונים, דין הגורם שגם האזור שממעל למחיצה יקרא שהוא בעל מחיצה, ודין נוסף הגורם שיחשב שהמחיצה הנוכחים נחשבת שהיא מגיעה ומתקרבת עד למעלה. ולכאורה שני דינים אלו אינם נובעים מאותה המשמעות, ולהבין את הקשר בין שתי משמעויות אלו, ובפרט את הדין הראשון שגם מה שלמעלה מן המחיצה יקרא בעל מחיצה מה שלא שמענו בשאר צדדים נאמר, שהוא בגלל שמחיצת עשר כוחה מלכתחילה להיות חוצצת כלפי צד אחד לגמרי, לכן גם (לגבי הדין השני) ביחס הקשר מחיצה לדבר נוסף, הרי שמחיצה סוגרת את כל הצד, וממילא דין המחיצה קיים לכל הצד ומתקרב על הדבר הנצרך קירוב מחיצה\u003c/span>"}, {"s": "h7", "h": "גוד אחית"}, {"s": "p", "h": "גוד אחית – הל\"מ והוא דין המתייחס להמשכת מחיצה כלפי מטה, וגם דין זה כמו קודמו מתייחס ליכולת של מחיצה בצד אחד להשפיע על כל הצד."}, {"s": "h7", "h": "פי תקרה"}, {"s": "p", "h": "דין המתייחס לגידור המקום שתחת התקרה ע\"י ההבחנה של סיום המקום בסיום התקרה, ודין זה בשונה מדין גוד אחית הוא דין הנובע מכוח הגדרת התקרה על המקום שמתחתיה, ושבכוחה זה קצות התקרה נעשות למעין מחיצות מגדירות לכלל המקום. ועל כן אין בקיעת גדיים הפורצת מחיצות מקלקלת דין זה, שהוא חל מכח ובכלל המקום."}, {"s": "h7", "h": "לחי"}, {"s": "p", "h": "סתימה משהו ברוח אחת המגדירה את כל הרוח כסתומה, ודין זה אם נאמר שהוא בגדרי מחיצה, כוחו מכלל גידור הרשות והוא כנספח למחיצות האחרות ברשות, והוא כאילו נאמר שבהיות המחיצות ממשיכות משהו על הרוח הפתוחה, הרי הם חלים גם עליה."}, {"s": "h7", "h": "קורה"}, {"s": "p", "h": "המונחת מעל רוח פרוצה, ומגדירה את הרוח כסתומה, וגם דין זה כקודמו כוחו נובע מכלל צורת הגידור שבשאר רוחות הרשות."}, {"s": "p", "h": "(לחי וקורה הם דינים החלים בהתווספם לשאר מחיצות קיימות, ויש ולבארם בשני פנים, או שצורה כזו של רשות נחשבת כבעלת מחיצות מכל הכיוונים, או שאמנם הרשות אינה חצוצה מכיוון הלו\"ק אך המראה שלהם מורה על ההפרדה שיש בין הרשות לחוצה לה.) "}, {"s": "h7", "h": "פתח"}, {"s": "p", "h": "הגדרה למקום שהוא פרוץ ממחיצות המשמש לכניסה ויציאה, ואין עליו שם פירצה כיון שהוא משמש לשימוש (כניסה ויציאה) שאינו סותר (הגדרת מקום עם) מחיצה, כמו כן כיוון שפתח הוא אחד ממרכיבי הצד של כל מקום גדור, הרי לצורה מובהקת שלו יש שם גידור (עיין צורת הפתח). הגדרת המושג פתח תיתכן כהגדרה לרוח אחת, והיא תהיה חלק ממחיצת אותו הצד, או כהגדרה לכלל הרוחות, והיא תהיה חלק מכלל מחיצות הרוחות."}, {"s": "h7", "h": "פתחא רבה"}, {"s": "p", "h": "הגדרה המתייחסת לפתח העיקרי של הרשות מחמת גודלו וחשיבות מיקומו ביחס לרשות."}, {"s": "h7", "h": "צורת הפתח"}, {"s": "p", "h": "הנחת צורה הנראית כפתח ברוח בה אין מחיצה מגדירה את המקום לא כפרוץ אלא כפתוח."}, {"s": "h7", "h": "דופן"}, {"s": "p", "h": "דופן הוא שם למחיצת רוח אחת שהיא חלק מכלל מחיצות שאר רוחות, והיינו, שכל מחיצה למרות שהיא גודרת לרוח אחת, הרי מכלל כל הרוחות הנצרכות להגדרת מקום רשות שהוא בעל כמה רוחות."}, {"s": "h7", "h": "כותל"}, {"s": "p", "h": "שם דופן חשובה שאינה ראויה להיטפל לשאר רוחות."}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"890\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">36\u003c/sup>\u003cspan class=\"ca\" data-c=\"890\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">עומד מרובה\u003c/span>"}, {"s": "p", "h": "דין המתייחס למקום הפרוץ במחיצה כסתום ע\"י התייחסות לכלל הרוח (או כלל הרוחות), וביטול האזור הפרוץ מהשפעה על כלל הרוח או כלל הרוחות ביחס למקום."}, {"s": "h7", "h": "פסי ביראות"}, {"s": "p", "h": "צורת מחיצות מיוחדת המגדירה את המקום בתוכה כנפרד אע\"פ שרוב הרוחות פרוצות."}, {"s": "h7", "h": "גידודי"}, {"s": "p", "h": "חלקי מחיצה שאינה שילמה, אך שם מחיצה קיים עליה לענינים מסוימים."}, {"s": "h7", "h": "גיפופי"}, {"s": "p", "h": "חלקי מחיצה שאינה שלימה, אך שם מחיצה קיים עליה לעניינים מסוימים."}, {"s": "h6", "h": "דיני פירצה"}, {"s": "p", "h": "חילוק גדר בין פירצה וביטול במחיצה – פירצה חסרון במחיצות מקום והביטול ביתרון כח הפורצן "}, {"s": "p", "h": "והנה מצאנו במחיצה הפסולה שתי שמות, פירצה וביטול. וגדר חילוקם שכח המבטל יגדיר כי סיבת אי נפרדות המקום מכח שחוצה לו, וזה לשון מבטלי מחיצה, וגדר פירצה נוגע לחסרון בכח המקום להפריד עצמו, והוא גדר האמור באתי רבים שהוא נוגע לכח החוץ לפעול עירוב, ופירצה נעשית ממילא. והיינו, כי הפרדת המקום מחוצה לו די במחיצה, ולא קרב זה אל זה, שאין למקום שחוצה לו שום גדר חיובי בנוגע לעירוב רשויות, ואין בכח שום מקום לחבר עצמו למקום אחר, אלא זה שייך רק ע\"י כח מערב חיובי, וגדר הנ\"ל הוא, שהשימוש האחיד שעושים הרבים בשתי המקומות משמעותו ביחס לשימוש ברשות שאין היא נפרדת מחוצה לה, אבל זה אינו די להפוך את המקום לפרוץ, דהא אית ליה מחיצה, ואין כח המערב הנ\"ל נוגע לנפרדות הנעשית ע\"י מחיצה. דכיון שהמקום נחשב לנפרד ע\"י מחיצתו, יש לו להגדיר את שימוש הרבים כשימוש נפרד מהשימוש במקום שחוצה לו. אבל כיון שדין מחיצה עצמו משמעותו מניעת רגל רבים, הרי שהשימוש האחיד מבטל את משמעות המחיצה כמונעת רגל רבים, וזה חסרון במחיצה עצמה. אך גדר המקום כפרוץ הוא נעשה ממילא אחר דליתא למחיצה, וע\"כ דין זה תלוהו בביטול מחיצה."}, {"s": "h7", "h": "שלושה טפחים"}, {"s": "p", "h": "גודל פירצה המפרידה בין חלקי המחיצה שלא יוכלו להיקרות אחד, ולהחיל שם גידור על מקום השלוש."}, {"s": "h7", "h": "ארבעה טפחים"}, {"s": "p", "h": "גודל פירצה חשובה הניתנת להגדרת מקום עצמית ופרוץ."}, {"s": "h7", "h": "עשר אמות"}, {"s": "p", "h": "גודל פירצה חשובה שאינה מושפעת בהגדרתה כפרוצה ע\"י דברים אחרים."}, {"s": "h7", "h": "פרוץ במלואו"}, {"s": "p", "h": "פירצה המתייחסת לרוח אחת כפרוצה לחלוטין ואינה ניתנת להגדרה ע\"י הרוחות האחרות."}, {"s": "h7", "h": "פרוץ מרובה"}, {"s": "p", "h": "דין המתייחס לרוח אחת (או לכלל הרוחות) שאין ביכולת המחיצה הקיימת (חשובה ככל שתהיה) להגדיר את שאר הרוח המרובה ממנה."}, {"s": "h7", "h": "פרצה בקרן זווית"}, {"s": "p", "h": "פרצה בקרן זווית – פרצה במיקום שאינו מאפשר להגדירה כפתח שאין דרך בני אדם לעשות במיקום זה פתח"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"891\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">37\u003c/sup>\u003cspan class=\"ca\" data-c=\"891\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">מפולש\u003c/span>"}, {"s": "p", "h": "שתי רוחות פרוצות היוצרות פירצה מתמשכת לעומק הרשות."}, {"s": "h7", "h": "בקעי ביה רבים"}, {"s": "p", "h": "שימוש ברשות באופן המערב את הרשות שמחוצה לו לתוכו."}, {"s": "h7", "h": "אתי רבים"}, {"s": "p", "h": "דין החל ברשות מוגדרת שנעשה בה שימוש שהוא חלק משימוש כולל ברשות אחרת המתנגדת להגדרתה, והוא מאחד אותה להיות חלק מאותה רשות (הרבים)."}, {"s": "h7", "h": "אתי אוירא דהאי גיסא"}, {"s": "p", "h": "דין המונע ממחיצה ראויה לגדור חלק ממקום כששאר המקום משני צידי המחיצה פרוצים."}, {"s": "h7", "h": "בקיעת גדי"}, {"s": "p", "h": "דין המונע ממחיצה ראויה לגדור מקום, כיון שהוא פרוץ מלמטה לכניסת גדי."}, {"s": "h7", "h": "דקירת גדי"}, {"s": "p", "h": "דין המונע משני חלקי מחיצה לגדור מקום כאחד, כיון שהוא פרוץ באמצעיתו לכניסת גדי."}, {"s": "h4", "h": "רשות הרבים"}, {"s": "p", "h": "כמו שכתבנו עיקר ההבחנה שיש ברשות הרבים מהבחינה השימושית היא, שהשימוש בה אינו בזכות וממילא גם שימוש שנעשה ע\"י אדם יחידי לצורכו המיוחד הרי הוא שימוש של רשות הרבים."}, {"s": "p", "h": "לרשות הרבים ניתנו כמה תנאים הנוגעים לצורת המקום והשימוש שעל פיהם תיקרא רשות הרבים מן התורה."}, {"s": "p", "h": "ומלבד זאת ישנם מקומות שיקראו רשות הרבים אף שאינם בתנאים אלו מחמת שהם נספחים אל הרשות ויש עליהם דיני רשות."}, {"s": "p", "h": "ותמצא מדיני רה\"ר (היינו, במה חשוב מקום כרה\"ר), דינים שהם במקום עצמו, ודינים שהם בשימושו. במקום עצמו, כמו שיעור רוחב רה\"ר וכו'. ובשימושו, מעבר ס' ריבוא, והיותו סרטיא או פלטיא או פתוח להם וכו'."}, {"s": "p", "h": "גדר מקום חפץ דרשות הרבים – אין קרקע רה\"ר אחת ומקומותיה נפרדים "}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"115\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">38\u003c/sup>\u003cspan class=\"ca\" data-c=\"115\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ובאמת כמש\"כ הרי זה יוצא מההבדל בין גדרי רה\"י ורה\"ר, שאין נחשבת קרקע כרה\"ר ע\"י תנאיה כהגדרה כוללת לכלל המקום, אלא כל חלק וחלק מרה\"ר יש בו גדר רה\"ר בנפרד. משא\"כ ברה\"י שכל גדריה הוא הגדרת המקום כאחד. וזה פשר שיש ברה\"י חסרון ברוב גודלה שהוא ביחס לאחידות המקום.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"116\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">39\u003c/sup>\u003cspan class=\"ca\" data-c=\"116\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וכן לרה\"ר שחפץ הנמצא בה חשוב כמוצא, כי יש איכות ברה\"ר שאין כלל מקומותיה חשובים להיות אחד, ואדרבה שהיא מפרידתם, והיינו, שאמנם ביחס לגדר כנוס שיש ברה\"י הרי משמעות זו ברה\"ר היא שלילית, אך יש גם איכות חיובית להחשיב כל מקום ומקום בה לנפרד, אפילו במקום שיש להחשיבו כאחד מצד עצמו וכמו מקום הנחתו של חפץ (היינו חפץ המונח כבר לגבי כלל המקום שעליו מונח), לא יחשב להיות מקום אחד ולא יהיה נפרד משאר מקומותיה, והרי זה חשוב כמי שנמצא בכמה מקומות ואין לו מקום.\u003c/span>"}, {"s": "h5", "h": "\u003csup class=\"cb\" data-c=\"892\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">40\u003c/sup>\u003cspan class=\"ca\" data-c=\"892\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">המבנה הממשי של רשות הרבים\u003c/span>"}, {"s": "p", "h": "מצאנו כמה דינים הנוגעים למבנה הממשי של רשות הרבים."}, {"s": "p", "h": "א. רוחבו (ואורכו) של רשות הרבים צריך להיות ט\"ז אמה."}, {"s": "p", "h": "ב. צריך שלא יהיה מקורה."}, {"s": "p", "h": "ג. שיעברו בו ס' ריבוא בכל יום."}, {"s": "p", "h": "חילוק גדר רשות ברה\"י מרה\"ר - רה\"י בקרקע נפרדת ורה\"ר בשימושה "}, {"s": "p", "h": "והנה בהקדם גדרי רה\"ר יבואר חילוק רה\"י ורה\"ר ובמה יחשבו לרשותם , היינו, דין גידור הנמצא ברה\"י, ודין שימוש הנמצא ברה\"ר, דלכאורה יחוייב גדר המשותף להיותם מחשיבים מעשה הוצאה בחפץ. וביאורו, דודאי אין גדר שינוי מקום חפץ דהוצאה אלא ביחס למקום חפץ, והוא בקרקע, וגדר רה\"י הוא גדר במקום אדם יחיד, וממילא גדר מקום חפץ הוא ביחס לשייכות אדם וחפץ, וגדר זה במקום הוא גדר סיום, היינו, מקום זה ולא מקום אחר, שזה המושג שייכות ביחס למקום. וע\"כ ביחס למקום חפץ, היינו, הקרקע, יהיה גדר שקרקע זו נפרדת. "}, {"s": "p", "h": "אך גדר רה\"ר אינו ביחס לאדם מסוים, שאין אדם אחד מגדיר רה\"ר, וע\"כ ביחס למקום חפץ לא יהיה הגדרת הקרקע במה שהיא נפרדת, ויותר מזה דאין כלל הגדרה בקרקע דרה\"ר בנפרד משימושה, דרוחב רה\"ר וצורתו הם גדרים שליליים דחוסר הגבלה. וא\"כ אין כלל הגדרה בצורת רה\"ר, אלא כל משמעות רה\"ר הוא בשימושה, וע\"כ לא תוגדר אלא בשימושה, וע\"כ תנאי רה\"ר הוא בשימוש. אלא דכיון שהוצאה נוגעת למקום חפץ, והיינו, קרקע הרי שגדר שימוש הרבים אינו רה\"ר עצמה, אלא ששימוש הרבים מגדיר את הקרקע, וזה באותה המשמעות כמו ברה\"י. "}, {"s": "p", "h": "וע\"כ כל שיעורי רה\"ר יהיו במובן של חוסר הגבלה, שאין הם משמעות חיובית בקרקע אלא בהגדרת השימוש. וע\"כ אם לא יהיה בהם משמעות ביחס לשימוש, היינו, שלא יהיה בהגבלה הנ\"ל, משמעות ביחס לשימוש, לא יהיה זה חסרון בהיות הקרקע רה\"ר, ואי איך שלא יהיה הרי שגדר רשות התורה הוא בקרקע המקום כי הם ביחס למקום חפץ, ואין מקום חפץ בכל הרשות אלא בקרקעה, וכל הדינים הנוגעים למה שהוא לא גדר בקרקע, הם בהכרח לא דינים עצמיים אלא ביחס לקרקע. "}, {"s": "p", "h": "וע\"כ לא יהיה גדר מחיצות דרה\"י אלא גדר בקרקע, והיינו, שאף שיש ברה\"י מה שאין ברה\"ר שיש בו משמעות שהוא תופס חלל, שהרי עולה עד הרקיע, אין זה חלק מהגדרת הרשות, שאין הגדרת הרשות אלא בקרקעה, והיא אינה אלא ביחס לגובה עשרה. וגם אין יועיל בה גדרים שאינם נוגעים לקרקעה באופן חיובי, ואם נמצא בדיניה גדרים הנוגעים לזה, הרי בהכרח שהם גדרים שליליים כמניעה וכו'."}, {"s": "p", "h": "[אך כאמור לעיל גדר מה שתקנו חכ' הוא ביחס הפוך, דאין הם דינים ביחס לקרקע, אלא ביחס לרשות עצמה, היינו, חללה. והיינו, שראו חכ' שאף שקרקע רה\"י מוגדרת היטיב כדינה מן התורה, הרי שהתייחסות האנשים לחלל הרשויות כזהות הרשות יביא להחליף את משמעות זהות הרשויות ממשמעות הקרקע למשמעות החלל. והרי אין דיני רשויות מן התורה מיועדים ומועילים להגדיר את החלל. וע\"כ תקנו דינים הנוגעים לחלל הרשות, והיינו, שאם היה ברור גדר זה דאין רשות אלא ביחס למקום חפץ, ואין רשות אלא בקרקעה, היה הבדל הרשויות ברור לאנשים. אך כיון דאין זה ברור, הרי שאנו נצרכים להגדיר אף את חלל הרשות, וזה משמעות מה שתיקוני מבוי שווים, בלי שייכות לדין מחיצות התורה, ובין אם יהיה הדין ב' או ג' מחיצות דאורייתא, יהיה דין להכשיר את המבוי מארבעה צדדים.]"}, {"s": "p", "h": "חילוק גדר קרקע רה\"ר מקרקע רה\"י - חפץ המונח ברה\"ר אינו נחשב כמונח בכלל הרשות "}, {"s": "p", "h": "ועכ\"פ מצאנו דגדר קרקע הנצרך לרה\"י הינו ביחס לשימוש אדם להנחת חפץ. אך אין זה הגדר בקרקע דרה\"ר, והיינו, דאף שצריך שיהיה מקום דרה\"ר ראוי להנחת חפץ, אין זה משמעות רה\"ר עצמה. כי אין משמעות חפץ המונח ברה\"ר (היינו, תוספת המשמעות האמורה לעיל המוגדרת כהוצאה) גדר רה\"ר עצמה. "}, {"s": "p", "h": "ודבר זה מוכח מזה שחפץ המונח ברה\"ר אינו נחשב שמקומו בכלל הרשות שנמצא בה, דא\"כ לא הוי ביה דין העברה, ובהכרח שמשמעות הרשות שלעצמה אינה בהיותה מקום חפץ. ויותר מזה דכיון שהיותה רה\"ר הוא גדר בדין העברה, בהכרח שביחס למקום חפץ דין רה\"ר הוא דין שלילי, ושלא יהיה חפץ הנמצא במקום הרשות כנמצא בכל הרשות (ויותר מזה מצאנו לדעת ר' יוסי דאף שתי רשויות הרבים נפרדות הוי אחד לגבי הוצאה)."}, {"s": "p", "h": "שיתוף גדר רה\"ר ורה\"י בהוצאה - שני גדרים במקום חפץ מונח ומשמעות היותו ברשות "}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"893\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">41\u003c/sup>\u003cspan class=\"ca\" data-c=\"893\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">וא\"כ הוא שאין רה\"ר גדר מקום חפץ, וא\"כ הוא שביארנו שדין רשות דהוצאה הוא דין במקום חפץ, הרי שביחס להגדרת שינוי שיש בדין הוצאה יהיה זה גדר שלילי, והיינו, שמה שמותר להעביר ד\"א בכרמלית זה משום שאין לנו לומר שיש הבדל ביחס למקום חפץ בין מקום זה שבכרמלית למקום אחר. וזה משום שכמו שאמרנו יש כאן שני גדרים, האחד, הוא מקום חפץ מונח, היינו, עצם מה שחפץ תופס מקומו, וזה משום חשיבות חפץ מונח ביחס למקום חפץ לעומת שאינו מונח. והגדר השני, הוא משמעות שיש בהיותו במקום, וכיון שמשמעות זו היא מוקדמת לעצם מקום חפץ והיא המגדירה שטח שמקום חפץ יהיה חלק ממנו, הרי שמשמעות רשות היא הגדרת מקום שאינו חלק מהגדרת מקום חפץ מונח מסוים, וכיון שזה אמור ביחס לקרקע לעומת אוויר, וכיון שאין ברה\"י אלא הגדרה זו, בהכרח שגם רה\"ר הוא בהגדרה זו. שאם אין הם באותו גדר לא יתכן לקרותו שינוי, אלא תוספת, וזה ברור.\u003c/span>"}, {"s": "p", "h": "שלילת חסרון אחידות ברה\"ר בהעברה ד' - מעשה העברה נחשב שינוי חשוב אף באותה רשות "}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"117\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">42\u003c/sup>\u003cspan class=\"ca\" data-c=\"117\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ונקדים להוציא מדעת מה שהיה לומר דדין העברה כשינוי מקום חפץ נובע מגדר רשות שבה נאסרה, היינו, רה\"ר, שאף שיש למצוא בדין העברה מכלל איסור הוצאה מרשות לרשות אנו למדים שהעברה חשיב שינוי במקום חפץ, אין זה משום חסרון אחידות משמעות היות חפץ ברה\"ר ומה שהיא אותה הרשות, שנאמר דלכן הוה כשני רשויות.\u003c/span>"}, {"s": "p", "h": "וזה אינו, שהרי אף ברה\"ר מצאנו שהיא רשות אחת, וכמו לענין הצטרפות הוצאת שני חצאי שיעור לשני רה\"ר דבגמ' בב\"ב (ואף לפר\"ח שם לא חלק רק שאין חסרון דמחוסר קירבה כמו בכתיבה. וע\"ש. ומש\"כ בזה), אלא ודאי דגדר העברה הוא באעפ\"כ, היינו, שאף שנעשית באותה הרשות, עדיין יהיה מעשה העברה נחשב שינוי חשוב במקום חפץ."}, {"s": "p", "h": "ראיה משיעור ד' אמות בהעברה - גדר העברה שינוי מקום חפץ ולא שינוי רשות עצמו "}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"118\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">43\u003c/sup>\u003cspan class=\"ca\" data-c=\"118\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וכן נראה שיש להוכיח שאין גדר העברה ברה\"ר שהוא מרה\"ר אחת לאחרת, במה ששיעור העברה הוא ד' אמות. שהנה אם היה בהעברה גדר מה שאין רה\"ר אחת היה די בהעברה ד\"ט שזה שיעור מקום חפץ, ואין לומר שאמנם חשיב רשות אחרת, אך מחמת שתוך ד\"א חשיב שהוא עדין ברשותו, דהמעביר זה חסרון, היינו, שרשות ד\"א שיש לאדם המעביר מאחד המקום להיות אחד, שהרי אף בעומד ברה\"י ומטלטל ברה\"ר, ואיכא ביני וביני מחיצה, וודאי אין נחשב שהחפץ ברשות המעביר, עדיין אין דין העברה אלא בד\"א.\u003c/span>"}, {"s": "p", "h": "והיינו, שאמנם שיעור ד\"א הוא שיעור בשימוש אדם, אך אין גדר במעשה העברה אלא בגדר מקום חפץ, שכיון שהוא בתוך מקום שימוש אדם אחד, הוא נחשב אותו מקום לענין שינוי מקום חפץ. וא\"כ צ\"ל שגדר מעשה הוצאה הוא שינוי מקום חפץ ביחס לשימושו ברשות, וגדר רה\"ר מה שאין היא מגדירה את כל מקומותיה אחד לענין מקום חפץ הוא גדר שלילי, ולא מעצם גדר מעשה הוצאה."}, {"s": "p", "h": "חילוק גדר מקום דרה\"ר מרה\"י - רה\"ר לשימוש זמני ורה\"י לשימוש קבוע דהנחה "}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"119\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">44\u003c/sup>\u003cspan class=\"ca\" data-c=\"119\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ומעתה יבואר ההבדל בין גדר מקום דרה\"ר לגדר מקום דרה\"י, והיינו, שדווקא ברה\"ר שאינה מיועדת לשימוש במקום אחד אלא להילוך יהיה גדר מקום חפץ ביחס לשימוש מקומי, אך ברה\"י שהיא מקום שאינו מיועד להילוך אלא לשימוש במקום, גם גדר מקום חפץ אינו ביחס לשימושו במקום המסויים, כי רה\"ר אינה נחשבת כמקום הראוי להנחת חפץ ואינה משמשת לכך, וע\"כ לא יהיה גדר במקום החפץ אלא ביחס לשימושו הנוכחי, שכל שימוש בחפץ ברה\"ר הוא ארעי.\u003c/span>"}, {"s": "p", "h": "אך ברה\"י המיועדת לשימוש במקום לא יהיה גדר מקום חפץ ביחס לשימוש ארעי כזה, אלא ביחס לשימוש קבוע דהוא שימוש דהנחה, וע\"כ לא יהיה לו משמעות בשימושו המקומי, וע\"כ לא יהיה הבדל בין רה\"י אחת לשניה, דכיון שביחס למושגי שימוש דרה\"י, היינו, מקום מנוחת חפץ, אין הבדל בין אחת לשניה, ואף שהם שתי רשויות נפרדות. ששימוש הנחה הנ\"ל הוא שימוש נפרד כיון שאין משמעות קירבה ביחס להנחת חפץ, שאין משמעות מקום חפץ ביחס להנחתו משמעות שימוש בפועל, ולא יהיה מחיצות שביניהם משמעות, שאין למחיצות משמעות הפרדה אלא ביחס לשימוש בפועל, ולא ביחס למשמעות הנחה."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"120\" style=\"--a:#dc2626;--abg:rgba(220,38,38,0.1)\">45\u003c/sup>\u003cspan class=\"ca\" data-c=\"120\" style=\"--a:#dc2626;--abg:rgba(220,38,38,0.1)\">(ורש\"י כתב דרה\"ר עבידא להילוך ורה\"י לתשמיש היחיד (דאין הילוך תשמיש אלא שימוש) והיא היא. וכן בזה יש לבאר סברת רב חסדא דלא בעי מקום ד' ברה\"י ותלה זה במה שהיא עולה עד הרקיע ובזה הרי לא פליגי כ\"ע וביאורו הוא דגם מה דעולה עד הרקיע הוא משום דאינו תלוי בשימוש המוגבל בי\"ט. ובמק\"א הארכתי)\u003c/span>"}, {"s": "p", "h": "גדר שימוש רה\"ר בהילוך ותשמיש - דריסת קרקע ללא תפיסת היחיד ברוחב ט\"ז אמה "}, {"s": "p", "h": "ועכ\"פ נמצא כי גדר רה\"ר הוא ביחס לשימוש אדם, והנה תמצא שימוש אדם במקום הוא בשני פנים, הילוך, ועמידה. וגדר שימוש הרבים הוא בהילוך, והילוך אדם אחד הוא ברוחב ד\"א, והילוך דרבים ברוחב ט\"ז אמה, והילוך דיחיד דד\"א הוא שיעור תפיסה, היינו, שהוא תופס בהילוכו רוחב ד\"א הנצרכים לו. והילוך דרבים דט\"ז אמה הוא בשלילת זה, היינו, שיהיה הילוך מבלי תפיסה ע\"י מי שהולך. והילוך, היינו, המשכיות הפסיעה, ופסיעה אחת דאדם היא באורך ד\"ט (דביותר מזה אין נחשב פסיעה, אלא קפיצה מהילוך להילוך, ואין נחשב ההילוך אחד, ואין קרקע נחשבת לשימוש אחד אלא בהילוך), והילוך הוא ביושר, והילוך ביושר הוא בתוך רוחב ד\"א, ויותר מזה הוא עיקוף. והילוך הרבים הוא הילוך הנוח והמיידי (היינו ללא עמידה), ודין רה\"ר כמו ברה\"י מוגדר בקרקע, והיינו, קרקע המשמשת להילוך הרבים, וכיון דאין הילוך הרבים אלא בט\"ז אמה, יהיו כל ט\"ז אמה אחד ברה\"ר ביחס להילוך, וע\"מ שיהיה נחשב הקרקע כקרקע המשמשת לרה\"ר צריך שיהיה בה ט\"ז אמה, והיינו, שהקרקע עצמה אינה מאוחדת בט\"ז אמה אלא שימוש הרבים אינו נחשב ככזה אלא ברוחב קרקע זה, ובפחות אינו נחשב הילוך הרבים. אך קרקע רה\"ר אינה אחת בט\"ז אמה, ואין לה רוחב, וע\"כ גדר ההילוך ביחס לקרקע הוא ע\"י דריסה, היינו, מה שדורסים בה הרבים בהילוכם, שאין משמעות בכל חלק מהקרקע במשך ההילוך, אלא בדריסה, וע\"כ כל מקום שיהיו הרבים דורסים כחלק מהילוכם יחשב כרה\"ר, וע\"כ לא יהיה עמידה חסרון בהגדרת קרקע כרה\"ר, אלא בהגדרת שימוש כזה כשימוש הרבים, וע\"כ אם יהיה עמידה שהיא מוגדרת כשימוש הרבים דריסת קרקע זו, גם תחשוב את הקרקע כרה\"ר."}, {"s": "p", "h": "קרקע דרשות האמור ביחס להילוך - קרקע רשות להנחת חפץ אינה מוגבלת לגדרי הילוך "}, {"s": "p", "h": "ודין קרקע האמור לגבי רשות הוא ביחס להנחת חפץ כאמור, ואין זה שייך לגדרי הילוך, וע\"כ אף שלא יחשב שימוש המגדיר רה\"ר אלא בדריסת קרקע דהילוך קרקע, הרשות עצמה לא תוגבל בגדר זה, וע\"כ שימוש הרבים אינו מגדיר ביחס לקרקע הרשות כדין בהילוך, וכל שימוש שיחשב שימוש הרבים יגדיר את הקרקע כמקום הנחשב כרה\"ר. והיינו, שאמנם רה\"ר המוגדרת כך היא ע\"י שימוש הרבים, והמושג שימוש הרבים הוא בהילוכם, וכל שימוש אחר אינו מוגדר שימוש הרבים אלא שימוש היחיד, אך אין הילוך עצמו הגדרת קרקע דרה\"ר, אלא עצם השימוש שביחס להילוך נקרא דריסה, אך כל שימוש שיחשב שימוש הרבים יגדיר את המקום המשומש כרה\"ר, וע\"כ שימוש שנחשב אחד עם הילוך גם הוא יחשב שימוש הרבים, וע\"כ עמידה שהיא חלק מהילוך כמו עמידה לכתף גם היא נחשבת לשימוש הרבים, כי אין גדר הילוך הרבים כסוג שימוש גדר חיובי של שימוש אדם, אלא גדר שלילי, היינו, שימוש המועט שאינו מבטל שימוש הרבים, שהרי אין הרבים אלא הרבה יחידים, ואין שימוש במקום אלא שימוש היחיד, והגדרת רבים אין היא חיובית ביחס ליחידים, אלא ביטול היחיד."}, {"s": "p", "h": "גדר שימוש הרבים ביחס למקום - שימוש שאינו סותר היות המקום לרבים כהילוך וכיתוף "}, {"s": "p", "h": "וע\"כ יהיה גדר שימוש הרבים ביחס למקום גדר ברבים ולא בשימוש, והיינו, עצם מה שהמקום הוא לרבים. ואם היה אפשר שיהיה הגדרה במקום שהוא לרבים, בלי היותם לא היה צריך את השימוש. אלא כיון שאין הגדרת המקום כרה\"ר אלא ע\"י היותם, ואין היותם אלא ע\"י שימושם, אלא שאין היחיד משתמש אלא לעצמו (ואף בהילוך), וא\"כ אין שימושו ראוי להגדיר רה\"ר, ע\"כ יהיה השימוש המגדיר את המקום שימוש שאינו סותר את היות המקום לרבים והיינו, הילוך, אלא שהרי הילוך דיחיד הוא תפיסת המקום ע\"י יחיד, ואמרו דבט\"ז אמה אין נחשב שהיחיד תופס המקום, דאין בשימושו כח לתפוס כזה רוחב (וזה גדר דהתפשטות ד\"א דיחיד ביחס למקום המיועד לשימוש הנ\"ל). וא\"כ יש כאן שימוש בלי תפיסה, וזה גדר שימוש דרבים אפילו ביחיד. ואמנם אין עמידה לפוש נחשבת הילוך, היינו, שימוש בלי תפיסה, אך עמידה לכתף אף היא נחשבת שימוש הרבים, שאף היא חלק מהילוך, וע\"כ כיתוף יחשב כשימוש הרבים להגדיר את המקום הראוי לכיתוף כחלק מהרשות, והיינו, עמוד ט'. ואף שאין הוא חלק מהקרקע דרה\"ר במובנה כמקום הרשות, הרי הוא נחשב חלק מהרשות עצמה במובן קרקע דהנחת חפץ, וכמו בדריסה דהילוך. ובזה יבואר גדר תשמיש, דהרי אף הילוך אינו אלא תשמיש ביחס להגדרתו את הקרקע כנדרסת, וכך הוא נקרא בכל מקום, אלא שהילוך נחשב לתשמיש ביחס להגדרת קרקע דרשות ביחס למקום חפץ, אך ביחס להגדרת שימוש הרבים הרי שהוא נחלק בזה מתשמיש, שתשמיש הוא במקום מסויים, והילוך הוא השימוש ההמשכי. ובזה יבואר מה שאין תשמיש מגדיר את הקרקע כהילוך דקרקע, דהילוך יש לה תפיסת י\"ט שהיא הגדרת קרקע הרשות, אך תשמיש רק מגדיר את המקום כמקום הרשות, וכמו אווירה, ולא כקרקע הרשות. וזה במשמעות קליטת רשות, היינו, שגדר קרקע הרשות הוא במשמעות קודם לרשות, אך קליטת הרשות הוא רק אחר שיש רשות, שחפץ הנמצא במקום הרשות יחשב כמונח ברשות."}, {"s": "p", "h": "דריסת הרבים בהגדרת קרקע רה\"ר - עמידה לכתף חלק משימוש הרבים כמו הילוך ממש "}, {"s": "p", "h": "וא\"כ הרי שדריסה ביחס לקרקע קודם הגדרת הרשות הוא בגדרי שימוש, וע\"כ יחשב דריסה שאינה נוחה כלא ניחא תשמישתיה, היינו, ביחס להגדרת קרקע כמשמשת לרבים, שאין שימוש כזה נחשב לשימוש לגבי דריסה, ולא נחשב דריסת רבים אפילו שרבים דורסים, דכיון שזה חסרון בצורת שימוש של רבים, אין זה רבים אלא הרבה יחידים (וזה גדר רבים מכתפים לה בכומתא וסודרא ברה\"י, שאף שודאי אין לזה גדר רה\"ר, דכיון שהוא רה\"י גם שימוש רבים נחשב לשימוש יחידים, אבל לגבי עירובי חצרות הרי אף הרבה יחידים הוא חסרון. ועוד יתבאר בעז\"ה), אך בזה יש גדר שני, והיינו, שאף אחר שישנם התנאים בקרקע להגדרת שימוש כשימוש הרבים, הרי אין הקרקע נחשבת לקרקע רה\"ר אלא ע\"י שימוש הרבים, ובזה איכא הבדל בין רה\"ר ליחיד, שכיון שאין רה\"י אלא בנפרדותה, וזה גדר חיובי, אין שייך שזה יתפשט למקום אחר, שאין נפרדות מתפשטת בחיבורה עם מקומות אחרים (אלא אדרבה היא נפרצת ע\"י החיבור), מאידך כיון שהגדרת רה\"ר היא ע\"י שימושה, וזה הרי שייך שיתפשט, והיינו, שכל מקום שיהיה משמש את הרבים באחת עם מקום שימוש הרבים, יחשב גם הוא רה\"ר. וגדר זה הוא בכל רה\"ר, שכיון שאין רה\"ר מוגדרת אלא ע\"י שימוש הרבים, הרי שכל מקום ומקום מוגדר בנפרד ע\"י שימוש הרבים."}, {"s": "p", "h": "התפשטות שימוש רבים למקומות סמוכים – גדר עמוד ט' שנחשב שימוש אחד עם שימוש רה\"ר "}, {"s": "p", "h": "וע\"כ יהיה שייך שאף במקומות שאין בהם תנאים להגדרת השימוש כשימוש הרבים מחמת רוחבם וכו', כיון שהם משמשים כאחת עם רה\"ר גם הם יחשבו כך מחמת השימוש עצמו. ובזה לא נצטרך לתנאים דלעיל אלא רק מה שלא יחשב המקום נפרד ביחס לשימוש. וע\"כ עמוד תשעה יחשב לרה\"ר אף שהוא נחשב מקום נפרד מצד קרקע, אך הוא אחד עם השימוש. ובזה גם שייך שתהיה רה\"ר נפרדת ביחס לדבר הצריך חיבור כמו הנחת חפץ, היינו, שאף ששני מקומות יחשבו לרה\"ר ולא יהיה ביניהם נפרדות קרקע, כיון שהם נפרדים ע\"י שימוש לא יחשב לרשות שימוש אחת."}, {"s": "p", "h": "גדרים בהתפשטות שימוש הרבים למקום אחר – התפשטות השימוש הנובעת מדחק כבקרן זווית "}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"894\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">46\u003c/sup>\u003cspan class=\"ca\" data-c=\"894\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ובהתפשטות שימוש הרבים לעוד מקומות נמצא כמה גדרים, וכמו ע\"י הדחק, היינו, שאף אם יהיה מקום המשמש את הרבים באחת עם רה\"ר שלידו, והיה לו להיחשב כאחד, כיון שאין זה מכוחו אלא מכח התפשטות של שימוש שלידו, צריך שהוא יהיה משמש באחת, ומקום שמתפשט שימוש הרבים אליו משום הדחק שיש ברה\"ר, הוא חסרון בעצם ההתפשטות להגדיר את השימוש אחד עם שימוש שלידו, ושימוש שהוא משום שאין מקום ברה\"ר, אין הוא נחשב שימוש אחד. ועל זה אמרו שהילוך שע\"י הדחק נחשב הילוך, ותשמיש שע\"י הדחק אינו נחשב תשמיש. וביאורו שכיון ששימוש הרבים בהילוך הוא עיקר שם שימוש הרבים, אף שנעשה ע\"י הדחק, אחר שנעשה אין הבדל בינו לבין שימוש מקודם לו. אך תשמיש שאין הוא נחשב חלק משימוש רבים דקרקע, ואין הוא משמעות שימוש הרבים עצמו, אלא רק בזה שהוא מחובר להילוך שלידו, אם נעשה שימוש זה ע\"י הדחק, אין נחשב להיקרות מחובר. אך הילוך כזה נחשב הילוך, וזה גדר קרן זווית, שאמנם יש בה הילוך ע\"י הדחק, ונחשב הילוך אחד, אך מקום קרן זווית עצמה יש בו חסרון בהילוך שלא נוח תשמישו. וזה חסרון בהגדרת שימוש הרבים, ולא יועיל ההתפשטות. וזה גם גדר מאי דלא מסגי בהדיא, שאין זה נחשב שימוש אחד אלא שימוש אחר, וכיון שאין במקום עצמו גדר רה\"ר אין זה נחשב שימוש הרבים.\u003c/span>"}, {"s": "h7", "h": "גידור ושיעור ט\"ז ברשות הרבים - רוחב השתמשות מול מחיצות ושיטת הרשב\"א בפלטיא"}, {"s": "p", "h": "ובענין גידור דרשות הרבים שלכאורה משמע דגידור הוא סתירה לצורת רשות הרבים, ואינו ענין אלא לרשות היחיד. וממילא יש לבאר גדר טז' אמה מלבד רוחב השתמשות הראויה לרבים, גם כרוחב שמחיצות כבר אינם משפיעות עליו לענין רשות הרבים. "}, {"s": "p", "h": "ואמנם מצאנו ברשב\"א דפירש פלטיא שהוא מקום סגור מארבע רוחות, וגודלו טז' אמה על טז' אמה (ולשון טז' מרובע הוא גם בטור). ואם כן קשה לומר דדין טז' הוא למנוע השפעת המחיצות על מקום רשות הרבים, דאין לומר כן כשיש ארבע מחיצות. אלא יש לבאר לדעתו ז\"ל גדר טז' אמה כרוחב השתמשות בלבד."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"895\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">47\u003c/sup>\u003cspan class=\"ca\" data-c=\"895\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">והנה דעת ר' יהודה דב' מחיצות דאורייתא, וכן מצאנו דמערבין רשות הרבים לחי או קורה מכאן וכו', ומלבד זה מצאנו דאית ליה לר\"י דרוחב פרצה הוא יג' אמה ושליש, וכן מצאנו לו דין דאתי רבים ומבטלי מחיצתא. ולתירוץ שני העניינים הראשונים, כתבו בתוס' לתרץ דרשות הרבים האמור מתקצרת פחות מיג' אמה ושליש בין שני רשות הרבים רחבים טז' אמה, שיש בזה דין רשות הרבים משום שהוא המשך של רשות הרבים שיש בו שיעור, ומאידך שייך בו לחי או קורה מכאן וכו'. \u003c/span>"}, {"s": "h7", "h": "שתי מחיצות דר' יהודה ברה\"ר – דעת תוס' בגדר הנ\"ל מה דעביד לרה\"י הוה ביטול רה\"ר"}, {"s": "p", "h": "עכ\"פ מצאנו דדין ב' מחיצות אינו עניין לדין רשות הרבים, דאפילו תוס' לא נחתי אלא לעניין עשיית לחי או קורה לעשותו רשות היחיד, אבל משום טעם דב' מחיצות הוו סתירה לרשות הרבים לא אתו. והנה בתוס' פ\"ב בעניין ירושלים הקשו דלר\"י עדיין כיון דהוי ב' מחיצות דאורייתא, אם כן אין זה רשות הרבים אפילו אינם ננעלות, וכתבו לתרץ שיש מקום בירושלים דאין לו מחיצות כלל, כגון שהעיר חצויה לארכה ולרחבה, ויש באמצע מקום פרוץ לכל הרוחות (וקשה שהרי אין דין ארבע מחיצות לארבע רוחות ואם כן הרי במקרה זה אפשר לראות המקום הפרוץ באמצע כגדור משאר רוחות וא\"ת כיון שהם עשויים כקרן זווית ואין פנים מחיתה לקרנות הרי אמרינן בפסים חוקקין להשלים ולא יגרע וצ\"ע)."}, {"s": "p", "h": "ועכ\"פ משמע בתוס' שאף שאין מתירים רה\"י לר\"י יותר מיג' אמה ושליש, עכ\"פ גם דין רשות הרבים לא נחתה ליה, כיון שיש לו מחיצות. וכן משמע מגמ' ותירוצי הראשונים למה לא יהיה גבולות הארץ ואוקיינוס לעולם כארבע מחיצות, ואין לחלק בין ארבע מחיצות לרבנן לדין ב' מחיצות דר\"י, ואין מרחק טז' אמה בין מחיצות מספיק להיות המחיצות לא משפיעות על מקום רה\"ר. וברשב\"א התקשה בתירוץ התוס' דירושלים. ותימה שלא הזכיר שיטתו (בעה\"ק) בעניין פלטיא דודאי לא שנא אף לר\"י, וגם הקשה שם מגמרא (ו:) למה לא אמרו דאיירי באין פרוץ מד' רוחות."}, {"s": "h5", "h": "\u003csup class=\"cb\" data-c=\"896\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">48\u003c/sup>\u003cspan class=\"ca\" data-c=\"896\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">הגדרות השימושיות של רשות הרבים\u003c/span>"}, {"s": "p", "h": "הנה כמשנ\"ת דיני רשות הרבים בכל מקום, שורשם שיהיה מקום זה מיועד לשימוש הרבים כל אחד שירצה."}, {"s": "p", "h": "משמעות שימוש הרבים לגבי קרקע - הרבים מגדירים משמעות שימוש הקרקע ולא הקרקע עצמה "}, {"s": "p", "h": "והביאור בזה בהקדם מה דצ\"ב איך בכלל יגדיר שימוש הרבים גדר בקרקע, אחר שהקרקע אינה מושפעת ע\"י שימוש בה. ובהכרח שאין זה דין בקרקע עצמה, אלא במה שיש בה אפשרות שימוש, ובזה יש לרבים להגדיר את משמעות שימוש הקרקע, והיותה מוכנה לשימוש, שהרי גדרה הנ\"ל הוא מכוחם (שאין משמעות שימוש בקרקע בלי משתמשים). וע\"כ עצם גדר הקרקע אין הוא מוגדר ע\"י הרבים, וההפך שהוא מגדיר את השימוש (והרי זה ההבדל בין רשות לסתם אוויר מקום שאין שייך רשות באוויר אלא בקרקע)."}, {"s": "p", "h": "גדר כח יהושע בהנחלת הארץ - כח הנ\"ל להיות מגדיר מסירת קרקע לשימוש הרבים והיחיד "}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"897\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">50\u003c/sup>\u003csup class=\"cb\" data-c=\"121\" style=\"--a:#dc2626;--abg:rgba(220,38,38,0.1)\">49\u003c/sup>\u003cspan class=\"ca\" data-c=\"121 897\" style=\"--a:#dc2626;--abg:rgba(220,38,38,0.1)\">ולפ\"ז יש למצוא גדר במה דזה תלוי במסירת יהושע ובכוחו להנחיל את הארץ, כי דין התורה במה נחשב רה\"ר הוא בקרקע שאין לה משמעות שימושית בעצמה, שבזה אמרה תורה ששימוש הרבים בה יחשיבה כרה\"ר, ובאמת בזה אין ליהושע לחדש דין (יותר ממה שאין לחכ' בכל דור), דבהגדרת שימוש הרבים עצמם ודאי שאין ליהושע כח, שלא ניתן לו כח באנשים, ואף בקרקע הרי לא ניתן לו כח אלא לחלוקתה, ואין לו בה קניין, ואין לו כח להגבילה בגדרים קניניים, וגם אין גדר רה\"ר תלוי בקניין (דא\"כ לא אתי מה דאמר ר' יוחנן בירושלים אלא למ\"ד דלא נתחלקה לשבטים, ואף אי נימא דאין קנין השבט כמו קנין יחיד לגבי זה, הרי שהיה לברר בכל מקום מה הונחל ליחיד ומה לא. וגם אין אפשרות לברר זה בקרקע שאין נוחות תשמישה קבוע, וגם ברור דאין זה גדר תפיסת שבט או תפיסת יחיד דשבט, דזה שייך לגדרי אחוזת אבות ולא לגדרי קנין, דלמי חוזרת ביובל. ואכמ\"ל). אלא שכיון שניתן לו להנחיל ולחלקה לכל ישראל, היה לו גם כח להגדיר מקום לכל ישראל, היינו, מה שזה צורכם, וגם זה בגדר חלוקה, שזה שיהיה מקום שהוא לשימוש הרבים אין זה גדר של זכות וחובה הסותר לזכות היחיד, וכולם צריכים לזה, וע\"כ גם זה הוא מדין חלוקה. וחלוקת הארץ לשימושיה אכן היה בכוחו, ובזה שחילק סוג הקרקע ביחס לשימוש הרבים והיחיד, הרי שהגדיר שבארץ ישראל יש משמעות בסוג הקרקע לשימושיה, וזה כמש\"כ קודם לדין רה\"ר דאורייתא שבדין התורה גדר הקרקע דרה\"ר הוא גדר שלילי (ושאין זה חלק מדיני התורה שהרי אינו אלא בקרקע דארץ ישראל ואין דין הוצאה תלוי בארץ), ודין התורה שיחשב קרקע רה\"ר ע\"י שימוש הרבים הוא ביחס לקרקע, ותקנת יהושע הוא ביחס לשימוש, אך הגדרת השימוש תשפיע על דיני התורה בהגדרת קרקע ע\"פ שימוש, וע\"כ לא יהיה זה שייך אלא בהנחלת יהושע את הארץ, ולא בשאר ארצות אף שיהיו חוקקים חוק דומה, כי אף שיהיה להם שלטון על אנשים (ודינא דמלכותא דינא), אין זה גדר ביחס לרבים ככלל אלא לכל יחיד בפרט וכו'. וע\"כ יבואר מה שחסרון דמעלות ומורדות דא\"י הוא חסרון בדיני התורה, ובמה שאין דומה קרקע דמעלות ומורדות דא\"י לדגלי מדבר.\u003c/span>"}, {"s": "p", "h": "סיכום תנאי רשות הרבים בקרקע - שלבי הגדרת מקום מקרקע לרשות של הילוך לרבים "}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"899\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">52\u003c/sup>\u003csup class=\"cb\" data-c=\"898\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">51\u003c/sup>\u003cspan class=\"ca\" data-c=\"898 899\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">וא\"כ מצאנו כמה תנאים ברה\"ר, זה לפנים מזה, דגדר הקרקע כמקום הראוי להנחת חפץ הוא תנאי ראשון, ובזה אין צורך שיהיה תשמישו נח, אלא גדרו הוא בעצם מושג קרקע לעומת אוויר, וזה גדר קרקע לכל הרשויות. ובהשלם מקום זה התנאי הרי שניתן להגדירו כמקום דרשות. ורה\"י הוא מקום תשמיש ליחיד, ורה\"ר הוא מקום הילוך לרבים (וגדר זה ואיך זה נעשה ע\"י שימוש הרבים יבואר בעז\"ה). והגדרת קרקע כמקום נפרד הוא במשמעותה ביחס לתשמיש, והגדרת קרקע כמקום הרבים הוא ביחס להגדרתה כמקום שימוש, ויהיה הגדרתה בזה ע\"י שימוש הרבים בפועל, ששימוש הרבים מגדיר את הקרקע במשמעותה השימושית כמקום הרבים, וגדר שימוש הרבים הרי שזה ביחס לשימושי אדם באופן כללי. ובזה נחלקו א\"י וחו\"ל שבא\"י אין נחשב שימוש דרוב יחידים במקום דלא ניחא תשמישתיה כשימוש הרבים, ובחו\"ל ליתא לזה. וע\"כ היא ביחס לשימושי אדם באופן כללי, ושאר תנאי רשויות ושייכות מקום לרשות (שלא בגדר קרקע) שונים מרשות לרשות ע\"פ החלוקה האמורה, ושאר דיני הוצאת חפץ שווים בכל הרשויות.\u003c/span>"}, {"s": "h7", "h": "ביאור שלושה סוגי רה\"ר וגדרם המאוחד – רה\"ר, סמטא, צידי רה\"ר"}, {"s": "p", "h": "ומצאנו ברשות הרבים שבשאר דיני התורה שלושה סוגים. א. רשות הרבים. ב. סימטא. ג. צידי רשות הרבים. וברש\"י ב\"מ (י:) ביאר את ההבדל בין שלושת רשויות אלו, שסמטא הוא רשות לכל אדם, וצידי רשות הרבים היא הפקר לרבים, ורשות הרבים הרי היא כמשמעו, ומדבריו נלמד שחילוקי גדרים במקום המיועד לשימוש הרבים, והם בשלושה כאמור."}, {"s": "p", "h": "רשות הרבים, והיא המיועדת לשימושיו הציבוריים של האדם היחיד, ולכל אדם שירצה בכך, והיא רשות הרבים כמשמעו, ושימוש פרטי בה כסותר את יעוד המקום, כיון שהוא גוזל מהרבים את האפשרות להשתמש שימושים ציבוריים, וזכותם למנוע ממנו שימוש כזה, והיא רשות הרבים שבדיני שבת."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"900\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">53\u003c/sup>\u003cspan class=\"ca\" data-c=\"900\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">סמטא, והיא המיועדת לשימושיו הפרטיים של האדם היחיד ולכל אדם שירצה בכך. והיא זכות כל אדם, ואין זכות למנוע ממנו שימושים פרטיים, כל זמן שאינם מבטלים את האפשרות שכל אדם ישתמש בהם, ואפילו בעת אחרת, וזו אינה נחשבת רשות הרבים לענייני שבת.\u003c/span>"}, {"s": "p", "h": "צידי רשות הרבים, הוא הפקר לרבים. והיא אינה מיועדת לשום תשמיש, וכן אינה מקבלת שום יעוד כזה, ולכן יכול כל אדם להשתמש שם. אך שימוש שכזה אינו שימוש בזכות כלל, ובזו חלקו ר\"א וחכ' אם נחשבת רשות הרבים."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"901\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">54\u003c/sup>\u003cspan class=\"ca\" data-c=\"901\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ויש לשמוע מהנ\"ל שמהות השימוש ברשות הרבים (לדעת חכמים לכל הפחות) הוא שימוש בזכות כמו ברשות היחיד לעניין השימוש הציבורי אך אינו מיועד לשימושים פרטיים כלל ויש למשתמשי השימוש הציבורי זכות למנוע כזה שימוש.\u003c/span>"}, {"s": "p", "h": "גדר חלוק בשימוש רה\"ר - ההילוך בקרקע והתשמיש בכיתוף "}, {"s": "p", "h": "ובזה יבואר מה שחילקו בגמ' בין מקום הילוך למקום תשמיש, וכי הם שני סוגי שימוש שיהיה ברשות (הרבים). ותשמיש, היינו, במקום עצמו, ויהיה נחשב כחלק מרה\"ר משום שהוא משמש את הקרקע שלה, וכמו בכיתוף שהאדם עומד בקרקע ומכתף על העמוד, ואף שאין בזה להגדיר את העמוד כקרקע, אבל יהיה בזה השימוש לבטל ממנו דין קרקע נפרד שהיה לו (וזה מה שאין חסרון בחורי רה\"ר במה שאין הם בגובה ט', דכיון שאין בחורים צורך בהגדרת שימושם עם קרקע, שזה נצרך רק כצריך להגדיר קרקע נפרדת כתשמיש הרשות, אבל בחורים שאין גדר קרקע נפרד לא יהיה צריך אלא שישמשו את רה\"ר, ויהיו כאווירה, היינו, אחר שיש רשות (וזה גופא נסתפקו בחורי רה\"ר אי איכא ברה\"ר גדר שלא ביחס לקרקע). וע\"כ לא יהיה בהם חסרון מחיצות ושיעור וכו'), אבל הילוך הוא בקרקע עצמה והילוך אחיד מחשיב את הקרקע כאחת, ולא משום שמשמש את הקרקע, וע\"כ אם יהיה ההילוך בקרקע שהיא נפרדת בעצמה כמו ע\"י מחיצה, לא יועיל בזה הילוך, שנפרדות הקרקע תגדיר את ההילוך כנפרד ולא ההילוך אותה, שהנפרדות גדר בקרקע, וההילוך גדר בשימוש בה (ולא שלה). אבל תשמיש הרי אינו בקרקע, וגם אינו מגדיר את המקום כקרקע אחת, וע\"כ אפשר שע\"י שימוש המוגדר אחד עם שימוש הקרקע דרה\"ר יחשיב המקום כחלק מרה\"ר לר\"י."}, {"s": "p", "h": "סיכום שימוש המגדיר רה\"ר – דריסת רגל הרבים המגדירה את הקרקע "}, {"s": "p", "h": "וא\"כ מצאנו דעיקר גדר רה\"ר הוא במה שהרבים משתמשים בו, ועיקר שימוש הרבים הוא הילוך, היינו, דריסת הרגל, דהוא שימוש היחיד שאינו נצרך למקום נפרד, כי אין חסרון לגבי מקום דריסת רגל דיחיד במה שאף אחרים דורסים בו, וכמש\"כ אין נחשב שימוש הרבים אלא במקום שאין שימוש כל אחד תופס הרשות, וזה שיעור ט\"ז אמה. אך אחר שיחשב המקום ראוי לשימוש הרבים יהיה זה גדר בשימושם שיחשב שימוש הרבים, וכל קרקע שיהיו רבים משתמשים בה תחשב כקרקע הרבים, אף אם אין בה שיעור זה (וזה הדין בכל רה\"ר ואף בט\"ז אמה שלה) וכמש\"כ אף שעצם שימוש הרבים הוא בכל הרשות תהיה הגדרתם ביחס להוצאה רק בקרקע שהיא נחשבת לגבי מקום הראוי להנחת חפץ, וכל מקום שיהיה ראוי לזה יחשב לקרקע, אך כיון ששימוש הרבים הוא בהילוך צריך שיהיה זה המקום משמש כחלק מהילוך, וכן אין קרקע רה\"ר נפרדת אלא ביחס לשימוש, היינו, הילוך, וכל מה שישמש הילוך אחד עם שימוש הרבים יחשב כרה\"ר."}], "comments": [{"id": "867", "n": 1, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-070 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (1 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. המושג מקום יש לו משמעויות מציאותיות ומשמעויות שימושיות, ההגדרות היסודיות הן המשמעויות המציאותיות של מושגי חפץ ומקום והמושגים השימושיים בנויים על המשמעויות המציאותיות ועל כן יהיו גדריהם דומים.\u003c/p>"}, {"id": "868", "n": 2, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-071 | סוג: קטע חסר | מקור: 08_הקדמות_והצעות_נוסח/הצעות נוסח להקדמה - מלאכת הוצאה, גדרי מעשה, מצוות ומלאכת שבת.docx\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"וגדרי מקום חפצים האמורין במלאכת הוצאה הם גדרים הנוגעים למושג השימושי של מקום, ולא במשמעות מקום המוקדמת, אך יש ...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>גדרי מקום המושג מקום יש לו משמעויות מציאותיות ומשמעויות שימושיות ,ההגדרות היסודיות הן המשמעויות המציאותיות של מושגי חפץ ומקום והמושגים השימושיים בנויים על המשמעויות המציאותיות ועל כן יהיו גדריהם דומים.\u003c/p>\u003cp>הגדרות מציאותיות\u003c/p>"}, {"id": "869", "n": 3, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-072 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (12 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. שם מקום בשני מובנים - ביחס לדברים הצריכים מקום וביחס לשאר מקומות\u003c/p>\u003cp>2. איחוד כל השבתות שמירה ביני ובין בני ישראל אות ברית לדורות לעולם\u003c/p>\u003cp>3. איחוד שבת אחת עשיה\u003c/p>\u003cp>4. חילוק שבת למעשים מלאכות\u003c/p>\u003cp>5. חילוק שבת לזמנים חילול איחוד הזמנים קודש\u003c/p>\u003cp>6. ידיעת מושג שבת כל השבתות אחת\u003c/p>\u003cp>7. ידיעת זמן שבת כל השבת אחת\u003c/p>\u003cp>8. ידיעת מלאכת שבת כל המלאכה אחת\u003c/p>\u003cp>9. דין מי ששכח זמן שבת מונה ששה ומשמר אחת או משמר אחת ומונה ששה בקידוש והבדלה\u003c/p>\u003cp>10. השוכח עיקר שבת חייב אחת על כל השבתות את שבתותי תשמורו\u003c/p>\u003cp>11. השוכח שהיום שבת חייב על כל שבת ושבת ושמרו בני ישראל את השבת\u003c/p>\u003cp>12. מחלליה מות יומת יום ולילה ואפילו חילל מקצתה חייב לשמור\u003c/p>"}, {"id": "103", "n": 4, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-183 | חומרה: בינונית | קטגוריה: מעבר מושגי והשתלבות בהקדמה. הפסקה ממשיכה את P00473, שבה נקבע שכל דין הנוגע למקום מתייחס לחשיבותו ביחס לדבר אחר ולא לחסרון בעצם קיומו. כאן מתחדש שמושג המקום עצמו מתקיים בכל אחד מממדיו — רוחב, אורך וגובה — גם בלא צירופם למרחב מעוקב. כדאי לבדוק אם המעבר מן „חשיבות המקום ביחס לדבר אחר” אל בירור עצם מושג המקום מוצג במפורש, כדי שלא ייראה כסטייה לנושא חדש. יש לוודא שהדוגמאות של דבר שאורכו יתר על רוחבו והדיון בשיעור הנוגע רק לאורך אכן משרתים את ההבחנה המרכזית, ושסיום הפסקה מכין את הכותרת P00475 על שני מובני שם מקום. ההופעה ב־P02991 היא פיתוח בגוף הספר; ההצגה המוקדמת נשמרת כחלק מן ההקדמה, והבדיקה נוגעת רק לרצף ולבהירות שלה.\u003c/p>"}, {"id": "104", "n": 5, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-188 | חומרה: בינונית | קטגוריה: המשכיות בין הגדרה לדוגמה. פסקה זו ממשיכה את P00478, המבחינה בין גדרי מקום לבין גדרי רשות, ומפרטת את משמעותו של שיעור הנמדד לאורך ולרוחב בלי להגדיר חלל בעל עובי. כדאי לוודא שהפתיחה „וזה גדר כל שיעור” חוזרת בבירור להגדרה שבפסקה הקודמת, ושהדוגמה של ארבעה טפחים על ארבעה טפחים אכן מבהירה את היחס בין שיעור שטח לבין שיעור אורך ורוחב. סיום הפסקה צריך להכין את הכותרת P00480 „הגדרות שימושיות” — המעבר מן הגדרים הכלליים של מקום אל משמעות המקום ביחס לשימוש האדם. ההופעה המקבילה ב־P03004 נשארת בגוף הספר, והבדיקה כאן אינה על עצם החזרה אלא על כך שההופעה שבהקדמה תהיה חוליה טבעית במעבר שבין P00478 לכותרת P00480.\u003c/p>"}, {"id": "105", "n": 6, "a": "עורך – ביקורת ראשונית", "d": "2026-11-04", "h": "\u003cp>E-0005 | חומרה: בינונית | קטגוריה: התאמה דקדוקית. לכאורה נדרשת התאמה בין \"המשמעות\" (נקבה) לבין הנשוא: \"המשמעות הראשונה היא משמעות של קירבה\". יש לבדוק גם משפטים מקבילים שבהם \"משמעות\" משמשת כנושא.\u003c/p>"}, {"id": "870", "n": 7, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-073 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/מלאכת שבת רשויות עירובי חצירות תחומין.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"מנוחה...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>הרחבת ההיבט הרעיוני-סוציאלי (העבד, השור והחמור). מקומו הטבעי כאן לאחר שביססנו את גדרי 'יום השביעי' כמחזור זמנים אנושי של עבודה ומנוחה מול עבדות.\u003c/p>"}, {"id": "871", "n": 8, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-074 | סוג: קטע חסר | מקור: 07_קדושת_שבת_והכנה/מאמר גדרי יום השבת - עותק 2.html / 07_קדושת_שבת_והכנה/קדושת שבת - עותק 3.docx\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"מנוחה...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>גדרי יום השבת\u003c/p>\u003cp>איחוד כל השבתות שמירה ביני ובין בני ישראל אות ברית לדורות לעולם\u003c/p>"}, {"id": "872", "n": 9, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-075 | סוג: קטע חסר | מקור: 07_קדושת_שבת_והכנה/קדושת שבת - עותק 1.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"מנוחה...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>המקום והדבר המשמעות הראשונה היא במשמעות הקיום עצמה שאין דבר שאין לו מקום וא\"כ מקומו של דבר ממנו קומו שעצם קיום דבר תלוי בהיות לו מקום כהקדמה למציאותו ,ואין הכוונה שיש מקום לפני היות הדבר ,אלא שקיום הדבר מחוייב היות לו מקום וזו משמעות קיומית .ואף שמשמעות זו אינה שייכת למקום חפץ שהרי ביחס לקיום אין החפץ חתיכה אחת של קיום אלא קובץ של דברים הקיימים לעצמם ומקום הקיום הוא ביחס אליהם ,יהיה לה שייכות ביחס לגדרי הוצאה במשמעות חפץ הנמצא במקום.\u003c/p>"}, {"id": "873", "n": 10, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-076 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (2 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. גובה מקום הנמשך משטחו ולא כחלל\u003c/p>\u003cp>2. ייחוד קרקע רה\"ר בשיעוריה\u003c/p>"}, {"id": "874", "n": 11, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-077 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/מלאכת שבת רשויות עירובי חצירות תחומין.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ארבעה טפחים...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>פרוץ פתוח גדור בדין טלטול מבית לבית בכמה מקומות מוכח שיש איסור להוציא חפץ מבית לבית של אחר והדבר מתמיה מה שאגב ריהטא יש להבין שהאיסור להוציא מבית לחצר דרבים הוא איסור הדומה כאחד שמוציא מרשות היחיד לרשות הרבים וטעם זה לכאורה לא שייך בהוצאה מבית לבית שהבית השני אינו דומה לרה\"ר והטעם המתאים יהיה לומר שהחשש מלהגיע להוצאה מרשות היחיד לרשות הרבים יתן טעם לגזירה להוציא מכל רשות אחת לשניה הנפרדת לה וכמו שנראה מלשון רש\"י (?) שהוא עיקר הגזירה אף בהוצאה מבית לחצר והנה למרות שבחשבון הטעמים לטעם הראשון ההוצאה מבית לחצר תוביל להוצאה דאורייתא יותר מאשר ההוצאה מבית לבית אך לטעם השני וודאי נאמר שההוצאה מבית מיוחד לחצר שאינו מיוחד אך משותף הוא פחות מוגדר כשינוי מרשות לרשות מאשר מבית מיוחד לבית שאינו בו שייכות כלל ר' חיים סטנסיל יש לחקור בהא דצו״פ מתיר לענין הוצאה ועירובין היינו משוס דצורת הפתח יש לו דין פתח והוא נעשה פתח ממש ,או דלמא דצורת הפתח אינו פתח אלא הוא דין בפ״ע דצורת הפתח מתיר לענין הוצאה וטילטול ,ופשר הדבר הוא ממה שכתב הרמב\"ם בפרק ט״ז מהלכות שבת הלכה כ' צורת הפחח שעשה א ותה מן הצד אינה כלום שאין דרך הפתחים להיות בקרן זוית אלא באמצע עכ״ל .ואם נימא שהוא דין בפני עצמו שצורת הפחח מתיר מה בכך מה שאין דרך הפתחים בכך להיות בקרן זוית הא מ״מ יש כאן צורת הפתח עם כל הדינים ,ומוכח מכאן שכל ההיתר של צורח הפתח\u003c/p>"}, {"id": "875", "n": 12, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-078 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (1 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. כמו שכתבנו לעיל רשות היא מקום המיועד לשימוש\u003c/p>"}, {"id": "876", "n": 13, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-079 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/מלאכת שבת רשויות עירובי חצירות תחומין.pdf / 02_קובץ_מאוחד/קובץ מאוחד - הקדמות - עותק 2.txt / 02_קובץ_מאוחד/קובץ מאוחד - עותק 1.docx ועוד\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ומאחר שמלאכת הוצאה בשבת נוגעת במעשה אדם בחפץ ובמקום. יהיו גדרי המלאכה ושיעוריה קבועים לפי שלושה חלקים אלו, דהי...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>וכיון שחלקים אלו מוגדרים ביחס אחד לשני, יש לנו לחלק ולהגדיר איזה גדר הוא חלק מהגדרות החפץ, ואיזה הוא חלק מהגדרות המקום, ואיזה הוא חלק מהגדרת מעשה האדם.\u003c/p>\u003cp>ועל כן יש לנו להגדיר את המושגים הנ\"ל בנפרד ואחר כן ביחס לשני המושגים האחרים.\u003c/p>\u003cp>מקום וחפץ\u003c/p>"}, {"id": "877", "n": 14, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-080 | סוג: קטע חסר | מקור: 02_קובץ_מאוחד/קובץ מאוחד - הקדמות - עותק 1.docx\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"והנה כל זה הוא רק ביחס האדם למשמעות מקום חפצים, אך ביחס לשימוש האדם בחפצים ובמקומות יוגדרו מקומות שימוש וחפצי ...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>עשרה טפחים גדר מה שגובה עשרה טפחים הוא מקום תפיסת רשות וכן גובה מחיצות וגובה להחשיב מקום להיות נפרד מרשות שסביבו ועוד כאלה הוא משום ששימוש של אדם בקרקע הוא עד גובה י' והיינו שעד י' טפחים נחשיב את שימוש האדם כחלק משימושו בקרקע ואפילו שיתכן שימוש גם מעל י' טפחים לא יחשב זה כשימוש בקרקע אלא כשימוש באוויר וכיון שאין הגדרת רשות אלא בקרקע לא תחשב הרשות אלא עד עשרה טפחים וממילא אם נרצה להפריד רשויות אין לנו אלא להפריד את הקרקע שלהם ובזה יספיק מחיצה י' טפחים ועל כן מקום עשרה טפחים יחשב כמקום נפרד מסביבותיו ארבע אמות גדר מה שמקום שביתת אדם הוא ד' אמות וכן העברה היא ד' אמות וכן שיעור תל המתלקט עשרה הוא בארבע אמות הוא משום ששיעור מקומו של אדם הוא ארבע אמות ומה שהוא שיעור מקומו של אדם מצאנו מחלוקת אם הוא משום שעצם מקום אדם המונח הוא בד' אמות או ששיעור שימוש אדם בחפץ הוא במקום ד' אמות ואיך שלא יהיה הוא גדר באדם וכיון שאין משמעות שימוש בחפץ אלא ביחס לשימוש אדם זה יהיה גם גדר מקום חפץ וממילא יהיה שיעור מקום שימוש אחד של מקום ד'\u003c/p>"}, {"id": "878", "n": 15, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-081 | סוג: חיבור עצמאי | מקור: קבצים ערוכים להטמעה / ביאורי רש\"י (פרק א חלק ו' במסמך הבדיקה)\u003c/p>\u003cp>כותרת מוצעת בסגנון הכותרות שבקובץ: ביאורי רש\"י למסכת שבת - רשויות, הנחה, כרמלית, מקומות וחפץ (אותיות 1-11, שבת ג.-ח.)\u003c/p>\u003cp>חלק ראשון של הלקסיקון: ביאורי רש\"י בדפי היסוד של גדרי הרשויות וההנחה. מקום השילוב: כנספח לדיון בחילוקי הרשויות.\u003c/p>\u003cp>הצעת קטע קישור בפתיחת הקטע: ולביאור הסוגיות יסייעו הביאורים הבאים בדברי רש\"י:\u003c/p>\u003cp>נוסח הקטע בשלימותו:\u003c/p>\u003cp>1. שימוש רשות היחיד ורשות הרבים (שבת ג.)\u003c/p>\u003cp>\\&gt; רש\"י (שבת ג.): *\"בעי אביי. השתא דחזינן דלאו בתר גופו שדינן לה לענין איחיובי מדאורייתא אלמא איפלוג רשותא מי אחמור עלה רבנן למיהוי כרמלית דהיכא דהושיט ידו מלאה לרשות אחרת לא יחזירנה אצלו ותהא כך פשוטה עד שתחשך דכיון דלאו בתר גופו גרירא נעשית לה רשות אחרת מדרבנן דגזור רשות מדבריהם לשבת שאסור להכניס ולהוציא ממנו לרה''י ולרה''ר ושמו כרמלית כדתניא בפרקין (דף ו.) ד' רשויות לשבת כרמלית לשון יערו וכרמלו שאינו לא הילוך תמיד לרבים ולא תשמיש רה''י.\"\u003c/p>\u003cp>ביאור: מבואר שגדר רשות הרבים הוא רשות להילוך תמידי; גדר רשות היחיד הוא רשות לתשמיש.\u003c/p>\u003cp>1. דמה שכתב שפתוחין בתים הרבה לחצר ואוסרים בני בתים זה על זה -- היינו אחר תקנת עירוב, וכמו שכתב בהמשך שאין יכולים להוציא מן הבתים בלא עירוב.\u003c/p>\u003cp>2. גדר הנחה (שבת ד.)\u003c/p>\u003cp>\\&gt; רש\"י (שבת ד.): *\"קלוטה. החפץ הואיל ונקלט באוירה של רשות הרבים כמי שהונחה בתוכו הוא ואע''ג דלא נח.\"\u003c/p>\u003cp>ביאור: משמע שגדר הנחה הוא בתוך הרשות, לעומת דבר שלא מונח שאינו בתוך הרשות. אך אם הוא באוויר הרשות נחשב קלוט, ונחשב שהוא בתוך הרשות ואפילו שלא נח, שזה חיסרון בקביעות מקום, היינו, שאין נחשב דבר שלא נח לקרות את מקום שנמצא בו כמקומו, שיחשב שנמצא בתוך הרשות. אך בקלוטה נחשב שהוא ברשות גם בלי מקום, וכיון שהוא ברשות ממילא יש להחשיב את מקומו שעתה הוא נמצא בו. וזה בזורק, אך במעביר יש באחיזתו להגדיר שאין זה מקומו, ואף שהוא ברשות אינו נחשב שהרשות מקומו.\u003c/p>\u003cp>2. ומעתה מבאר סיבת איסור חצרות: מפני שהבית רשות מיוחדת לו וחצר רשות חברו מושלת בה. והיינו שאין ביאור זה גדר אחר שתקנו דיני רשויות, אלא עיקר מה דאיתא לחילוק רשויות בין בית לחצר: שהבית רשות מיוחדת לו (היינו שהיא מיועדת לשימושו לבד), וחצר רשות חברו מושלת עליה (היינו חצר המקום עצמו רשות חברו מושל בה, היינו בית חברו, שהיא משועבדת לבית חברו). וגדר \"לו ולחברו\" היינו ביחס למה שהיא מיוחדת, ואין חיסרון בעצם מה שיש לחברו גם רשות בחצר (דאין חיסרון בדר בלא בית), אלא במה שביתו מושל ברשותו; והיינו דכיון שביתם מושל בחצר, הרי שיש בחצר גדר שאף בשימוש דתוכה הרי היא משמשת את הבית, היינו רשות הבית. וע\"כ יהיה הבדל הגדר בין רשות ביתו לרשות חצרו משמעותי, שאף היא רשות הבית אך אינה מיוחדת; וברשות הבית אין כוונתנו בדיני רשויות שאחר תקנה, אלא במשמעות שימוש בית שיש בחצר, דאחידות השימוש והבדל המיוחדות שיש ביניהם מחלקם, וזהו ביחס לאדם המשתמש שביתו מיוחד לו וחצרו אינה.\u003c/p>\u003cp>3. משמעות הנחה בקרקע ו\"כמאן דמליא\" (שבת ד.)\u003c/p>\u003cp>\\&gt; רש\"י (שבת ד.): *\"כמאן דמלי. דבר סתום מכל צד הוי כמלא חפצים עד גגו דאין אוירו חשיב אויר הלכך כל הנזרק לתוכו הוי כמונח.\"\u003c/p>\u003cp>ביאור: שעיקר חשיבות הנחה בקרקע הוא בהחשבת המקום שבו מונח החפץ כמקום של החפץ, וממילא זה גדר בחשיבות חפץ שיש לו מקום; אך באוויר, כיון שאין לו סוף, אין בזה גדר בחשיבות חפץ כיון שאינו תופס מקום אחרים וזה כמו הפקר. אך במקום סתום, כיון שיש גבול קיבול חפצים, נחשב כל חלל מקום שיש בו חשוב, ויש חשיבות בחפץ גם אם אינו מונח משום שעתה תופס מקום.\u003c/p>\u003cp>3. אבל אחר תקנת עירוב אין חילוקם מוגדר באדם אלא ברשות עצמה, וע\"כ כתב שהוא כמוציא מרשות לרשות.\u003c/p>\u003cp>ומה שנקט רש\"י גדר בבעל הבית המשתמש ולא בכל מי שמוציא, הוא משום שלפני תקנת עירוב באמת אין משמעות רק לבעל הבית, אלא שאחר שתקנו חילוק רשויות אין זה גדר במשתמש לבד (חוץ מביטול רשות) אלא זה גדר ברשות.\u003c/p>\u003cp>ומה שכתב דהוי מוציא מרשות לרשות -- היינו דווקא כיון שהבית מושל על החצר, ולא סתם חברו שמושל שזה אינו עניין לרשות; והיינו שאם היינו מתייחסים לחצר לבדה בלי מה שמשמשת את הבית, הרי שיש כאן שימוש מעורב של כמה אנשים, ודמיא למשתמשים בבית אחד ולדרים בלא בתים שאינם אוסרים, וכמו בשיירא, ולא היה בהוצאה דאחר מבית לחצר יותר ממשמעות שמוציא מרשות אלו לרשות אלו ושנתבאר שאינה אסורה, וכמו מקרפף לקרפף דתרי.\u003c/p>\u003cp>4. גדר מעשה הוצאה בשתי הרשויות (שבת ה:)\u003c/p>\u003cp>\\&gt; רש\"י (שבת ה:): *\"היכא אשכחן כה''ג. דמפסקא רשותא אחריתי מיחייב דילמא לא חייב' רחמנא אלא במוציא מרה''י לר''ה בהדיא.\"\u003c/p>\u003cp>ביאור: והיינו, שאף שלגבי המעשה הוי מעשה אחד, ויש לנו לצרף את שני המקרים, מה שהיה מונח ברשות זו ועתה מונח ברשות אחרת כחלק ממעשה שלו, וכן דכיון שלא נח בכרמלית אין זה חשוב שהיה לחפץ מקום שם, אלא כיון שחלק מהמעשה שלו הוא לא רק גדר בהעברת חפץ אלא במניעת הגדרה למקום חפץ, והיינו, שלהגדיר מעשה שלו כהוצאה צריך לחבר את כל המעשה לאחד, ומי אמר שמה שמונע מהחפץ לנוח אינו מפסיק מעשה שלו, שאין זה חלק מההוצאה; וכן שזה מעשה בגדרי מקום, היינו, שאין זה מקום חפץ, יש לומר שזה הפסק בעצם המעשה.\u003c/p>\u003cp>5. סיבת גזירת כרמלית (שבת ו.)\u003c/p>\u003cp>\\&gt; רש\"י (שבת ו.): *\"אינן לא כרשות היחיד. משום דדמיא לרה''ר דאין להם מחיצות: ולא כרה''ר. דאינן דומין לדגלי מדבר דלאו להילוכא דרבים עבידי: אין נושאין ונותנין בתוכן. כלומר אין מטלטלין בהן אלא בתוך ד' משום דדומין לר''ה וגזרו בהן רבנן אטו ר''ה.\"\u003c/p>\u003cp>ביאור: עיין לעיל, ושינה בלשונו שלא כתב שאינו תשמיש רשות היחיד, והיינו שגדר תשמיש רשות היחיד הוא במקום עם מחיצות; אלא ששם דיבר מגדר כרמלית מה שאינה חשובה רשות, וכאן ביאר מה סיבת הגזירה להגדירה כרשות לגבי הוצאה מרשות הרבים והיחיד וכו'. וזה משום שכיון שאינה דומה לאחת מאלו -- היינו, שהמוציא מרשות היחיד לה יבחין שאין לה מחיצות ויאמר שמותר להוציא מרשות היחיד לרשות הרבים כיון שיש לו לתלות זאת במחיצות; והמוציא מרשות הרבים יבחין שאינה משמשת לרשות הרבים ויאמר שמותר להכניס מרה\"ר לרה\"י כיון שיש לו לתלות בתשמיש. אך מה שאין מטלטלין בה ארבע אמות הוא משום רה\"ר במה שאין לרשות הרבים מחיצות. ואמנם ברשות הרבים הגדר הוא העברה, אך בכרמלית גדר האיסור הוא הוצאה, כיון שנחשב מקום שמונח בו החפץ מקום נפרד, משא\"כ ברשות הרבים (ועיין ב\"ב ר' יוסי וכו'), וע\"כ נכתב \"נושאין ונותנין\", אבל לא איירי מדין העברה, וע\"כ לא כתב דינה ברה\"ר.\u003c/p>\u003cp>6. חילוק רשויות שבת (שבת ו.)\u003c/p>\u003cp>\\&gt; רש\"י (שבת ו.): *\"חצר של רבים. שפתוחין לחצר בתים רבים וחצר פתוחה לרה''ר ובני הבתים יוצאים דרך החצר לרה''ר: ומבואות שאינן מפולשין. שראשו אחד סתום וחצרות פתוחין לו ובני החצרות יוצאין דרך מבוי לרה''ר: עירבו. כל הבתים של חצר יחד בפת וכן לענין המבוי אם עירבו החצרות הפתוחות לו ביחד: מותרים. להכניס ולהוציא מן הבתים לחצר וכן מן החצרות למבוי: לא עירבו אסורין. מפני שהבית מיוחדת לבעליה והחצר רשות לכולן ונמצא מוציא מרשות לרשות אע''פ ששתיהן רה''י לעשות סייג לתורה להרחיק שלא יוציא מרה''י לרה''ר והך מילתא לאו מחילוק ד' רשויות היא דבין עירבו בין לא עירבו רה''י היא והמוציא מתוכו לרה''ר חייב.\"\u003c/p>\u003cp>ביאור: וסיים שאין זה מחילוק רשויות, והיינו שכרמלית היא מקום נפרד אלא שאינו רשות וממילא חשיב הוצאה ממקום למקום והחשיבוהו לרשות; אבל אלו רשות היחיד הם, ואין הוצאה מאחד לשני נחשבת הוצאה ממקום למקום, ואין איסור העברה בהם.\u003c/p>\u003cp>וברישא כתב מה נחשב חצר ומבוי מבחינת המבנה, והיינו מה שפתוחין, וכן כתב מה משמעות זה הפתח, והיינו שיוצאים ממנו, וזה תנאים בצורת המקומות. אך גדר חילוק הרשות הוא במה שהבית מיוחדת לבעליה והחצר רשות לכולן (היינו הבתים), שזה סיבת מה שהחשיבו המקומות לנפרדים. ומה שהחצר רשות כולן תלוי בפתוחין כדלעיל, ולא כתב רשות מיוחדת משום שאין זה גדר רשות באותו מובן כמו החצר, שהבית הוא רשות לתשמיש אדם, והחצר היא רשות לתשמיש בתים (ולא תיאסר בבעלים רבים).\u003c/p>\u003cp>וזה גדר ההבדל בין בית לחצר שהבית מיוחד והחצר רשות לכל. אבל כל זה הוא רק בסיבת הגזירה; אבל גדר הגזירה, ומה שהחשיבום רשויות נפרדות לאסור הוצאה, הוא גדר שכתב בעירובין (יב:) שהבית רשות מיוחדת לו והחצר רשות שרשות חברו מושלת בה. וסיבת מה שכתב זה אבעלים משום שאחר שיש לבית גדר רשות, אין לאסור להוציא לחצר שזה רשות שלו וזה רשות שלו, וע\"כ כתב שהחצר אינה רשותו אלא רשות הבית, ורשות זו חלוקה משום שרשות חברו מושלת בה. וזה כמו גדר קודם הגזירה לגבי גדרי רשויות, וכן לגבי עירוב שכתב שעירבו הבתים ולא האנשים, כי זה גדר עירוב ביחס למצב קודם הגזירה שעתה אין לחצר גדר רשות.\u003c/p>\u003cp>7. גדר מקום כרמלית והנחה (שבת ז.)\u003c/p>\u003cp>\\&gt; רש\"י (שבת ז.): *\"דעד י' הוי כרמלית. אויר של בקעה או של ים או של קרפף יתר על בית סאתים תופס את שמו עד י' אבל למעלה מי' אין שם כרמלית עליו בדבר שאינו מסויים כגון פני לבינה או פני כותל או קלט מן האויר למעלה מי' מותר להוציא לכתחילה משם לרה''י ולרה''ר דאין שם כרמלית עליו כי היכי דאויר למעלה מי' ברה''ר לאו רה''ר הוא כדתנן לקמן למעלה מי' כזורק באויר גבי כרמלית נמי לאו כרמלית הוא ובדבר מסוים כגון ראש עמוד וגב לבינה ליכא לאוקמיה דאי אית ביה ארבע פשיטא דלמעלה מעשרה לא הוי כרמלית דהא אפילו עמוד ברשות הרבים רשות היחיד הוא ואי דלית ביה ארבע ולמטה מעשרה מי הוי כרמלית הא קאמר אין כרמלית פחותה מארבע ואי בדקאי בכרמלית וכיון דלית ביה ד' הוי שם הכרמלית עליו אם כן מצינו חומר בכרמלית מרשות הרבים דאילו ברשות הרבים כי האי גוונא מקום פטור הוא ובטל ומותר לרשות הרבים ולרשות היחיד ואנן אמרינן בשמעתין דהאי תופסת עד י' מקולי רשות הרבים הוא הלכך לא מיתוקמא אלא באוירא.\"\u003c/p>\u003cp>ביאור: עיין תוספות. ונראה ביאורו: דהא חזינן דכל שגובה שלושה ברשות הרבים הוי כרמלית, והיה לומר דכמו תל עשרה ברה\"ר הוי רשות היחיד וכן הוי מחיצה, כך מחיצת כרמלית תהיה בשלושה ושלא ייחשב מקום שסביבו מחיצות שלושה כרמלית כיון שיש לו מחיצות. והיינו, שהרי אין בקעה כמו ים שיש בקרקע שלה עצמה הבדל שנאמר שגזרו על מקום מים, והיה לומר שזה דווקא אם אין לו מחיצות, אבל בשלושה כבר נחשב מחיצות לחלק, ויהיה אסור להוציא מבקעה לבקעה, ועל זה אמר דלא הוי אלא בעשרה. וזה הביאו ראיה שלא זו בלבד שאין דין מחיצת עשרה לחילוק, אלא יותר מזה שאפילו מקום שהוא פחות מבית סאתיים והוקף לדירה, כיון שאין לו גובה עשרה נחשב כרמלית, ובהכרח שאין דין מחיצות בכרמלית כלל.\u003c/p>\u003cp>וכתב דגדר אוויר, היינו, מקום שאינו מסוים; והיינו דמלבד גדר מקום חשוב שהוא בארבעה, ישנו עוד גדר אפילו בפחות מארבעה, והוא מה שהמקום מסוים, וכוונתו שאפשר להניח עליו. וזה הביא ראיה מרשות הרבים, מזה שמקום כזה חלוק לעצמו אפילו בפחות מעשרה, והיינו שכל שאפשר להניח עליו אפילו משהו כבר נחשב מקום, ואינו נחשב אוויר, והוא חלוק מאוויר. ובבאמת שזה מוכרח, שהרי מה דעמוד תשעה חשיב רה\"ר הוא גדר חיובי שמשמש עם קרקע הרשות, וע\"כ אינו חולק מקום לעצמו וכמו פני כותל.\u003c/p>\u003cp>וע\"פ זה נראה לבאר דברי רש\"י לגבי דבילה שמינה דלא ממעט מארבעה, והיינו שגדר ההנחה הוא בפני הכותל, ובאמת זה חשיב מקום אחר מקרקע שתחת הדבילה ואיכא לארבעה. אבל כיון שהעברה ארבע אמות היא באוויר רשות הרבים ולא בקרקע, והיינו שעוקר ממקום זה ומניח במקום אחר, ובאמת כל חלק וחלק מקרקע רשות הרבים חשיב כמקום אחר, אלא דכיון שארבע אמות חשיב אוויר תשמיש אחד וגדר הוצאה הוא בגדרי תשמיש, לא נחשב הוצאה, היינו, עקירה מהמקום בפחות. וכיון שהעברה זו אחר שתעשה לא תחשב לגבי המקום, אין הוא מניח במקום אחר. וע\"ז אמרו שהיא בטילה, והיינו שאין גדר בחפץ עצמו שיעבור ארבע אמות, אלא הארבע אמות הם גדר במקום חפץ ולעניין גדר העברה. משא\"כ בחוליה ששם גם המקום עצמו הרי אינו, ובהכרח שגדר המקום הוא בחפץ, וע\"כ יש להסתפק.\u003c/p>\u003cp>ואיך שלא יהיה, מצאנו שיש כאן שלושה גדרים ברשות: קרקע הרשות, ואוויר קרקע הרשות, ואוויר הנספח לקרקע; ואם יהיה לו קרקע משהו לא יהיה נספח, אלא אם גם קרקע זו תסופח לרשות, כמו בעמוד תשעה. אך ברשות היחיד אין אוויר הרשות רק מחמת קרקע אלא מחמת הרשות עצמה, וקרקע כל שהוא תחשב לרשות היחיד; ולעניין חפץ מונח ברשות -- היינו בקרקע ולא באווירה. ולמאן דאמר קלוטה כמי שהונחה זהו גדר שלילי, ומקום מקורה גם אווירה נחשב כקרקע.\u003c/p>\u003cp>8. גדר כרמלית (שבת ז.)\u003c/p>\u003cp>\\&gt; רש\"י (שבת ז.): *\"מקולי רה''י ורה''ר. רב דימי אשמעינן מקולי רה''י כי היכי דרשות היחיד ליתיה פחות מרחב ד' והמכניס מרה''ר עליו פטור כרמלית נמי לא הוי ומותר לכתחלה להכניס מרשות הרבים ומרה''י עליו ורב ששת אשמעינן דמקולי רה''ר נמי אקילו עלה דאינה תופסת באויר למעלה מי' כרה''י אלא למטה מי' כתורת רה''ר.\"\u003c/p>\u003cp>ביאור: ומלשונו משמע דגדר כרמלית הוא בכל מה שאינו רשות היחיד ורשות הרבים. וכן משמע שמה ששיעורו ד' טפחים ולא ט\"ז, אין זה מחומרי דרשות היחיד, וכמש\"כ במק\"א, שאין זה גדר ברשות הרבים, אלא בשימוש הראוי להגדיר רשות הרבים.\u003c/p>\u003cp>9. גדר ד' טפחים (שבת ז:)\u003c/p>\u003cp>\\&gt; רש\"י (שבת ז:): *\"גבוהה י'. כלומר אפי' גבוהה י' אם אינה רחבה ו' באמצעיתה חייב דאכתי חפץ בעלמא הוא ואינה רשות לעצמה דלא הוי רשות דאוריי' אלא גבוהה י' ורחבה ד' על ד' כדאמרי' בעירובין (דף נא.) דכל שיעורין דשבת צריך הן ואלכסונן ודבר עגול כי מרבעת לה מתוכו ומפקע עיגול שסביב הריבוע לא משכחת ביה ד' מרובעים אי לא הוי עיגולו קרוב לששה כדאמרינן גבי סוכה העשויה ככבשן (סוכה פ''א דף ז:) דעל כרחיך צריך שתמצא בתוכו אלכסון של ד' על ד' וכל טפח בריבועו טפח ותרי חומשי באלכסונו הרי ה' טפחים וג' חומשין ואביי לא דק ולחומרא הוא דלא דק ולהפרישו מאיסור שבת אף ע''ג דיש כאן אלכסון באינה רחבה ששה מחייב ליה מדרבנן עד דאיכא ששה אבל ודאי לענין קרבן לא מייתי אי הויא ה' טפחים וג' חומשין דהוי כזורק רשות: רחבה ו' פטור. דהוי רשות לעצמה ואנן ממשכן גמרינן שהיו זורקין מחטיהן במלאכתן זה לזה ולא היו זורקין רשויות וא''ת בדלא גבוהה עשרה נמי רשות לעצמה היא דהא שמה כרמלית ההיא לאו מדאורייתא הוה רשות אלא מדרבנן ולא להקל על דברי תורה בא כגון זו שיפטר מחטאת.\"\u003c/p>\u003cp>ביאור: ומשמע שגדר ד' טפחים הוא גדר כללי ברשויות, שהרי לא ביאר כמו בתוספות, ולאו דווקא ברשות היחיד; והיינו שיש בד' טפחים גדר שמשמש להנחת חפצים, וגדר זה הוא בכל הכוורת ולא רק בקרקעיתה, והיינו שגם מחיצות שיש לה הם חלק מהרשות. וכן משמע שגדר ד' טפחים בכרמלית אין הוא גדר במקום אלא ברשות.\u003c/p>\u003cp>10. חילוק מקומות (שבת ח.)\u003c/p>\u003cp>\\&gt; רש\"י (שבת ח.): *\"וזרק. מתחלת ד' לסוף ד'.\"\u003c/p>\u003cp>ביאור: ומשמע שהיה לומר שהוא מקום נפרד, וזה יותר מפני כותל, ולא ניבעי לארבע אמות; וזה ביאר שאין זה מקום נפרד, והרי זה אפילו בד' טפחים, וזה אינו, שאין להגדיר ברשות הרבים מקומות נפרדים כלל, דזה היפך משמעות שימוש דרשות הרבים.\u003c/p>\u003cp>11. חפץ וכלי (שבת ח.)\u003c/p>\u003cp>\\&gt; רש\"י (שבת ח.): *\"פחות מכן. או בגובה או ברוחב מטלטלין וא''ת פחות מי' ורחבה ד' כרמלית היא לא גזור רבנן לבטולי מתורת כלים הואיל וכלי הוא.\"\u003c/p>\u003cp>ביאור: והיינו דמדאורייתא הוי כרמלית. וזה סיבת מה שלא פירש לעיל בכוורת כתוספות, שאחר שינוח ודאי נחשב ככרמלית מן התורה, ומה שמתחייב הוא משום שהוא חפץ עד שינוח. וזה גדר ההבדל בין חפץ לבין כלי, היינו שחפץ משמעותו דבר הניטל, וכלי משמעותו שימוש במקום.\u003c/p>"}, {"id": "879", "n": 16, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-082 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (30 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. הגדר המאוחד ברשויות ובמקום לדיורין - ארבעת השלבים ממחיצות לקרקע ועד דיורין לרשות\u003c/p>\u003cp>2. נקודת המחלוקת בהגדרת המקום לפמשנ\"ת - היקף שפיר וגדר המחלוקת בהגדרת הרשות בלבד\u003c/p>\u003cp>3. ביאור מה שאין הוצאה מרה\"י לרה\"י נכלל בגדר הנ\"ל\u003c/p>\u003cp>4. גדר תיקון יהושע ע\"פ הנ\"ל וביחס למעלות ומורדות\u003c/p>\u003cp>5. גדר שימוש הנ\"ל ביחס למקומות שאינם רה\"ר\u003c/p>\u003cp>6. גדר שימוש הרבים דבקיעה לפי הנ\"ל ובספיקא דתל\u003c/p>\u003cp>7. ביאור הגדר המאוחד ברשויות ובמקום - סיכום ארבעת השלבים ממחיצות לקרקע ועד דיורין לרשות\u003c/p>\u003cp>8. בירור נקודת המחלוקת בהגדרת המקום - יסוד שההיקף שפיר וגדר המחלוקת הוא בהגדרת הרשות בלבד\u003c/p>\u003cp>9. מהות הרשויות עצמם לאופיים השימושי והמבנה הממשי.\u003c/p>\u003cp>10. גדר הנ\"ל ביחס לחפץ במשמעות נפרדת ממשמעותו לאדם\u003c/p>\u003cp>11. חילוק גדר תקנת חכמים ברשויות מדאוריתא\u003c/p>\u003cp>12. תוספת ביאור בגדר הכנסה והוצאה הנ\"ל\u003c/p>\u003cp>13. שתי מחיצות לר' יהודה ברה\"ר - תירוץ תוספות ומחיצות שאינן מתירות ומונעות רה\"ר\u003c/p>\u003cp>14. ביאור גדר תיקוני מבוי ושם מפולש וגדר לחי כנובעים מתקנת הכשר מבוי שהיא בהגדרת חללו\u003c/p>\u003cp>15. בירור גדר הנ\"ל ותלותו בדין הנחלה שניתנה ביד יהושע\u003c/p>\u003cp>16. הצ\"ב לפמשנ\"ת במה דילפינן לה מדגלי מדבר ובגדרים המסתעפים מהנ\"ל\u003c/p>\u003cp>17. גדר תשמיש במקום מסויים וגדר הילוך השימוש ההמשכי\u003c/p>\u003cp>18. דין ד' אמות ברה\"ר הוא מעצם גדרי העברה\u003c/p>\u003cp>19. העמדת הושטה כמעשה הוצאה מחודש ולא כהעברה גרידא\u003c/p>\u003cp>20. בירור מה שנשתנה הוצאה מרה\"י לרה\"י מהעברת ד' אמות ברה\"ר - העלאת השאלה במושיט מרה\"י לרה\"י\u003c/p>\u003cp>21. יישום החילוק להוצאה הכנסה ומושיט כשני שינויים מצטרפים - יסוד סברת מה לי הוצאה מה לי הכנסה\u003c/p>\u003cp>22. פיסקה:  העמדת הושטה כמעשה הוצאה מחודש ולא כהעברה גרידא\u003c/p>\u003cp>23. חילוק גדר תקנת חכמים ברשויות מדאורייתא - תקנת חכמים ביחס לחלל הרשות ולא רק לקרקעה\u003c/p>\u003cp>24. גדר תיקון יהושע ע\"פ הנ\"ל וביחס למעלות ומורדות - כח יהושע להגדיר שימוש נובע מכח ההנחלה\u003c/p>\u003cp>25. גדר שימוש הרבים לפי הנ\"ל - שימוש הרבים אינו גדר חיובי אלא שלילי שאינו סותר את היות המקום לרבים\u003c/p>\u003cp>26. בגדר דריסת הרבים לפמשנ\"ת - עמידה לכתף חשובה לשימוש הרבים כמו שהילוך חשוב\u003c/p>\u003cp>27. גדר שימוש הנ\"ל ביחס למקומות שאינם רה\"ר - עמוד תשעה ומקום שאינו נפרד ביחס לשימוש\u003c/p>\u003cp>28. גדרים נוספים בהתפשטות שימוש הרבים - חסרון בשימוש הבא מכח הדחק לעומת שימוש הבא מעצמו\u003c/p>\u003cp>29. גדר שימוש הרבים דבקיעה לפי הנ\"ל ובספיקא דתל - חילוק בין מחייב שימוש למחייב חיבור המקום בלבד\u003c/p>\u003cp>30. תנאי קרקע - יסוד להנחת דברים ומשמעות מקום לדבר בקיום ובשייכות לשאר מקומות\u003c/p>"}, {"id": "880", "n": 17, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-083 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (24 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. שלושה גדרים במקום - חלל מקום ורשות ומה שנחשב מקום ביחס לחוץ לו ולעצמו\u003c/p>\u003cp>2. גדר כרמלית - אין בה איכות רה\"י ולא איכות רה\"ר וע\"כ אין מוציא אליה או ממנה חשוב כמוציא\u003c/p>\u003cp>3. דין העברה ד' אמות - העברה ד' אמות ברה\"ר צריכה עקירה והנחה ושיעור מגדר מעשה עצמו\u003c/p>\u003cp>4. בירור גדר הילוך ותשמיש בדעת רש\"י כדין שימוש ולא כתנועה\u003c/p>\u003cp>5. (253) - איכות רשות היחיד בהכלת החפץ ככנוס והיות כלל מקומותיה מקום אחד (מקור - הוצאה - 7 - 828)\u003c/p>\u003cp>6. (273) - סדר ההשתלשלות האונטולוגי של המרחב – ממקום וקרקע ועד מחיצה וגובה (מקור - רשויות - 7 - 782)\u003c/p>\u003cp>7. (285) - ביאור שגובה עשרה אינו חלל מעוקב אלא גובה שטח (מקור - רשויות - 7 - 712)\u003c/p>\u003cp>8. (286) - מחיצות התורה כהגדרת קרקע לעומת מחיצות דרבנן כהיקף חלל (מקור - רשויות - 7 - 745)\u003c/p>\u003cp>9. (287) - צורת סיום המקום בריבוע – שתי מחיצות לאורך וד' מחיצות לאורך ורוחב (מקור - רשויות - 7 - 705)\u003c/p>\u003cp>10. (304) - חילוק מושגי בין פירצה במחיצה לבין ביטול מחיצה ע\"י כח חיצוני (מקור - רשויות - 7 - 695)\u003c/p>\u003cp>11. (317) - איכות רשות הרבים בפירוק מקום החפץ – חלוקת הקרקע למקומות נפרדים (מקור - רשויות - 7 - 658)\u003c/p>\u003cp>12. (318) - מעמד החפץ ברה\"ר כמוצא – חוסר איחוד המקומות לעומת רשות היחיד (מקור - הוצאה - 7 - 829)\u003c/p>\u003cp>13. (333) - שתי מחיצות לר' יהודה ברה\"ר - תירוץ תוספות ומחיצות שאינן מתירות ומונעות רה\"ר\u003c/p>\u003cp>14. (338) - ההבחנה המושגית בין הילוך הרבים בקרקע לבין תשמיש הרבים ככיתוף (מקור - רשויות - 7 - 632)\u003c/p>\u003cp>15. איכות רשות היחיד בהכלת החפץ ככנוס והיות כלל מקומותיה מקום אחד (מקור - הוצאה - 7 - 828)\u003c/p>\u003cp>16. סדר ההשתלשלות האונטולוגי של המרחב – ממקום וקרקע ועד מחיצה וגובה (מקור - רשויות - 7 - 782)\u003c/p>\u003cp>17. ביאור שגובה עשרה אינו חלל מעוקב אלא גובה שטח (מקור - רשויות - 7 - 712)\u003c/p>\u003cp>18. מחיצות התורה כהגדרת קרקע לעומת מחיצות דרבנן כהיקף חלל (מקור - רשויות - 7 - 745)\u003c/p>\u003cp>19. צורת סיום המקום בריבוע – שתי מחיצות לאורך וד' מחיצות לאורך ורוחב (מקור - רשויות - 7 - 705)\u003c/p>\u003cp>20. חילוק מושגי בין פירצה במחיצה לבין ביטול מחיצה ע\"י כח חיצוני (מקור - רשויות - 7 - 695)\u003c/p>\u003cp>21. איכות רשות הרבים בפירוק מקום החפץ – חלוקת הקרקע למקומות נפרדים (מקור - רשויות - 7 - 658)\u003c/p>\u003cp>22. מעמד החפץ ברה\"ר כמוצא – חוסר איחוד המקומות לעומת רשות היחיד (מקור - הוצאה - 7 - 829)\u003c/p>\u003cp>23. ההבחנה המושגית בין הילוך הרבים בקרקע לבין תשמיש הרבים ככיתוף (מקור - רשויות - 7 - 632)\u003c/p>\u003cp>24. הגדר המאוחד ברשויות ובמקום לדיורין - ד' השלבים ממחיצות לקרקע ועד דיורין לרשות\u003c/p>"}, {"id": "106", "n": 18, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-186 | חומרה: בינונית | קטגוריה: מעבר מסיווג הרשויות לדיניהן. לאחר ש־P00607 הציגה את ארבע הרשויות ואת מאפייני המקום והשימוש בכל אחת מהן, פסקה זו עוברת מן הסיווג אל תוצאותיו בדין הוצאה מרשות לרשות. כדאי לבדוק אם המעבר מן ההבחנה בין מקום אחיד, מקום שאינו אחיד ומקום שאינו מקום כלל אל הדינים המעשיים ברור לקורא, והאם הביטוי „כדלעיל” מפנה במדויק לדיון שבו הוגדר מקום החפץ. יש להקפיד במיוחד שההבחנה בין כרמלית לבין מקום פטור תוצג כמעבר בין שתי קטגוריות שונות ולא כיישום אחיד של אותה נוסחה. בסיום הפסקה יש לוודא שהכותרת P00609 „נושאי דיני הוצאה ברשויות” נובעת ממנה באופן טבעי. ההופעה ב־P03243 נשארת בגוף הספר; ההערה הקיימת S-20261108-043 שם עוסקת בהבחנה ההלכתית בין דאורייתא, דרבנן ומקום פטור, ולא בעצם ההטמעה של ההסבר שבהקדמה.\u003c/p>"}, {"id": "881", "n": 19, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-084 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/מלאכת שבת רשויות עירובי חצירות תחומין.pdf / 08_הקדמות_והצעות_נוסח/תוכניות להטמעת קטעים.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"דיני הוצאה ורשויות מן התורה ותקנות חז\"ל מתחלקים לכמה נושאים הנצרכים ביאור וגדר. א. מהות הרשויות עצמם לאופיים ה...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>B1. שני תפקידים נפרדים של מחיצה (הגדרת קרקע מול הגדרת מקום-שימוש)\u003c/p>\u003cp>מיקום הכנסה מוצע: להוסיף בסוף \"כותרת 6 מספר 13 - גדרי מחיצה\": אחרי כותרת 7 מספר 194 (המסתיימת \"...ומעתה נאמר שההגדרה של המחיצות של רשות היחיד הם גורמי היותו מקום מוגדר ליחיד.\") ולפני \"כותרת 6 מספר 14 - דיני מחיצה\" (רשימת אין מחיצה אלא לד\"ט, לבוד וכו').\u003c/p>\u003cp>מקור: חלק ג', כותרת 3 מס' 158\u003c/p>"}, {"id": "882", "n": 20, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-085 | סוג: קטע חסר | מקור: 08_הקדמות_והצעות_נוסח/הצעות נוסח להקדמה - נושא הרשויות.docx\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"וגדר ההבדל בין רשות דאורייתא (היינו, הדינים שנאמרו בתורה שביחס להם יש להיות דין רשות), ובין רשות דרבנן. כי מן ...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>גם גדר רשויות נובע ממשמעות הנ\"ל\u003c/p>\u003cp>הנובע מזה דגם גדר מקום יהיה ביחס לגדרי מקום חפץ\u003c/p>"}, {"id": "883", "n": 21, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-086 | סוג: קטע חסר | מקור: 04_רשויות/רשויות.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"וביאור חלוקה זו, כי משמעות רשות כמקום שימוש, היינו, שגדרי מקום הרגילים יגדירו מקום של דבר רק אם נמצא בו, ורק ב...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>סוגי רשות שימוש\u003c/p>\u003cp>סוגי השימוש יחלקו לשניים עיקריים והם שני רשויות שמן התורה\u003c/p>"}, {"id": "107", "n": 22, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-200 | חומרה: בינונית | קטגוריה: השתלבות הבחנה מושגית בהקדמה. P00630 הבחינה בין מקום כשלעצמו — יכולת להכיל דברים — לבין מקום של דבר — הימצאותו של דבר במקום. P00631 מוסיפה את התנאים לקבלת שם „רשות”: קרקע ולא אוויר, ורוחב ארבעה על ארבעה טפחים. כדאי לוודא שהמעבר מן הגדרת מקום אל תנאי שם רשות מפורש, ושברור מדוע תנאים אלו אינם מבטלים את הגדרת המקום הכללית אלא מוסיפים עליה רובד הלכתי. P00632 ממשיכה ומסבירה את דין הקרקע כבסיס להנחת דברים; יש לבדוק שהחלוקה בין שני התנאים שב־P00631 נשמרת גם בהמשך, ושסיום הפסקה מכין את הפירוט הבא ולא משאיר את רשימת התנאים כיחידה מנותקת. ההופעה המקבילה ב־P03271 נשארת בגוף הספר; הביקורת כאן מתייחסת רק לאופן שבו הגדרת הרשות משתלבת במבוא המושגי.\u003c/p>"}, {"id": "884", "n": 23, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-087 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/מלאכת שבת רשויות עירובי חצירות תחומין.pdf / 08_הקדמות_והצעות_נוסח/תוכניות להטמעת קטעים.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ותנאי הראשון שיהיה קרקע ולא אוויר, הוא שיהיה לו בסיס להנחת דברים. והיינו, שאף שאוויר שווה לקרקע לענין מה שיכול...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>A4. רשות כגדר בשימוש הקבוע (לא ארעי)\u003c/p>\u003cp>מיקום הכנסה מוצע: להוסיף בהמשך ישיר ליחידה A3 לעיל (באותו המיקום, אחריה), עדיין לפני כותרת 7 מספר 166 (\"רשות היחיד\"). מרחיב את אותה הנקודה מזווית נוספת: לא רק *מהם* תנאי הקרקע, אלא *לאיזה סוג שימוש* מיועדת ההגדרה.\u003c/p>"}, {"id": "108", "n": 24, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-191 | חומרה: בינונית | קטגוריה: סגירת הגדרה ומעבר ליחידת המשך. לאחר ש־P00647 הבחינה בין עצם משמעות הוצאה לבין היקף איסור התורה, פסקה זו מיישמת את מודל איכויות הרשות על כרמלית: אין בה את איכות האיחוד של רשות היחיד ואף לא את איכות ההפרדה של רשות הרבים. כדאי לוודא שהביטוי „ובזה יש לנו להגדיר” מקשר במפורש לשתי האיכויות שהוצגו קודם, ושברור לקורא מדוע הוצאה לכרמלית אינה מקבלת את שם מעשה ההוצאה האסור לפי המודל. סיום הפסקה צריך להוביל לכותרת P00649 „רשות ביחס לחפץ המונח בה”, שבה נפתח בירור ממוקד של יחס הרשות לחפץ. ההופעה המקבילה ב־P03327 נשארת בגוף הספר; הערת התוכן הקיימת שם אינה משנה את מוקד הביקורת על רצף ההקדמה.\u003c/p>"}, {"id": "109", "n": 25, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-192 | חומרה: בינונית | קטגוריה: הטמעת מפת הגדרים בהקדמה. יש לקרוא את P00656–P00658 כיחידה מושגית אחת: P00656 מציגה שלוש שכבות — קרקע, מקום ורשות; P00657 מפרטת לכל שכבה שני אופני הגדרה; ו־P00658 מאחדת אותן למהלך של ארבעה שלבים ומוסיפה את תפקיד הדיורין. כדאי לוודא שהמעבר מן החלוקה לשלושה מושגים אל ששת הגדרים שב־P00657 ברור ואינו יוצר רושם שמדובר ברשימה חדשה שאינה נובעת מן החלוקה. בפרט, יש להבחין בעקביות בין „קרקע נפרדת/אחידה”, „מקום נפרד/אחיד” ו„רשות נפרדת/אחידה”, ולוודא שסיכום ארבעת השלבים שב־P00658 אכן מסכם את החלוקה ולא מוסיף לפתע שלב חמישי של דיורין בלי להסביר את היחס בינו לבין ארבעת השלבים. סיום P00658 צריך להכין באופן טבעי את הכותרת P00659 „רשות היחיד”. ההופעה ב־P04423 נשארת בגוף הספר; הביקורת כאן עוסקת רק בהצגת מפת־היסוד בהקדמה.\u003c/p>"}, {"id": "885", "n": 26, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-088 | סוג: קטע חסר | מקור: 08_הקדמות_והצעות_נוסח/הצעות נוסח להקדמה - נושא הרשויות.docx / 08_הקדמות_והצעות_נוסח/תוכניות להטמעת קטעים.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"וגדרם המאוחד דרשות המקום בקרקע, שתהיה ראויה קרקע המקום לאחד את כל שימושיה, שיחשבו שימוש באותו המקום, וזה מוקדם...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>הערת עריכה: שים לב: כותרת 7 מס' 1298 המקורית ממשיכה מעבר לרשויות עצמן, עד \"ודיורין לרשות שיחשב הוצאה\" - משפט זה שייך כבר לתחום ה\"דיורין\" (חצירות/עירובין) ולא לגוף נושא הרשויות. הבאתי את הפסקה בשלמותה כלשונה (כנדרש), אך ראוי לשקול אם לעצור את הציטוט קודם למשפט זה, או להשאירו כרמז-גישור לפרקים הבאים.\u003c/p>\u003cp>A3. גדר \"מקום\" ושני התנאים בשם \"מקום רשות\"\u003c/p>"}, {"id": "110", "n": 27, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-189 | חומרה: בינונית | קטגוריה: הטמעת רצף הסבר בהקדמה. יש לקרוא את P00667–P00668 כיחידה אחת: P00667 מסיקה משני סוגי השימוש — תשמיש קבוע ומעבר — את ההבדל בין רשות היחיד לרשות הרבים; P00668 מיישמת את ההבחנה על הנחת חפץ ועל מעבר חפץ. כדאי לוודא שהפתיחה „ותראה” חוזרת בבירור לחלוקה שהוצגה ב־P00666, ושמובן כיצד ההבחנה בין שימוש תכליתי לשימוש אמצעי מגדירה גם את מקום החפץ. יש לבדוק שסיום P00668 מכין את הכותרת P00669 „המבנה הממשי של רשות היחיד”, ולא יוצר קפיצה מההגדרה הכללית לדיון ברשות היחיד בלבד. שתי הפסקאות נשמרות בהקדמה כחלק מן המפה המושגית; ההופעות ב־P03340–P03341 הן הרחבה בגוף הספר. ההערה מתייחסת לשילוב הרצף המוקדם בלבד.\u003c/p>"}, {"id": "886", "n": 28, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-089 | סוג: קטע חסר | מקור: 08_הקדמות_והצעות_נוסח/הצעות נוסח להקדמה - נושא הרשויות.docx\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ולאחד כל הגדרות אלה נאמר כי המושג עירוב למרות שהוא נגרם ע\"י שני חלקים שנתערבו הרי כל חלק מוגדר (ובמילה מוגדר ה...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>ותראה שכל תנאי שימצא אחד משלושה חלקים אלו הרי הוא בהכרח תנאי הנוגע בכולם, ויהיה גדר האחד שממנו יפרדו שאר תנאים היכולת בהגדרה עצמית לנצרך לו.\u003c/p>"}, {"id": "111", "n": 29, "a": "עורך – ביקורת ראשונית", "d": "2026-11-04", "h": "\u003cp>E-0006 | חומרה: נמוכה | קטגוריה: התאמה דקדוקית. \"אפשרות\" היא נקבה, ולכן לפי ההקשר יש לכתוב \"שתי אפשרויות קוטביות\". אותרו 7 מופעים של \"שני אפשרויות\" במסמך; יש לבדוק את כולם.\u003c/p>"}, {"id": "887", "n": 30, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-090 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/הקדמות וכללים - רשויות - הוצאה - עירובין - תחומין.docx\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ונצרכים אנו להגדיר את המשמעות של מקום שאין הוא רשות היחיד בגלל מחיצותיו, ולהבין את הכח שעומד ממול ההגדרה של רש...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>וכן הוא לכל רשויות שמן התורה, היינו, רשות הרבים, רשות היחיד ומקום פטור, שעיקר משמעות תנאי רשות היחיד הוא להיות המקום גדור לעצמו ומיוחד לשימוש לנמצאים בתוכו, ועיקר משמעות תנאי רשות הרבים היא להיות מקום מעבר הפרוץ והמיועד לשימוש הרבים, ורשות מקום פטור שגדרו בשלילת אלו, היינו, שאין מקומו ראוי להיות בו שימוש הרבים או היחיד.\u003c/p>\u003cp>ותמצא כי יהיו תנאי הרשות הנ\"ל חלוקים לשני סוגים, תנאים הנוגעים לצורת המקום הממשים (גשמית), ותנאים הנוגעים לדרך השימוש הנוכחי במקום. והנראה בפשטות שכח המערב והגורם למקום שלא להיות בו רשות היחיד הוא כח הנוגע לביטול תנאים הנ\"ל ומשמעותם שיהיה המקום ראוי להיות רשות שימוש ליחיד. ומעתה נאמר שגם גדר המונע בזה, היינו, מחיצות, הוא בכוחם להיות גורמי היות המקום מוגדר ליחיד.\u003c/p>\u003cp>דיני מחיצה\u003c/p>"}, {"id": "112", "n": 31, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-181 | חומרה: בינונית | קטגוריה: סגירת מהלך ומעבר לנושא הבא. פסקה זו היא מסקנת המהלך שב־P00766: מתוך הקושי בדין אתי רבים מתברר שיש משמעות עצמאית לצורת המקום שהמחיצות מגדירות, הקודמת לקיום הרשות עצמה. כדאי לוודא שהמעבר מן „ונראה מכאן לכאורה” שבפסקה הקודמת אל „ואחר העיון הוא מוכרח” מציג לקורא בבירור את שלב ההכרעה, ושמובן מה בדיוק הוכרח — עצם קדימת צורת המקום, ולא כל פרט מגדרי המחיצות. לאחר מכן מופיעה הכותרת P00768 על גובה עשרה טפחים; יש לבדוק אם היא נקראת כדוגמה/המשך של הגדרת צורת המקום או כיחידת דיון חדשה, ובהתאם להוסיף קישור קצר או להשאיר את הגבול ברור. ההופעה המקבילה ב־P03033 היא פיתוח בגוף הספר ונשארת במקומה; אין לקצר את ההצגה שבהקדמה בשל החזרה.\u003c/p>"}, {"id": "888", "n": 32, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-091 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/הקדמות וכללים - רשויות - הוצאה - עירובין - תחומין.docx / 08_הקדמות_והצעות_נוסח/תוכניות להטמעת קטעים.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ואחר העיון הוא מוכרח דהא צורת הרשות, ודאי קודמת לרשות, דאף אם ג' מחיצות דאוריתא, מי יגביל הרשות ברוח רביעית של...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>הערת עריכה: כותרת 7 מס' 696 (המובאת כאן כהקדמה למס' 697) עוסקת ב\"אתי רבים\" - מושג שכבר מוזכר ומוגדר בהקדמה (כותרת 7 מס' 219 הקיימת). הבאתי אותה במלואה כהקשר הכרחי להבנת מס' 697, אך אין בה תלות במחלוקת ראשונים - היא בירור עצמאי של המחבר.\u003c/p>"}, {"id": "113", "n": 33, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-182 | חומרה: בינונית | קטגוריה: רצף והעמקת ההגדרה בהקדמה. פסקה זו מוסיפה ביאור להבחנה שהוצגה ב־P00769 בין פני השטח לבין האוויר שאליו הם פונים: גובה עשרה אינו שיעור בחלל עצמו אלא בגובה המקום/במרחק מפני השטח, והחלל מוגדר כתוצאה מסדר שני. כדאי לוודא שהפתיחה „וביתר ביאור” אכן נסמכת על ההבחנה שבפסקה הקודמת, ושברור לקורא מהו היחס בין „גובה מקום”, „תפיסת גובה של שטח” ו„חלל”. יש להימנע ממצב שבו הפסקה חוזרת על P00769 בלי להציג בבירור את ההבחנה החדשה. בסופה יש לבדוק את המעבר לכותרת P00771, העוסקת בחילוק גדר מחיצות דאורייתא ודרבנן: האם ברור מדוע עוברים מהגדרת הגובה למעמד המחיצות, או שנדרש משפט קישור קצר. ההופעה ב־P03069 נשארת כפיתוח בגוף הספר; אין לקצר את ההצגה שבהקדמה בשל החזרה.\u003c/p>"}, {"id": "889", "n": 34, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-092 | סוג: חיבור עצמאי | מקור: קבצים ערוכים להטמעה / בגדר הלכה דלבוד (פרק א חלק א' במסמך הבדיקה)\u003c/p>\u003cp>כותרת מוצעת בסגנון הכותרות שבקובץ: בגדר הלכה דלבוד - ארבעת גדרי לבוד, יסוד הביטול ותרי לבוד\u003c/p>\u003cp>חיבור עצמאי בגדרי הלכה דלבוד, שהוכן להטמעה ולא הוטמע. מקום השילוב הטבעי: סמוך לדיון בדין לבוד שבחילוקי הרשויות (\"לבוד - הל\"מ. והוא דין על רווח הגדול שלא יחשב כרווח\"), כהרחבה וביאור עומק לדין המונח במילון המחיצות.\u003c/p>\u003cp>הצעת קטע קישור בפתיחת הקטע: ובביאור עומק דין לבוד האמור, נראה לחלקו לארבעה גדרים:\u003c/p>\u003cp>נוסח הקטע בשלימותו:\u003c/p>\u003cp>בגדר הלכה דלבוד: ארבעת גדרי לבוד, יסוד הביטול ותרי לבוד\u003c/p>\u003cp>הלכה למשה מסיני היא דכל פחות משלושה כלבוד דמי. ושם לבוד הוא דין כולל להרבה דינים המחולקים בגדרם ובדין היוצא מהם, ומצאנו כמה סוגים עיקריים בזה, והם:\u003c/p>\u003cp>1. לבוד המבטל: היינו במקום שאין צריך רק שלא יהיה משמעות נפרדת לדבר מסביבותיו, וכגון בגבשושית ברשות הרבים, ובשימוש בשרשי אילן, ובסכך פסול בסוכה גדולה.\u003c/p>\u003cp>2. לבוד המקרב או המאריך: והיינו במקום שיש שיעור ראוי ואין צורך בחיבור, והחיסרון הוא המרחק שאינו נמצא במקום הראוי, וכגון בקורה משוכה ותלויה לעניין קורה על גבי מבוי, ובסוכה גדולה לעניין מחיצות סמוכות לסכך, ובמחיצה שיש בה עומד מרובה, ועוד.\u003c/p>\u003cp>3. לבוד המחבר: היינו במקום שבו מלבד חיסרון המרחק שאינו במקום הראוי, גם יש בו חיסרון שהמרחק גם מפריד ומגדיר את הדבר אחרת מאם היה מחובר, וכגון בשתי קורות אחת יוצאת וכו', ובלבוד באמצע בסוכה גדולה, ובמחיצה שיש בה עומד מרובה לעניין פתח בקרן זווית.\u003c/p>\u003cp>4. לבוד הממלא: היינו במקום בו מלבד מה שחסר בחיבור הדבר לאחד, גם על ידי החלוקה יש חיסרון שיעור בעצם הדבר, וכגון בשתי קורות המתאימות, ובסוכה קטנה, ובמקיפין שלושה חבלים.\u003c/p>\u003cp>ועוד יש למצוא חילוקים רבים בזה ודוגמאות רבות (וגם יש לבאר עוד בגדרי מחיצת עשרה וטפח דקורה וכו' שעפ\"ז יוגדר הלבוד בכמה אופנים ואכמ\"ל), ועכ\"פ הרי הוי הלכה אחת, ויש למצוא בזה גדר (ועיין שבת צז. וברש\"י).\u003c/p>\u003cp>ונראה שגדר דין לבוד מתייחס לכל דבר (רווח, שטח, וכן עצם וחסרונו) שאינו חשוב להתייחסות נפרדת מסביבותיו, ולכן עיקרו דין ביטול (וכדמשמע שם). וגדר ביטול זה נובע כמובן מחשיבות האחידות של הדבר שאליו הוא מתבטל; ודיני התורה הקדושה המתייחסים אל דברים המחולקים והאחידים, כגון חלקי מחיצה ורשות אחידה וכו', מוגדרים על ידי דין לבוד. וכגון דין לבוד המתייחס להצורך להגדיר שיעור גודל ריחוק שלא ייחשב כריחוק לעניין דבר הצריך המשכיות, והרי אין כל דבר דבוק לחברו לחלוטין שלא יהיה בו שום רווח בכדי שיהיה המשך, ובזה יש גדר ממתי נעשה הרווח בעיה להמשך ולשאר בעיות החלוקה באופן כללי וכדלעיל (ועוד יש לחייב בזה ביאור שלא נתבאר הכרח לבוד דמילוי).\u003c/p>\u003cp>ומאחר שעניין לבוד הוא מגדרי ביטול, את ההתייחסות לדבר המאוחד הבלתי נפרד יש להגדיר את דיני הלבוד שאינם שייכים בביטול רק בדברים שהם עצמם בחינה של דבר אחר; ובמקרה של לבוד דמילוי, וכגון מחיצות שהם בחינה (של גידור) למקום אותם הם חוצצות (היינו שאין המחיצות רק צורך להגדרת המקום הנידון כגדור ומיוחד לעצמו), במקרה כזה דין לבוד יאחד את הרווח שבין המחיצות עם המחיצות עצמן, לצורך הגדרת המקום אותם הם חוצצות כמגודר.\u003c/p>\u003cp>ונראה בסברת מה שאין אומרים זאת אלא בדבר שהוא התייחסות לאחר, שהוא בגלל שאין לנו להתייחס לחלקים כדבר אחד אלא אם כן ישנה משמעות איחוד קודמת לאחד אותם, כמו במקרה לעיל שישנו מקום אחיד ומחיצות נפרדות, ולשם אחידות המקום לעניין גידורו אנו מתייחסים גם למחיצות ולרווח שסביבותיו כאחד; וכן הוא בלבוד המחבר שיבוא סיבת החיבור לצורך המקום האחד.\u003c/p>\u003cp>(ובזה יש לבאר דין לבוד לחומרא בגבשושית: שמה שאין אומרים לבוד לחומרא הוא משום שאין דין פסלות וכו' דין חיובי שיש לומר עליו דיני לבוד, וזה שייך רק במקומות שבהם הדין הוא ביחס לדבר אחר כגון סכך לסוכה וכו', שאין סיבת הסכך היות הרווח שלידו גם סכך רק הסוכה, והיא אין בה אלא הכשר סוכה ולא פסלות, אבל בגבשושית אין זה רק ביטול הפשוט. ודו\"ק).\u003c/p>\u003cp>(וכן יש לבאר בזה בעניין דין תרי לבוד שמצינו ג' גווני: לבוד משתי רוחות בקורה, וכן לבוד וחבוט בקורה, וכן בסוכה במחצלת תלויה. ואף שיש לדמות הא דשתי רוחות דעירובין לתרי לבוד דסוכה, יש להבחין: דשתי רוחות דעירובין הוי מדין אחד דבעינן קורה על גבי מבוי, ושתי רוחות הוי פחות קורה על גבי מבוי מאשר רוח אחת; ובתרי לבוד דמחצלת אין שני הלבוד מקיימים דין אחד; ולאידך דתרי לבוד דמחצלת הוי בדין מחיצה עשרה דלולי כן לא הוי מחיצה [וסברא זו תלויה אי עשרה הוי שיעור גודל מחיצה או שיעור הנחצץ ברשות, ואכמ\"ל], אך בשתי רוחות דקורה הרי שיעור קורה עצמה יש כאן [דלא מצינו חילוק במבוי ארבעה, וצ\"ע, ואפשר דדין קורה ע\"ג מבוי גם חשיב שיעור עצמי, ואכמ\"ל], ובדין לבוד וחבוט הוא ממש באותו מקום ובדין אחד דבעינן קורה ע\"ג מבוי [ואף אם הוי פחות מג' באלכסון הרי נדרשנו לדין חבוט, ועיין רע\"א סוכה יז.]).\u003c/p>\u003cp>שנתבאר בגמרא (עירובין ט. וסוכה טז:) דצריכא לקמ\"ל (ועיין עירובין שם וברש\"י ד\"ה רב אשי), ולא נתבאר מאי שנא מהקפת חבלים וקנה קנה פחות משלושה דיש בהם כמה וכמה לבודים. ולמשנ\"ת יש לחלק בין דין לבוד בדבר שהוא עצמו שייך בביטול, לבין דבר שדין הביטול שלו הוא ביחס לדבר אחר, וכדלעיל.\u003c/p>\u003cp>הצעת קטע קישור בסיום הקטע: ולפי האמור יתבארו כל פרטי דין לבוד המפוזרים בש\"ס.\u003c/p>"}, {"id": "114", "n": 35, "a": "עורך – ביקורת ראשונית", "d": "2026-11-04", "h": "\u003cp>E-0021 | חומרה: נמוכה | קטגוריה: ניסוח ובהירות. במשפט מופיעים \"שני דינים שונים\" ובהמשך \"שני משמעויות אלו\". כדאי לבדוק התאמה דקדוקית (\"שתי משמעויות\") ולוודא שהקורא מבין מה היחס בין שני הדינים לבין משמעות הביטוי \"גוד אסיק\".\u003c/p>"}, {"id": "890", "n": 36, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-093 | סוג: קטע חסר | מקור: 08_הקדמות_והצעות_נוסח/הצעות נוסח להקדמה - נושא הרשויות.docx\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"עומד מרובה...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>וכהערה כללית בנושאי עירובין מה שנדרש להגדיר בכל דיני מחיצות והל\"מ שלהבדיל מההבנה המוטעית כאילו ההלכות גוד ולבוד ודופן עקומה הן כאילו חריגה מהתפיסה הרגילה את מושגי מחיצה וזה אינו כי הם השלמה לתפיסה האמיתית של מחיצות כי הדינים האלו למרות שקיבלנו מסיני כקבלה ולא כסברא הרי הם חלק ממכלול ההבנה האמיתית של מחיצה ורשויות\u003c/p>"}, {"id": "891", "n": 37, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-094 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/מלאכת שבת רשויות עירובי חצירות תחומין.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"מפולש...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>והאי נפרצה חצר כנגדו משום רבותא דחצר נקט דאע''ג דרבים נכנסין לה בזו ויוצאין לה בזו אפילו הכי שריא הואיל ונפרצה בפחות מעשר דחשיב כפתח חצר אבל איסור מבוי לאו משום [פירצה] דכותל שכנגדו הוא אלא משום דבני חצר אסרי עליה כי לא עירבו דכיון דלדידיה הוי מלואו פירצה הוא ודיורי חצר אוסרין עליו והוא אינו אוסר עליהן כדאמרינן בפרק כל גגות העיר (לקמן ד' צב ).גבי חצר גדולה שנפרצה לקטנה דיורי גדולה בקטנה כלומר אוסרים בקטנה דדידהו הוא דבטלה לגבה ואין דיורי קטנה בגדולה דלגבי גדולה פתח הוא ושתי חצירות שיש ביניהן פתח לא אסרן אהדדי כדאמרינן בפרק חלון (לקמן ד' עו ):נפרץ הכותל עד עשרה אמות אם רצו מערבין שנים ואם רצו מערבין אחד מפני שהוא כפתח ושניהם מותרין זה בזה: והיינו שדברי רב בחצר תלויים באם עירבו בני חצר עם בני מבוי דאם עירבו בני חצר עם בני מבוי ואין רשות חצר נפרדת מרשות מבוי אף שנפרצה אין נפרצה למקום האסור לה ואף שדיורי החצר במבוי אין אוסרים על בני מבוי שהרי עירבו עימם אבל אם לא עירבו בני חצר עם בני מבוי אף שחצר עצמה לא נפרצה ואין לומר שהם נחשבים למקום אחד עכ\"פ לגבי מה דצריך שיהיה למבוי מחיצה נחשב לפרוץ והיינו דלגבי מה שנחשב לבני מבוי שמשתמשים במבוי שמשתמשים בשלהם וכיון שנפרצה אין המבוי מקום נפרד שלהם והוא מחובר למקום שאינו שלהם וכיון שכן אין להגדיר את המבוי כרשות שלהם וא\"כ המשתמש במבוי משתמש בשלו וכיון שאין להגדיר את מקום שימושו כאחד ע\"י השימוש (וכמו ברה\"ר) הרי שטלטול יותר מד\"א הוי כמוציא מרשות לרשות (והנה לא חילקו בגמ' הא דעירבו ולא עירבו כמו מה שמבואר בגמ' בשבת לגבי איסור מבוי ואיפכא דבעירבו היינו בני חצר לעצמם והרי נאסר להוציא מחצר למבוי וממבוי לחצר והוו שתי רשויות ומבוי רשות שנפרצה למקום האסור לה ובלא עירבו הוה רשות אחת ולנפרצה למקום המותר לה דכיון שנפרץ במילואו אף אם לא עירבו הרי בית פתוח למבוי ואיכא לדיורי בית במבוי כמו דאיכא בחצר ולא דנו שיהיה עירבו יותר סיבה לאיסור במבוי רק משום שנחשב החצר רשות הבית וממילא הנמצאים שם נחשבים דיורי בית וכיון שהמבוי משמש את החצר שהיא רשות בית והיא פתוחה לו הרי שדיורי הבית במבוי ואסרים בני חצרות זה על זה שאינם משותפין משום חצר כמו בני חצר אחת וגם אין נחשב המבוי רשות לחצר לבד בלי בתים (וכמו בלא עירבו) דכיון דהחצר רשות הבתים אין חשוב שימוש חצר עצמה להגדיר שימוש במבוי כשימושה שנאמר שיהיה המבוי רשות שלה דחשיבא ליה לדיור בית יותר מדיור חצר שהוא מיוחד ותדיר יותר אבל בלא עירבו אין החצר רשות בית (וגם אם יבטלו לאחד אין הגדר שהחצר כולה רשות ביתו אלא דכולה רשותו שלו) ואין הדרין בה נחשבים כדרים בבית ושימוש שלהם במבוי עושה אותה רשות החצר ורשות חצירות במבוי היא רשות אחת כמו דחצרות רשות אחת וביאור מה דדיורי בתים יחד במבוי אין בו להגדיר רשות אחת לכולם הוא משום שדיורי בית הוי מיוחדים לדר ויהיה משמעות בשימוש דבית במבוי שאין הוא כשימוש של בית וכיון שמה שאינו מיוחד הוא משום שאר בני מבוי יש בזה להבדילו משאר בני מבוי ואין שימושו של זה חלק משימוש כולם וכן כולם ואין שליטת החצרות במבוי אחת שיהיה המבוי רשות כל החצרות באחת ושיהיה המבוי רשות אחת לעצמו וכמו בחצר שאינה מעורבת אין לדמות דכיון שאין במבוי ד' מחיצות ואין בו שימוש תדיר אינו חשוב לעשות רשות לעצמו (לעומת חצירות ששולטות עליו ובטל להם) וכיון שאין בו רשות אין המקום אחד וכיון דאין המקום אחד כל מקום ומקום חלוק לעצמו ומעביר ד\"א הוי כמרשות לרשות)\u003c/p>\u003cp>בשלא עירבו .כי לא נפרצה מאי טעמא דשמואל דאמר בני חצר אסרי ומאי טעמא דרב דאמר לא אסרי :בנראה מבחוץ ושוה מבפנים .דפליגי ביה אמוראי לקמן בפירקין (ד' ט ):איכא למאן דאמר נדון כנראה משני צדדין ואיכא למאן דאמר אינו נידון והכא נמי הנך גיפופי דאית לחצר העודפים על רוחב פירצת המבוי נראין מבחוץ לאותן העומדים בחצר ולא מיחזי\u003c/p>\u003cp>כותל פרוץ במלואו ויותר מעשר נמי לא הוי הלכך אע''ג דשוה מבפנים שהעומדין במבוי אין רואין אותו ונראה להם כותל פרוץ במלואו אפילו הכי לרב מהני הני גיפופי לשוויה פתחא לגבי מבוי כי היכי דמשוו ליה פתחא לגבי חצר והא דתנן קטנה אסורה מוקים ליה רב בנכנסין כותלי קטנה לגדולה דליכא נראה מבחוץ והויא פרוצה במלואה אבל הכא פיתחא הוא אף למבוי ולא אסרי בני חצר למבוי ואע''ג דשאר חצירות הפתוחות למבוי בפתח הגון ודאי אוסרות עליו זו הואיל ואינה רגילה בו שהרי סתום היה מתחלה אינה אוסרת עליו כדאמר בפרק מי שהוציאוהו (לקמן ד' מט ).שאינה רגילה בו מותר ושמואל סבר אין נידון משום שיור למבוי ופירצה היא ודיורי חצר אוסרין עליו אם לא עירבו: וביאור זה הוא דכיון שאין החצר רגילה במבוי אין להחשיב את המבוי רשות החצר וגם דיורי החצר אינם אוסרין על בני מבוי כיון שאינם במבוי שיש מחיצה ביניהם אבל בחצר שרגילה בו הוה המבוי רשות החצר ושמואל סבר דאין נידון משום שיור וא\"כ נפרץ המבוי במילואו לחצר ואף שאין רשות החצר פרוצה לו שנאמר שמקום המבוי אחד עם מקום החצר ואין לעשות שתי רשויות במקום אחד כיון שהוא פרוץ לה נחשב מקום אחד לגבי דיורי החצר והיינו שגדר מחיצה רביעית הוא להגדרת המקום כמשמש וזה אין לו מחיצה וכיון שכן נחשב שמשמש כאחד עם חצר שלידו ואף שאין לו להיחשב כמשמש את החצר שאינם רגילים בו כיון שיש בשימוש בו לבני החצרות נפרדות ביחס לדיורי חצר שלידו הרי שאין הוצאתם לרשות האחת של כולם יחד אלא למבוי שיש לו זכות השתמשות בו והווה כמוציא מרשות לרשות ולשון שיור שכתב רש\"י היינו גדר נראה מבחוץ וכו' בפס ולחי יחד שלחי הוא מכח מחיצה שלידו דחשיב מחיצה או היכר ופס הוא מחיצה רביעית ואף בשני לחיים שאמנם הוא מכח מחיצות שבצידו אך עי\"ז חשיב שיש מחיצה בצד רביעי ואף שאין זה מחיצה למקום עצמו נחשב שיש מחיצה בצד רביעי כיון שהוא חוצץ במקומו בין החוץ לאויר שכנגדו וע\"כ יועיל כל עוד תהיה המחיצה הנ\"ל קשורה למקום המבוי אפילו נראה מבחוץ\u003c/p>\u003cp>חצר קטנה חצר גדולה חצר קטנה שנפרצה .במלואה לגדולה גדולה מותרת ולא אסרי בני קטנה עילויה דלגבי גדולה פתח הוא דיש לה שיור מכאן ומכאן והוו כשתי חצירות ופתח אחד ביניהן דלא אסרן אהדדי ולקמן מוקי לה בשאין קטנה רחבה יותר מי' דאי יותר מעשר לא הוי פתח גבי גדולה :וקטנה אסורה .דלדידה לאו פתח הוא אלא פירצה ונעשית רשותן של בני גדולה שהרי נתערבה עמהן :א''ל .רב היתר חצר אשמעינן ואע''ג דנפרצה בכותל השני דדרסי רבים מרשות הרבים זו לרה''ר זו דרך חצר ומבוי דאי מהתם הוה אמינא משום דלא דרסי רבים דהא גדולה לא נפרצה בכותל השני: ושוב חזינן דדייק רש\"י לומר דהאי חצר נעשית רשות של בני גדולה והיינו בני החצר הגדולה ויש בזה גדר כמו שהיתה פתוחה לקטנה ודריסתה עליה\u003c/p>\u003cp>אתי רבים אי מהתם .מחצר שהרבים נכנסין לה כו' דקתני רשות היחיד לשבת :הוה אמינא .האי דקרי ליה רה''י :לזרוק .כלומר מדאורייתא רה''י הוא והזורק מרה''ר לתוכו חייב :אבל לטלטל. בתוכו :אימא לא .משתריא ומדרבנן דליגזור רבנן עליה :קמ''ל. רב מותרת: ומשמע דלא פסקינן כר\"י לגבי אתי רבים ואפילו לטלטל וכן כתב רש\"י בשבת (ו):\u003c/p>\u003cp>תיקון מבוי לדברי המתיר .להשתמש תחת הקורה אלמא חיצון יורד וסותם אוסר כל המבוי הזה עד שיביאו קורה אחרת דאין הסתימה מחוברת לכתלים ויש אויר ביניהם והכא לאו מחיצה ממש הוא להכשיר הפסק אויר שמכאן ומכאן ע''י לבוד: וזה משום מה דאמרן לעיל דגדר תיקוני מבוי הוא תיקון שיחשב היקף רשות השימוש באופן הפחות וע\"כ כתבו רבי ברישא\u003c/p>\u003cp>איסור חצירות חצירות של רבים .שפתוחין בתים הרבה לחצר ואוסרים בני הבתים זה על זה שאין יכולין להוציא מן הבתים לחצר בלא עירוב מפני שהבית רשות מיוחדת לו וחצר רשות חבירו מושל בה ונמצא מוציא מרשות לרשות ורבנן גזור שלא להוציא מרשות היחיד לרשות היחיד גזירה דילמא אתי לאפוקי מרשות היחיד לרשות הרבים אבל בחצר מותר לטלטל בה כדאמרינן במסכת שבת בפ' רבי אליעזר אומר אם לא הביא כלי כו' (ד' קל:): ויש כאן שלושה חלקים ברש\"י דמה שכתב שפתוחין בתים הרבה לחצר ואוסרים בני בתים זה על זה היינו אחר תקנת עירוב וכמו שכתב בהמשך שאין יכולים להוציא מן הבתים בלא עירוב ומעתה מבאר סיבת איסור חצרות מפני שהבית רשות מיוחדת לו וחצר רשות חבירו מושל בה והיינו שאין ביאור זה גדר אחר שתקנו דיני רשויות אלא עיקר מה דאיתא לחילוק רשויות בין בית לחצר שהבית רשות מיוחדת לו היינו שהיא מיועדת לשימושו לבד וחצר רשות חבירו מושלת עליה היינו חצר המקום עצמו רשות חבירו מושל בה היינו בית חבירו שהיא משועבדת לבית חבירו וגדר לו ולחבירו היינו ביחס למה שהיא מיוחדת ואין חסרון בעצם מה שיש לחבירו גם רשות בחצר דאין חסרון בדר בלא בית אלא במה שביתו מושל ברשותו והיינו דכיון שביתם מושל בחצר הרי שיש בחצר גדר שאף בתוכה הרי היא משמשת את הבית היינו רשות הבית וע\"כ הבדל הגדר בין רשות ביתו לרשות חצירו משמעותי שאף היא רשות הבית אך אינה מיוחדת וגדר רשות הבית אין כוונתנו בדיני רשויות שאחר תקנה אלא במשמעות שימוש בית שיש בחצר דאחידות השימוש והבדל המיוחדות שיש ביניהם מחלקם והיינו שזה ביחס לאדם המשתמש שביתו מיוחד לו וחצירו אינה אבל אחר תקנת עירוב אין מוגדר באדם אלא ברשות עצמה וע\"כ כתב שהוא כמוציא מרשות לרשות ומה שנקט רש\"י גדר בבעל הבית המשתמש ולא בכל מי שמוציא הוא משום שלפני תקנת עירוב באמת אין משמעות רק לבעל הבית אלא שאחר שתקנו חילוק רשויות אין זה גדר במי שמשתמש לבד (חוץ מביטול רשות) שזה גדר ברשות ומה שכתב דהוי מוציא מרשות לרשות היינו דווקא כיון שהבית מושל על החצר ולא סתם חבירו שמושל שאין זה נוגע לרשות והיינו שאם היינו מתייחסים לחצר לבדה בלי מה שמשמשת את הבית הרי שיש כאן שימוש מעורב של כמה אנשים בדיוק כמו בבית אחד וכן הדרים בלא בתים אינם אוסרים וכמו בשיירא ולא היה בהוצאה דאחר מבית לחצר יותר ממשמעות שמוציא מרשות אלו לרשות אלו שנתבאר שאינה אסורה כמו מקרפף לקרפף דתרי ואחר כתב ורבנן גזור שלא להוציא מרשות היחיד לרשות היחיד\u003c/p>\u003cp>עיר של רבים\u003c/p>"}, {"id": "115", "n": 38, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-198 | חומרה: בינונית | קטגוריה: קישור בין מסקנת־ביניים להרחבת ההקדמה. פסקה זו מסכמת את ההבחנה שבכותרת P00845: ברשות הרבים כל חלק וחלק מקבל גדר רשות בפני עצמו, ואילו ברשות היחיד כלל המקום מוגדר כאחד. כדאי לוודא שהפתיחה „ובאמת כמש״כ” מפנה למהלך שקדם לה ולא נשענת על „כמש״כ” שאינו ברור לקורא, ושמובן כיצד חסרון האחידות ברשות היחיד נובע מגודלה ולא מתנאי הקרקע בלבד. יש לבדוק במיוחד את המעבר שבסוף הפסקה אל P00847: שם מתווספת לרשות הרבים לא רק שלילת האחדות אלא גם איכות חיובית של הפרדת כל מקום, והביטוי „נמצא בכמה מקומות ואין לו מקום” דורש הכנה מושגית. הערת S-20261109-173 כבר בוחנת את P00847 ואת המעבר מפסקה זו אליה; הערה זו משלימה את בדיקת חוליית הסיכום P00846 ואינה חוזרת על תוכן ההערה הקודמת. ההופעה ב־P02943 נשארת בגוף הספר, ואין לקצר את ההצגה המוקדמת.\u003c/p>"}, {"id": "116", "n": 39, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-173 | חומרה: בינונית | קטגוריה: רציפות ההקדמה ושילוב מושגי. פסקה זו ממשיכה את ההבחנה שב־P00846 בין אחידות המקום ברשות היחיד לבין היות מקומות רשות הרבים נפרדים, ומוסיפה לכך את האיכות החיובית שבהפרדה. כדאי לבדוק אם פתיחת „וכן לרה״ר” נשענת בבירור על ההשוואה הקודמת, ואם המעבר מן התיאור השלילי של העדר אחידות אל האיכות החיובית מנוסח באופן מדורג. בפרט, הביטוי „נמצא בכמה מקומות ואין לו מקום” טעון הצגה לקורא כהגדרה מושגית של מעמד החפץ ולא כטענה פיזית; יש לוודא שהניסוח מבהיר את הפרדוקס לכאורה בלי להכביד. סיום הפסקה צריך להכין את המעבר לכותרת P00848, „המבנה הממשי של רשות הרבים”. ההרחבה ב־P03325 נשארת בגוף הספר, ואין לקצר את ההצגה המוקדמת בגללה.\u003c/p>"}, {"id": "892", "n": 40, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-095 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/מלאכת שבת רשויות עירובי חצירות תחומין.pdf / 08_הקדמות_והצעות_נוסח/תוכניות להטמעת קטעים.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"המבנה הממשי של רשות הרבים...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>מקור: חלק ג', כותרת 3 מס' 135 (בתוך \"יז. יסוד מחלוקת ר\"י וחכמים בלו\"ק\")\u003c/p>"}, {"id": "893", "n": 41, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-096 | סוג: קטע חסר | מקור: 08_הקדמות_והצעות_נוסח/הצעות נוסח להקדמה - נושא הרשויות.docx / 08_הקדמות_והצעות_נוסח/תוכניות להטמעת קטעים.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"וא\"כ הוא שאין רה\"ר גדר מקום חפץ, וא\"כ הוא שביארנו שדין רשות דהוצאה הוא דין במקום חפץ, הרי שביחס להגדרת שינוי ש...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>C4. ראיה לגדר השלילי משיעור ד' אמות בהעברה\u003c/p>\u003cp>מיקום הכנסה מוצע: להוסיף בהמשך ישיר ליחידה C3 לעיל (אותו מיקום, מיד אחריה) - מהווה חיזוק/הוכחה לאותה הקביעה, מזווית שונה (שיעור ד\"א דהעברה).\u003c/p>\u003cp>מקור: חלק ב' (מלאכת הוצאה-סוגיות), כותרת 3 מס' 46 (\"ה\"-\"ו\")\u003c/p>"}, {"id": "117", "n": 42, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-195 | חומרה: בינונית | קטגוריה: רציפות טיעונית והכנת ההוכחה. יש לקרוא את P00865–P00866 כיחידת קושיה ודחייה אחת: P00865 מציגה את ההבנה הנדחית שלפיה דין העברה נובע מהיות רשות הרבים מחולקת, ו־P00866 דוחה אותה מכוח העובדה שרשות הרבים נחשבת רשות אחת גם לעניין צירוף שני חצאי שיעור. כדאי לוודא שהביטוי „ונקדים להוציא מדעת” מבהיר לקורא שמדובר בהצגת סברה שנדחית ולא בהנחת יסוד של המחבר, וש„וזה אינו” שבפתיחת P00866 חוזר במדויק לאותה סברה. סיום P00866 צריך להכין את הכותרת P00867 ואת הראיה משיעור ארבע אמות, ולא להשאיר את הדחייה ללא תוצאה. ההופעות המקבילות P01156–P01157 נשארות בגוף הספר; יש לשמר את שתי הפסקאות בהקדמה ולוודא שהן משתלבות ברצף שמוביל בהמשך לראיה ב־P00868–P00869, שכבר נבדקה בהערת S-20261109-175.\u003c/p>"}, {"id": "118", "n": 43, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-175 | חומרה: בינונית | קטגוריה: רציפות הוכחה ושילוב הפסקאות. פסקה זו מציגה בהקדמה ראיה משיעור ארבע אמות לכך שגדר העברה ברשות הרבים אינו מעבר מרשות אחת לאחרת, אלא שינוי במקום החפץ. כדאי לבדוק שהמעבר מן ההקדמה הקודמת, שבה הובהר שרשות הרבים היא רשות אחת (P00865–P00866), אל הראיה משיעור ארבע אמות מפורש, ושהפתיחה „וכן נראה שיש להוכיח” מצביעה בבירור על הטענה שאותה היא באה להוכיח. יש לוודא שהניגוד בין שיעור ארבעה טפחים שהיה צפוי אילו היה מדובר בשינוי רשות לבין שיעור ארבע אמות בפועל מוסבר במידה הנדרשת לקורא. P00869 ממשיכה ישירות את מסקנת הראיה; נכון לקרוא את שתי הפסקאות בהקדמה כיחידת הסבר אחת וללטש את המעבר ביניהן. ההופעה המקבילה בגוף הספר ב־P01160–P01161 היא פיתוח באותו הקשר ואינה סיבה לקיצור או להפניה.\u003c/p>"}, {"id": "119", "n": 44, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-187 | חומרה: בינונית | קטגוריה: רצף מושגי והטמעת רצף הפסקאות. יש לקרוא את P00871–P00873 כרצף אחד בהקדמה: P00871 מציגה את ההבדל בין מקום רשות הרבים, המיועד להילוך ולשימוש ארעי, לבין מקום רשות היחיד, המיועד לשימוש קבוע; P00872 משלימה את הצד של רשות היחיד; ו־P00873 מוסיפה הערת מקור וביאור ביחס לרש״י ולרב חסדא. כדאי לוודא שהמעבר מ־P00870, המציגה את חילוק השימוש, אל פתיחת „ומעתה יבואר” ברור, ושאין חזרה לא מוסברת בין שני אופני השימוש. יש לבדוק גם אם P00873, המובאת בסוגריים ומסתיימת ב„ובמק״א הארכתי”, נקראת כהערת מקור המשולבת במהלך או כקטע צדדי שמנתק את הרצף. יש לשמר את כל שלוש הפסקאות בהקדמה; הופעותיהן ב־P01181–P01183 הן פיתוח בגוף הספר ולא סיבה לקיצור ההקדמה. ההצגה המוקדמת צריכה להיקרא כיחידת הסבר אחת, טבעית ורציפה.\u003c/p>"}, {"id": "120", "n": 45, "a": "עורך – ביקורת ראשונית", "d": "2026-11-04", "h": "\u003cp>E-0009 | חומרה: בינונית | קטגוריה: הפניות פנימיות. הביטוי \"במק\"א הארכתי\" מופיע במספר מקומות, לצד הפניות כגון \"במק\"א\" ו\"במקום אחר\". יש לקבוע בכל מופע אם ההפניה פנימית או חיצונית, ולציין מיקום מדויק או פרטי חיבור. הדוח מרכז את כל המופעים שאותרו.\u003c/p>"}, {"id": "894", "n": 46, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-097 | סוג: קטע חסר | מקור: 08_הקדמות_והצעות_נוסח/הצעות נוסח להקדמה - נושא הרשויות.docx / 08_הקדמות_והצעות_נוסח/תוכניות להטמעת קטעים.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ובהתפשטות שימוש הרבים לעוד מקומות נמצא כמה גדרים, וכמו ע\"י הדחק, היינו, שאף אם יהיה מקום המשמש את הרבים באחת ע...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>הערת עריכה: זהו קטע רציף אחד ובלתי-מקוטע במקורו (כותרת 7 מס' 646 עד 651 ברצף), ולכן הובא כיחידה שלמה אחת. מכיל בתוכו (במס' 649) גם דוגמה קונקרטית (עמוד תשעה) הממחישה את חילוקי רה\"י/רה\"ר, וכן (במס' 651) התייחסות למקרה קרן זווית - מובאים במלואם כחלק אינטגרלי מרצף הביאור.\u003c/p>\u003cp>C7. יסוד תיקון יהושע: הרבים מגדירים את משמעות השימוש ולא את הקרקע עצמה; וסיכום שלבי ההגדרה\u003c/p>"}, {"id": "895", "n": 47, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-098 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 5 (הערת שוליים 10)\u003c/p>\u003cp>נושא ההערה: כוחן של מחיצות לדעת רש\"י ודלתא דירושלים; נכתבה על הדיון בדעת רש\"י בירושלים.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: אבל לפי צד א' בתוס' [כב. ד\"ה קשיא] משמע לכאו' שלדעת ר' יהודה יש חילוק בזה, שמבואר שכיון ששתי מחיצות דאורייתא ממילא אע\"ג שצריך מדרבנן לחי ברוח שלישית ורביעית אינם מתבטלים ע\"י בקיעת הרבים, וגם לא מוכח ש\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>אבל ברש\"י לא זכר דלתא דירושלים הוה משום אתי רבים, והיה לחלק בין נידון דרה\"ר מיערבא לארומ\"מ, אף דמיניה מוכח דר\"י לא ס\"ל כוחן של מחיצות, והיינו, דגדר כוחן של מחיצות הוה במשמעות חיובית להיות המקום רה\"י (ולהיותו מגדיר השימוש בו, ולא אתו רבים אלא רובי יחידים).\u003c/p>"}, {"id": "896", "n": 48, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-099 | סוג: קטע חסר | מקור: 08_הקדמות_והצעות_נוסח/הצעות נוסח להקדמה - נושא הרשויות.docx\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"הגדרות השימושיות של רשות הרבים...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>וכאמור עיקר משמעות תנאי רשות הרבים שיהיה המקום מיועד לשימוש הרבים כל אחד שירצה.\u003c/p>"}, {"id": "121", "n": 49, "a": "עורך – ביקורת ראשונית", "d": "2026-11-04", "h": "\u003cp>E-0015 | חומרה: בינונית | קטגוריה: רציפות ההקדמה והשתלבותה. פסקה זו מציגה כבר בהקדמה את זיקת מסירת יהושע והנחלת הארץ להגדרת קרקע לרשות הרבים. ההצגה המוקדמת נועדה להעשיר את התשתית המושגית ולכוון את הקורא לנושא שיפותח בגוף הספר, ולכן אין להציע לצמצמה או להחליפה בהפניה. יש לבדוק את ההטמעה בתוך ההקדמה: האם המעבר מן הדיון בשימוש הרבים ובקרקע אל שאלת כוחו של יהושע נבנה באופן מפורש; האם הפתיחה „ולפ״ז” נסמכת על מסקנה ברורה; והאם סיום הפסקה מכין את הסיכום הבא על תנאי רשות הרבים. אם נדרש, אפשר לחדד משפט קישור או את סדר הצגת ההנמקות, כך שהפסקה תיתפס כהמשך טבעי של ההקדמה ולא כיחידה נפרדת שנפתחת בבת אחת.\u003c/p>"}, {"id": "897", "n": 50, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-100 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/הקדמות וכללים - רשויות - הוצאה - עירובין - תחומין.docx\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ולפ\"ז יש למצוא גדר במה דזה תלוי במסירת יהושע ובכוחו להנחיל את הארץ, כי דין התורה במה נחשב רה\"ר הוא בקרקע שאין ...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>הצריך ביאור לפי\"ז בדברי רש\"י בדגלי מדבר\u003c/p>\u003cp>גדר הילוך ותשמיש הנמצא בסוגיא דרקק\u003c/p>"}, {"id": "898", "n": 51, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-101 | סוג: קטע חסר | מקור: 04_רשויות/רשויות - עותק 2.docx / 04_רשויות/רשויות.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"וא\"כ מצאנו כמה תנאים ברה\"ר, זה לפנים מזה, דגדר הקרקע כמקום הראוי להנחת חפץ הוא תנאי ראשון, ובזה אין צורך שיהיה...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>הצריך ביאור לפי\"ז בדברי רש\"י בגדלי מדבר ובגדר תשמיש והילוך\u003c/p>"}, {"id": "899", "n": 52, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-102 | סוג: קטע חסר | מקור: 04_רשויות/רשויות - סוגיות - עותק 3.txt / 08_הקדמות_והצעות_נוסח/תוכניות להטמעת קטעים.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"וא\"כ מצאנו כמה תנאים ברה\"ר, זה לפנים מזה, דגדר הקרקע כמקום הראוי להנחת חפץ הוא תנאי ראשון, ובזה אין צורך שיהיה...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>הערת עריכה: כותרת 7 מס' 628 עוסקת בכוחו ההלכתי של יהושע בחלוקת הארץ, ומזכירה בסופה (במשפט אחד) את סוגיית \"מעלות ומורדות דארץ ישראל\" - נושא שיש בו מחלוקת ראשונים בפרטיו. הפסקה עצמה, לעומת זאת, אינה נוקטת עמדה במחלוקת זו אלא רק מציינת שהיא שם מקומה; היסוד העצמי (כוחו של יהושע כמנחיל ולא כמחוקק, וההבחנה בין הגדרת הקרקע להגדרת השימוש) הוא ניתוח עצמאי של המחבר. מובא במלואו כלשונו; אם ברצונך להימנע לגמרי מכל רמז למעלות-ומורדות, ניתן לעצור את הציטוט לפני המשפט האחרון (המתחיל \"וע\"כ יבואר מה שחסרון דמעלות ומורדות...\").\u003c/p>\u003cp>חלק ד — הצעת מסגרת פתיחה כוללת לחילוקי רשויות\u003c/p>\u003cp>D1. מטריצת ד' רשויות השבת: \"האם מקום?\" × \"האם מיועד לשימוש?\"\u003c/p>"}, {"id": "900", "n": 53, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-103 | סוג: קטע חסר | מקור: 08_הקדמות_והצעות_נוסח/הצעות נוסח להקדמה - נושא הרשויות.docx\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"סמטא, והיא המיועדת לשימושיו הפרטיים של האדם היחיד ולכל אדם שירצה בכך. והיא זכות כל אדם, ואין זכות למנוע ממנו ש...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>האמורה היא חציצה בפני החוץ לרשות התופס עד עשרה ואפילו שהמחיצות מהותם להגדיר את הרשות לעצמה ולא רק להבדיל אותה מחוצה לה ההבדלה מחוצה לה גורמת הגדרה לעצמה שאר דיני המחיצות ומחלוקתם נוגעים בעיקר להגדרה מה נחשב גידור בעיני הרואה דיני השימוש היות הרשות מיועדת לשימוש דירה ושלא יעבור בה דרך הרבים וכו' הם מחמת שהשימוש ואי השימוש המציאותי בה ומשמעותו יכול לעקר את המשמעות של הגידור שלה רשות הרבים התנאים הגשמיים כמו דיני רשויות הרגילים היות המקום ארבעה על ארבעה וכו' גם דיני השטח של רשות היחיד מוגדרים על הצורך שיהיה מקום זה ראוי לשימושים המוגדרים כשימושי הרבים והשימוש בה אע\"פ שאין זה הלכה פסוקה שיהיו בה באיזה שהיא צורה ס' ריבוא ודאי זה מגדיר את הצורך שבאמת יהיה בה שימוש הרבים\u003c/p>\u003cp>והנה שאין בדעתנו להעמיד הגדרת הרשויות על דיוקם רק נאמר שרשות היחיד מיועדת לשימושים פרטיים ולדיירים הנמצאים שם לשימושים אלו ורשות הרבים מיועדת לשימושים ציבוריים ולציבור המגיע לשם לעשות אותם והשינויים האמורים הם הסיבות לשינויים הדינים בתנאים ליצור רשות כזו ומקום פטור מהותו בעצם שהוא חסר יעוד מסוים מחמת היותו בלתי ראוי לשימוש מגדיר או שאר סיבות המוזכרות דהינו שאין בתנאי המקום שלו שיעור להיות מקום מסוים ונפרד לעצמו ואף שצורת הדברים הם שימוש הנותן למקום את הגדרתו קבעו חכמים שגם מקום שבגדרי מקום יש בו כח ליתן בו מהות אע\"פ שאינו מיועד לשימוש נחשב למקום בעל הגדרה אחרת והיא כרמלית ומהות זו מוגדרת על ידי כמה תנאים והם התנאים הגשמיים המכינים אותה לשימוש היחיד והשימושים בה התנאים הגשמיים הם בעיקר המחיצות שהם הגדרים המבדילים אותה מחמת היותה מוגדרת לעצמה ע\"י המחיצות הגשמיות שמבדיל אותה בדעת האדם ממקום אחר\u003c/p>\u003cp>בביאור דין חצר גדולה חצר קטנה נראה שענין שדיורי גדולה בקטנה ואין דיורי קטנה בגדולה והיינו שודאי אין דיירי גדולה דרים אלא בגדולה רק שלענין הדינים שמשפיעים דיירי גדולה על הקטנה בהיותם שייכים בה שפתוחה אליהם ענין זה שייך רק בדיורי גדולה והיינו שישנם דינים ומציאות בקטנה שאינם מצריכים את דיירי גדולה להיות ממש בתוך קטנה בכדי שיהיו בדינים אלו גם אלא רק היותם שייכים בה (בראיה בקירבה וכו') מספיק בשביל שיחשבו דינים אלו הקיימים בקטנה גם בגדולה והיות דיורי גדולה בקטנה מחשיבה שגם לגדולה יש חלק בקטנה לענין דינים אלו וכך בדינים הנצרכים לעירוב המקומות אם הכח המערב ויוצר דינים הוא כח שנובע מגדולה הרי שנחשבים המקומות מעורבים לענין זה אך אם הכח המערב הוא כח שנובע מ(דין הנובע ממציאות שקיימת ב)קטנה הרי שאין זה גורם שהמקומות יחשבו מעורבים לענין זה\u003c/p>\u003cp>והשימוש בה שמגדיר אותה כרשות היחיד ששימושיו הם שימושי היחיד הם בסוג השימושים והן במשתמשים רשות הרבים כמשנ\"ת מיועדת לשימושים ציבוריים ולציבור המשתמש ומהות זו מוגדרת על ידי כמה תנאים והם התנאים הגשמיים המכינים אותה לשימוש הרבים והמשתמשים בה ובזה יש להבחין האם רשות הרבים היא רשות מוגדרת למהותה או אי רשות וכן יש להבחין מהו שרשות הרבים עד עשרה טפחים אך הגדרה ממנה נעשית לרשות עד השמים התנאים הגשמיים הם יכולת שטחה להכיל שימושי הרבים והשימוש בה הם הימצאות המשתמשים בה וכו' מקום פטור כמדומה שמעצם שמו נראה שאין זה רשות בעלת הגדרה חיובית שתנאיו רק שלא יהיה רשות היחיד ולא רשות הרבים וקראהו אוויר וכו' ואחרי חידוש דין כרמלית עוד נוסף בו שלא יהיה בעל שיעור מקום רשות היחיד דיני המחיצות מושתתים על אמת התורה בדבר איזה מקום צריך להיות נחצץ ודעת האדם הרואה בהם חוצצים את המקום אותו אמרה התורה לחצוץ והנה אע\"פ שרשות היחיד תופסת עד הרקיע הלכה למשה מסיני הוא שהמקום הצריך חציצה הוא עד עשרה טפחים ובזה נלמד שהחציצה\u003c/p>\u003cp>ובוא ונסדר דיני עירובין אשר למדנו זה הזמן מה שנראה לחשבן בעיקרי דיני מחיצות והנה מצאנו כמה דינים חלוקים מהם כתובים בתורה ובהלכה למשה מסיני דיני מחיצה לכאורה נתחדשו בצורך הדיני להפריד בין מקומות רשויות וחפצים ואו שנאמר דין מחיצות עיקרו דאוריתא מה שכתוב בגמ' דף ג: דלר' יהודה גמרינן מארון וכפורת והנה לא נתברר מה הלימוד מן הארון אחר שאומר רש\"י שעיקר הלימוד הוא מזה שאין השכינה יורדת למטה מעשרה טפחים ומשמע שיש רשות תחתית וכו' והנה אין זה מעצם הדין דשיעור אמות דארון וכפורת רק שלדעת ר\"מ אין אפשרות ללמוד כיון שלדעתו ירדה שכינה אף למטה וכו' רק היות המושג שישנם בכל רשות חלוקה של עשרה טפחים הגדרה של מחיצה היא הגדרה משתנה לפי הגדרת הנחצצים והגדרה קבועה של הגדרת מחיצה באשר היא היותה עומדת וראויה לחצוץ בפני ענינים וחלק גדול ממטרתנו הוא להגדיר האם דין מסוים נובע מסיבת הגדרת הנחצצים או שמא מסיבת הגדרת המחיצה וכדוגמא חלקי דינים הנובעים מן הגדרת המחיצה הן דיני חוזקה ודינים הנובעים מן הגדרת הנחצצים הן גודל רוחב המחיצה וכו' ונביא בזאת רשימת דינים המוזכרים בפרקנו\u003c/p>\u003cp>ארבעה רשויות שני רשויות שבת רשות היחיד ורשות הרבים כרמלית ומקום פטור רשויות היחיד שונות כמו בית חצר ומבוי גג וקרפף להם ניתן דינים שונים מחיצות כמה וכמה מושגים הנובעים מדיני מחיצות מחיצה עשרה טפחים לבוד גוד אחית גוד אסיק פסי ביראות פי תקרה פס ארבעה\u003c/p>\u003cp>שיעורה י' טפחים גובה\u003c/p>\u003cp>מושגים הנזכרים בדיני רשויות ומחיצות, מושגים כללים מקום חשוב -הגדרה המתייחסת למקום בעל חשיבות עצמית או נפרדת מהסובב לפי יכולת השימוש בו המושפעת מגודלו וכו' והנה על אף שלמקום שנאמר עליו הדינים האמורים הם משפיעים עליו בדרכים שנות שהרי לא דיני מחיצה בשבת כדיני מחיצה בכלאים ולא כדיני מחיצה בסוכה ולא כדיני מחיצה בפני צואה לתפילה וכו' איברא וודאי שהכל נובע מיסוד דומה של דיני מחיצה ועל שחלק גדול מדיני מחיצה כמו בשאר דינים שבתורה נצרכים להבנת המציאויות לאשורם וכמו שכתב החזון איש בנוגע להלכה למשה מסיני בענינים אלו ומחלוקת בענין שנאמרה הלכה בצורה מסוימת המחייבת מציאות מסוימת ופירושה ע\"י חז\"ל נתונה להבנת ותפיסתו התורנית של כל חכם וחכם\u003c/p>"}, {"id": "901", "n": 54, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-104 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/מלאכת שבת רשויות עירובי חצירות תחומין.pdf / 02_קובץ_מאוחד/קובץ מאוחד - הקדמות - עותק 2.txt / 02_קובץ_מאוחד/קובץ מאוחד - עותק 1.docx ועוד\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ויש לשמוע מהנ\"ל שמהות השימוש ברשות הרבים (לדעת חכמים לכל הפחות) הוא שימוש בזכות כמו ברשות היחיד לעניין השימוש ...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>והנה שאין בדעתנו להעמיד הגדרת הרשויות על דיוקם רק נאמר שרשות היחיד מיועדת לשימושים פרטיים ולדיירים הנמצאים שם לשימושים אלו ורשות הרבים מיועדת לשימושים ציבוריים ולציבור המגיע לשם לעשות אותם והשינויים האמורים הם הסיבות לשינויים הדינים בתנאים ליצור רשות כזו\u003c/p>\u003cp>ומקום פטור מהותו בעצם שהוא חסר יעוד מסוים מחמת היותו בלתי ראוי לשימוש מגדיר או שאר סיבות המוזכרות דהינו שאין בתנאי המקום שלו שיעור להיות מקום מסוים ונפרד לעצמו\u003c/p>\u003cp>ואף שצורת הדברים הם שימוש הנותן למקום את הגדרתו קבעו חכמים שגם מקום שבגדרי מקום יש בו כח ליתן בו מהות אע\"פ שאינו מיועד לשימוש נחשב למקום בעל הגדרה אחרת והיא כרמלית\u003c/p>\u003cp>ומהות זו מוגדרת על ידי כמה תנאים והם התנאים הגשמיים המכינים אותה לשימוש היחיד והשימושים בה\u003c/p>\u003cp>התנאים הגשמיים הם בעיקר המחיצות שהם הגדרים המבדילים אותה מחמת היותה מוגדרת לעצמה ע\"י המחיצות הגשמיות שמבדיל אותה בדעת האדם ממקום אחר\u003c/p>\u003cp>והשימוש בה שמגדיר אותה כרשות היחיד ששימושיו הם שימושי היחיד הם בסוג השימושים והן במשתמשים\u003c/p>\u003cp>רשות הרבים כמשנ\"ת מיועדת לשימושים ציבוריים ולציבור המשתמש ומהות זו מוגדרת על ידי כמה תנאים והם התנאים הגשמיים המכינים אותה לשימוש הרבים והמשתמשים בה\u003c/p>\u003cp>ובזה יש להבחין האם רשות הרבים היא רשות מוגדרת למהותה או אי רשות וכן יש להבחין מהו שרשות הרבים עד עשרה טפחים אך הגדרה ממנה נעשית לרשות עד השמים\u003c/p>\u003cp>התנאים הגשמיים הם יכולת שטחה להכיל שימושי הרבים\u003c/p>\u003cp>והשימוש בה הם הימצאות המשתמשים בה וכו'\u003c/p>\u003cp>מקום פטור כמדומה שמעצם שמו נראה שאין זה רשות בעלת הגדרה חיובית שתנאיו רק שלא יהיה רשות היחיד ולא רשות הרבים וקראהו אוויר וכו' ואחרי חידוש דין כרמלית עוד נוסף בו שלא יהיה בעל שיעור מקום\u003c/p>\u003cp>רשות היחיד\u003c/p>\u003cp>דיני המחיצות מושתתים על ציווי התורה בדבר איזה מקום צריך להיות נחצץ ודעת האדם הרואה בהם חוצצים את המקום אותו אמרה התורה לחצוץ והנה אע\"פ שרשות היחיד תופסת עד הרקיע הלכה למשה מסיני הוא שהמקום הצריך חציצה הוא עד עשרה טפחים ובזה נלמד שהחציצה האמורה היא חציצה בפני החוץ לרשות התופס עד עשרה ואפילו שהמחיצות מהותם להגדיר את הרשות לעצמה ולא רק להבדיל אותה מחוצה לה ההבדלה מחוצה לה גורמת הגדרה לעצמה\u003c/p>\u003cp>שאר דיני המחיצות ומחלוקתם נוגעים בעיקר להגדרה מה נחשב גידור בעיני הרואה\u003c/p>\u003cp>דיני השימוש היות הרשות מיועדת לשימוש דירה ושלא יעבור בה דרך הרבים וכו' הם מחמת שהשימוש ואי השימוש המציאותי בה ומשמעותו יכול לעקר את המשמעות של הגידור שלה\u003c/p>\u003cp>רשות הרבים\u003c/p>\u003cp>התנאים הגשמיים כמו דיני רשויות הרגילים היות המקום ארבעה על ארבעה וכו' גם דיני השטח של רשות היחיד מוגדרים על הצורך שיהיה מקום זה ראוי לשימושים המוגדרים כשימושי הרבים\u003c/p>\u003cp>והשימוש בה אע\"פ שאין זה הלכה פסוקה שיהיו בה באיזה שהיא צורה ס' ריבוא ודאי זה מגדיר את הצורך שבאמת יהיה בה שימוש הרבים\u003c/p>\u003cp>בוא ונסדר דיני עירובין אשר למדנו זה הזמן מה שנראה לחשבן בעיקרי דיני מחיצות והנה מצאנו כמה דינים חלוקים מהם כתובים בתורה ובהלכה למשה מסיני\u003c/p>\u003cp>דיני מחיצה לכאורה נתחדשו בצורך הדיני להפריד בין מקומות רשויות וחפצים ואו שנאמר דין מחיצות עיקרו דאוריתא מה שכתוב בגמ' דף ג: דלר' יהודה גמרינן מארון וכפורת והנה לא נתברר מה הלימוד מן הארון אחר שאומר רש\"י שעיקר הלימוד הוא מזה שאין השכינה יורדת למטה מעשרה טפחים ומשמע שיש רשות תחתית וכו' והנה אין זה מעצם הדין דשיעור אמות דארון וכפורת רק שלדעת ר\"מ אין אפשרות ללמוד כיון שלדעתו ירדה שכינה אף למטה וכו' רק היות המושג שישנם בכל רשות חלוקה של עשרה טפחים\u003c/p>\u003cp>הגדרה של מחיצה היא הגדרה משתנה לפי הגדרת הנחצצים והגדרה קבועה של הגדרת מחיצה באשר היא היותה עומדת וראויה לחצוץ בפני ענינים וחלק גדול ממטרתנו הוא להגדיר האם דין מסוים נובע מסיבת הגדרת הנחצצים או שמא מסיבת הגדרת המחיצה וכדוגמא חלקי דינים הנובעים מן הגדרת המחיצה הן דיני חוזקה ודינים הנובעים מן הגדרת הנחצצים הן גודל רוחב המחיצה וכו'\u003c/p>\u003cp>ונביא בזאת רשימת דינים המוזכרים בפרקנו\u003c/p>\u003cp>ארבעה רשויות שני רשויות שבת רשות היחיד ורשות הרבים כרמלית ומקום פטור רשויות היחיד שונות כמו בית חצר ומבוי גג וקרפף להם ניתן דינים שונים\u003c/p>\u003cp>מחיצות כמה וכמה מושגים הנובעים מדיני מחיצות\u003c/p>\u003cp>מחיצה\u003c/p>\u003cp>עשרה טפחים\u003c/p>\u003cp>לבוד\u003c/p>\u003cp>גוד אחית\u003c/p>\u003cp>גוד אסיק\u003c/p>\u003cp>פסי ביראות\u003c/p>\u003cp>פי תקרה\u003c/p>\u003cp>פס ארבעה\u003c/p>\u003cp>לחי\u003c/p>\u003cp>קורה\u003c/p>\u003cp>עומד\u003c/p>\u003cp>מרובה\u003c/p>\u003cp>צורת הפתח\u003c/p>\u003cp>גידודי\u003c/p>\u003cp>גיפופי\u003c/p>\u003cp>בקעי ביה רבים\u003c/p>\u003cp>אתי אוירא\u003c/p>\u003cp>פרצה עשר\u003c/p>\u003cp>פרצה ארבעה\u003c/p>\u003cp>בקיעת גדי\u003c/p>\u003cp>דקירת גדי\u003c/p>\u003cp>פרוץ כעומד\u003c/p>\u003cp>פרוץ במלואו\u003c/p>\u003cp>מחיצה לד' טפחים\u003c/p>\u003cp>פתח\u003c/p>\u003cp>דופן\u003c/p>\u003cp>כותל\u003c/p>\u003cp>פרצה\u003c/p>\u003cp>מפולש\u003c/p>\u003cp>מקום חשוב\u003c/p>\u003cp>דרך רבים\u003c/p>\u003cp>והנה ע\"מ לנסות לסדר מעט את שלל הדינים האמורים נאמר נחלקם לפי עשית וצורת מחציה ופריצתה\u003c/p>\u003cp>דיני מחיצה וצורתה הם\u003c/p>\u003cp>שיעורה י' טפחים גובה\u003c/p>\u003cp>מושגים הנזכרים בדיני רשויות ומחיצות,\u003c/p>\u003cp>מושגים כללים\u003c/p>\u003cp>מקום חשוב - הגדרה המתייחסת למקום בעל חשיבות עצמית או נפרדת מהסובב לפי יכולת השימוש בו המושפעת מגודלו וכו'\u003c/p>\u003cp>והנה על אף שלמקום שנאמר עליו הדינים האמורים הם משפיעים עליו בדרכים שנות שהרי לא דיני מחיצה בשבת כדיני מחיצה בכלאים ולא כדיני מחיצה בסוכה ולא כדיני מחיצה בפני צואה לתפילה וכו' איברא וודאי שהכל נובע מיסוד דומה של דיני מחיצה ועל שחלק גדול מדיני מחיצה כמו בשאר דינים שבתורה נצרכים להבנת המציאויות לאשורם וכמו שכתב החזון איש בנוגע להלכה למשה מסיני בענינים אלו ומחלוקת בענין שנאמרה הלכה בצורה מסוימת המחייבת מציאות מסוימת ופירושה ע\"י חז\"ל נתונה להבנת ותפיסתו התורנית של כל חכם וחכם\u003c/p>\u003cp>וכהערה כללית בדיני מחיצות והל\"מ, שלהבדיל מההבנה המוטעית כאילו ההלכות גוד ולבוד ודופן עקומה הן כאילו חריגה מהתפיסה הרגילה את מושגי מחיצה, וזה אינו, כי הם השלמה לתפיסה האמיתית של מחיצות, כי הדינים האלו למרות שקיבלנו מסיני כקבלה ולא כסברא, הרי הם חלק ממכלול הגדר התורני של מחיצה ורשויות.\u003c/p>"}]};
